def one_touch_per_finger(config, environ) -> None:
    """Android (16.0): one touch per finger. SDL reports a finger twice, as
    a touch and as a mouse click made of it, and Kivy read both, so a tap
    could act twice (a switch flipped back; Send sent, then began a voice
    note). The copy is turned off in SDL and Kivy's mouse input dropped; a
    real mouse still works, as SDL makes touches of it on Android. Must run
    before the window is made."""
    environ.setdefault("SDL_TOUCH_MOUSE_EVENTS", "0")
    for key, value in config.items("input"):
        if value.split(",")[0].strip() == "mouse":
            config.remove_option("input", key)


if kivy_platform == "android":
    one_touch_per_finger(Config, os.environ)
# A tap's press shows for at least this long (16.0; Kivy's is 35 ms).
Config.set("graphics", "min_state_time", "0.12")

