#: v15.1: a theme (Settings › Appearance) is a look: its palettes for a
#: light and a dark phone (Axiom's dark may be on black), its text face and
#: capitals, a type scale that brings the face's x-height near the serif's
#: (and one for its capitals: Overclock's pixel capitals run wide), and how
#: far its corners round (Overclock's are cut nearly square).
#: Axiom is the app as it was.
THEME_SETS = {
    "axiom": {"label": "Axiom", "light": "light", "dark": "dark",
              "black": "black", "face": "FerritextSerif",
              "caps": "FerritextCaps", "type_scale": 1.0, "caps_scale": 1.0,
              "corner": 0},
    "overclock": {"label": "Overclock", "light": "overclock_day",
                  "dark": "overclock_night", "face": "FerritextMono",
                  "caps": "FerritextPixel", "type_scale": 0.82,
                  "caps_scale": 0.82, "corner": 2},
    "ferrite": {"label": "Ferrite", "light": "ferrite_light",
                "dark": "ferrite_dark", "face": "FerritextSans",
                "caps": "FerritextCaps", "type_scale": 0.88, "caps_scale": 1.0,
                "corner": 0},
}
#: The theme set each palette belongs to.
PALETTE_SET = {palette: key for key, look in THEME_SETS.items()
               for palette in (look["light"], look["dark"], look.get("black"))
               if palette}
#: Palettes drawn as a dark page (Overclock's day side is one).
DARK_PALETTES = {"dark", "black", "overclock_night", "overclock_day",
                 "ferrite_dark"}
#: Avatar colours, picked by address hash. Each carries a light initial at
#: >= 3:1 (initials are large text).
AVATAR_PALETTE = ["#3E5A8C", "#B4472E", "#3F7F73", "#A87A2A",
                  "#8E3B55", "#6E5238", "#4E7A45", "#6B3E6E"]


class _Tokens:
    """The live theme: `T.bg`, `T.text`, … — read when a widget is BUILT.
    Changing theme rebuilds the widget tree (FextApp.apply_appearance), so
    nothing has to repaint itself in place."""
    name = "dark"
    theme_set = "axiom"
    type_scale = caps_scale = 1.0
    corner_cap = 0

    def load(self, name: str) -> None:
        self.name = name if name in THEMES else "dark"
        for key, value in THEMES[self.name].items():
            setattr(self, key, value)
        self.theme_set = PALETTE_SET[self.name]
        look = THEME_SETS[self.theme_set]
        self.type_scale = look["type_scale"]
        self.caps_scale = look["caps_scale"]
        self.corner_cap = look["corner"]

    @property
    def dark(self) -> bool:
        return self.name in DARK_PALETTES


T = _Tokens()
#: The pre-9.1 colour names, kept as live aliases of the theme's tokens:
#: worker threads still post status colours by these names.
_COL_TOKENS = {
    "COL_BG": "bg", "COL_BG_LIST": "bg", "COL_CARD": "surface",
    "COL_CARD_EDGE": "rule", "COL_APPBAR": "bg", "COL_APPBAR_TEXT": "text",
    "COL_APPBAR_DIM": "text_3", "COL_BUBBLE_ME": "own",
    "COL_BUBBLE_PEER": "peer", "COL_TEXT": "text", "COL_TEXT_DIM": "text_3",
    "COL_ACCENT": "accent", "COL_ACCENT_DARK": "accent_press",
    "COL_DANGER": "alert", "COL_OK": "ok", "COL_TICK_GOLD": "tick",
    "COL_TICK_GREY": "tick_grey", "COL_PRESSED": "press",
    "COL_DIVIDER": "rule", "COL_QUOTE_ME": "quote_own",
    "COL_QUOTE_PEER": "quote_peer", "COL_SELECT_RGBA": "select",
}


def apply_theme(name: str) -> None:
    T.load(name)
    globals().update({alias: getattr(T, token)
                      for alias, token in _COL_TOKENS.items()})


def picture_palette() -> dict:
    """The colours over a call's picture (17.0): the dark side of the
    theme's set, in either theme. A picture can be any colour; light words
    on a dark band read over all of them."""
    return THEMES[THEME_SETS[T.theme_set]["dark"]]


def retint(hex_color: str) -> str:
    """The current theme's version of a colour another theme produced (a
    status line posted just before the theme changed)."""
    if not isinstance(hex_color, str):
        return hex_color
    for theme in THEMES.values():
        for token, value in theme.items():
            if value == hex_color:
                return getattr(T, token)
    return hex_color


apply_theme("dark")
# Declared here for readers and linters; apply_theme() keeps them current.
COL_BG = COL_BG_LIST = COL_APPBAR = T.bg
COL_CARD = COL_BUBBLE_PEER = T.surface
COL_CARD_EDGE = COL_DIVIDER = T.rule
COL_APPBAR_TEXT, COL_TEXT = T.text, T.text
COL_APPBAR_DIM = COL_TEXT_DIM = T.text_3
COL_BUBBLE_ME, COL_ACCENT, COL_ACCENT_DARK = T.own, T.accent, T.accent_press
COL_DANGER, COL_OK, COL_TICK_GOLD, COL_TICK_GREY = (T.alert, T.ok, T.tick,
                                                    T.tick_grey)
COL_PRESSED, COL_QUOTE_ME, COL_QUOTE_PEER = T.press, T.quote_own, T.quote_peer
COL_SELECT_RGBA = T.select


def C(hex_color: str) -> list:
    """Hex string -> kivy rgba. UI-side only; workers keep hex strings."""
    return get_color_from_hex(hex_color)


def corner(radius: float) -> float:
    """A corner's radius in the current theme set: Overclock cuts its
    corners nearly square (v15.1)."""
    return min(radius, dp(T.corner_cap)) if T.corner_cap else radius


def mix(a: str, b: str, t: float) -> str:
    """`a` moved a fraction `t` of the way to `b` (hex colours)."""
    a, b = a.lstrip("#"), b.lstrip("#")
    return "#" + "".join(
        f"{round(int(a[i:i + 2], 16) * (1 - t) + int(b[i:i + 2], 16) * t):02X}"
        for i in (0, 2, 4))


# ---- system appearance ------------------------------------------------------
def system_prefers_dark() -> Optional[bool]:
    """What the operating system is set to: True dark, False light, None
    when it cannot be told. FEXT_THEME=dark|light overrides (tests,
    screenshots)."""
    forced = os.environ.get("FEXT_THEME", "").lower()
    if forced in ("dark", "light"):
        return forced == "dark"
    try:
        if IS_ANDROID:
            autoclass, _ = _jni()
            activity = autoclass("org.kivy.android.PythonActivity").mActivity
            mode = activity.getResources().getConfiguration().uiMode
            return (mode & 0x30) == 0x20          # UI_MODE_NIGHT_YES
        if sys.platform == "win32":
            import winreg
            with winreg.OpenKey(winreg.HKEY_CURRENT_USER,
                                r"Software\Microsoft\Windows\CurrentVersion"
                                r"\Themes\Personalize") as key:
                return winreg.QueryValueEx(key, "AppsUseLightTheme")[0] == 0
        if sys.platform == "darwin":
            out = subprocess.run(["defaults", "read", "-g",
                                  "AppleInterfaceStyle"], capture_output=True,
                                 text=True, timeout=2)
            return "dark" in out.stdout.lower()
        out = subprocess.run(["gsettings", "get", "org.gnome.desktop.interface",
                              "color-scheme"], capture_output=True, text=True,
                             timeout=2)
        if out.returncode == 0 and out.stdout.strip():
            return "dark" in out.stdout
        out = subprocess.run(["gsettings", "get", "org.gnome.desktop.interface",
                              "gtk-theme"], capture_output=True, text=True,
                             timeout=2)
        if out.returncode == 0 and out.stdout.strip():
            return "dark" in out.stdout.lower()
    except Exception:
        pass
    return None


def system_reduces_motion() -> bool:
    """Android's 'Remove animations' sets the animator scale to 0."""
    if not IS_ANDROID:
        return False
    try:
        autoclass, _ = _jni()
        Global = autoclass("android.provider.Settings$Global")
        resolver = android_context().getContentResolver()
        return Global.getFloat(resolver, "animator_duration_scale", 1.0) == 0
    except Exception:
        return False


#: Multiplies every font size, on top of the system font scale that sp()
#: already applies.
TEXT_SCALES = (("small", N_("S"), 0.9), ("default", N_("M"), 1.0),
               ("large", N_("L"), 1.15), ("largest", N_("XL"), 1.3))
THEME_CHOICES = (("system", N_("System")), ("light", N_("Light")),
                 ("dark", N_("Dark")))


class _Appearance:
    mode = "system"                 # the user's choice: system/light/dark
    theme_set = "axiom"             # v15.1: the look (THEME_SETS)
    scale = 1.0
    reduce_motion = False
    edge_fade = True                # 18.1: lists fade at their edges

    def resolve(self) -> str:
        """Re-read the preferences and the system; returns the theme name."""
        prefs = load_prefs()
        self.mode = prefs.get("theme", "system")
        if self.mode not in ("system", "light", "dark"):
            self.mode = "system"
        self.theme_set = prefs.get("theme_set", "axiom")
        if self.theme_set not in THEME_SETS:
            self.theme_set = "axiom"
        self.scale = dict((k, s) for k, _l, s in TEXT_SCALES).get(
            prefs.get("text_size", "default"), 1.0)
        # Motion is on unless it is turned off in Settings: the fades are
        # what make moving between screens read as instant.
        self.reduce_motion = bool(prefs.get("reduce_motion", False))
        self.edge_fade = bool(prefs.get("edge_fade", True))
        # Black is the dark theme's default (v12); a choice of grey stays.
        self.black = bool(prefs.get("black", True))
        if self.mode != "system":
            return self.themed(self.mode == "dark")
        return self.themed(system_prefers_dark() is not False)

    black = True

    def themed(self, dark: bool) -> str:
        """The theme set's palette for a dark or light choice: Axiom's dark
        on a black page when Black background is on (v12)."""
        look = THEME_SETS[self.theme_set]
        if not dark:
            return look["light"]
        return look.get("black") if self.black and look.get("black") \
            else look["dark"]


APPEARANCE = _Appearance()


def fs(size: float) -> float:
    """A font size in sp, scaled by the user's text-size choice and the
    theme set's face (v15.1)."""
    return sp(size) * APPEARANCE.scale * T.type_scale


def motion(duration: float) -> float:
    """An animation's duration, or 0 when the user has asked for less."""
    return 0 if APPEARANCE.reduce_motion else duration


#: Screen-to-screen timing (seconds). Short on purpose: a layer appears
#: almost at once and the fade only smooths the change.
LAYER_IN, LAYER_OUT, LAYER_FADE = 0.16, 0.13, 0.11
SHEET_RISE, SHEET_FADE = 0.18, 0.12        # a sheet rising, its card fading in


# ---- type -------------------------------------------------------------------
# Kivy draws a label with ONE font file and has no fallback, so each theme
# set's face carries the emoji too (tools/build_fonts.py merges them). The
# set's face is registered under Kivy's default family name, so every Label
# and TextInput in the app — and in Kivy's own widgets — is set in it.
FONT_DIR = ASSET_DIR / "fonts"
#: Each face's files by style. Kivy neither slants nor emboldens a face, so
#: a style a face lacks is drawn in its nearest: italic upright, bold
#: italic bold.
FACES = {
    "FerritextSerif": {"fn_regular": "FerritextSerif-Regular.ttf",
                       "fn_italic": "FerritextSerif-Italic.ttf",
                       "fn_bold": "FerritextSerif-Bold.ttf",
                       "fn_bolditalic": "FerritextSerif-BoldItalic.ttf"},
    "FerritextMono": {"fn_regular": "FerritextMono-Regular.ttf",
                      "fn_bold": "FerritextMono-Bold.ttf",
                      "fn_bolditalic": "FerritextMono-Bold.ttf"},
    "FerritextSans": {"fn_regular": "FerritextSans-Regular.ttf",
                      "fn_bold": "FerritextSans-Bold.ttf",
                      "fn_bolditalic": "FerritextSans-Bold.ttf"},
}
SERIF_FILES = FACES["FerritextSerif"]
#: The capitals faces, shipped as they come: Titillium Web Light (as
#: supplied) and Silkscreen, Overclock's pixel capitals.
CAPS_FACES = {"FerritextCaps": "ui.ttf",
              "FerritextPixel": "Silkscreen-Regular.ttf"}
CAPS_FONT = FONT_DIR / "ui.ttf"
CAPS_FONT_NAME = "Roboto"
# v15.1: no theme's face has every script. Chinese, Japanese and Korean
# are in one face for every theme (Ferritext CJK), and every other script
# in everyday use in another (Ferritext World: Arabic, Hebrew, the scripts
# of India and South-East Asia, Georgian, Armenian, Ethiopic, with Latin,
# Greek and Cyrillic; tools/build_fonts.py). Kivy draws a label in one
# face, so a label whose face lacks a character of its text is drawn
# wholly in the first of these that has them all (_resolve_font_name). A
# text field decides for all its lines at once (InkTextInput), so that it
# is measured in the face it is drawn in.
#: Chinese, Japanese and Korean: their characters, punctuation and
#: full-width forms.
CJK_TEXT = re.compile("[\u3000-\u30ff\u3130-\u318f\u3400-\u4dbf"
                      "\u4e00-\u9fff\uac00-\ud7af\uf900-\ufaff"
                      "\uff00-\uffef]")
#: The faces for what a theme's face lacks, in the order they are tried.
SCRIPT_FACES = (("FerritextCJK", "FerritextCJK-Regular.ttf"),
                ("FerritextWorld", "FerritextWorld-Regular.ttf"))
#: name -> file of each script face present (register_fonts).
SCRIPT_FILES: dict = {}


def register_fonts(theme_set: str = "axiom") -> bool:
    """Make the theme set's face Kivy's default family and its capitals
    face CAPS_FONT_NAME; every face stays registered by its own name. A set
    whose files are missing is drawn in Axiom's."""
    global CAPS_FONT_NAME
    faces = {}
    for name, files in FACES.items():
        paths = {k: FONT_DIR / v for k, v in files.items()}
        if all(p.is_file() for p in paths.values()):
            faces[name] = {k: str(p) for k, p in paths.items()}
            LabelBase.register(name, **faces[name])
    look = THEME_SETS[theme_set]
    face = faces.get(look["face"]) or faces.get("FerritextSerif")
    if face:
        LabelBase.register("Roboto", **face)
    else:
        log.warning("bundled fonts missing from %s — using Kivy's", FONT_DIR)
    caps = {name: FONT_DIR / file for name, file in CAPS_FACES.items()
            if (FONT_DIR / file).is_file()}
    for name, path in caps.items():
        LabelBase.register(name, str(path))
    CAPS_FONT_NAME = look["caps"] if look["caps"] in caps else (
        "FerritextCaps" if caps.get("FerritextCaps") else "Roboto")
    for name, file in SCRIPT_FACES:
        if (FONT_DIR / file).is_file():
            SCRIPT_FILES[name] = str(FONT_DIR / file)
            LabelBase.register(name, SCRIPT_FILES[name])
    return face is not None


register_fonts()


_FONT_CHARACTERS: dict = {}


def font_characters(path: str) -> frozenset:
    """The characters a font file has glyphs for, by its cmap: the format
    12 table where there is one (ours have one, for their emoji), else
    the format 4 table. Read once a file."""
    found = _FONT_CHARACTERS.get(path)
    if found is not None:
        return found
    chars, cmap, tables = set(), b"", {}
    try:
        with open(path, "rb") as f:
            count = struct.unpack(">H", f.read(12)[4:6])[0]
            records = f.read(16 * count)
            for i in range(0, 16 * count, 16):
                tag, _sum, at, size = struct.unpack(">4sIII",
                                                    records[i:i + 16])
                if tag == b"cmap":
                    f.seek(at)
                    cmap = f.read(size)
        for i in range(struct.unpack(">H", cmap[2:4])[0]):
            at = struct.unpack(">I", cmap[8 + 8 * i:12 + 8 * i])[0]
            tables.setdefault(struct.unpack(">H", cmap[at:at + 2])[0], at)
        if 12 in tables:                    # groups: first, last, glyph
            at = tables[12]
            groups = struct.unpack(">I", cmap[at + 12:at + 16])[0]
            for g in range(at + 16, at + 16 + 12 * groups, 12):
                first, last = struct.unpack(">II", cmap[g:g + 8])
                chars.update(range(first, last + 1))
        elif 4 in tables:                   # segments of the BMP
            at = tables[4]
            n = struct.unpack(">H", cmap[at + 6:at + 8])[0] // 2
            ends, starts, deltas, offsets = (
                struct.unpack(f">{n}{kind}", cmap[a:a + 2 * n])
                for kind, a in (("H", at + 14), ("H", at + 16 + 2 * n),
                                ("h", at + 16 + 4 * n),
                                ("H", at + 16 + 6 * n)))
            for k in range(n):
                for c in range(starts[k], min(ends[k], 0xFFFE) + 1):
                    glyph = c
                    if offsets[k]:          # through the glyph id array
                        g = at + 16 + 6 * n + 2 * k + offsets[k] + \
                            2 * (c - starts[k])
                        glyph = struct.unpack(">H", cmap[g:g + 2])[0]
                    if glyph and (glyph + deltas[k]) & 0xFFFF:
                        chars.add(c)
    except (OSError, struct.error):
        log.warning("could not read the characters of %s", path)
    found = _FONT_CHARACTERS[path] = frozenset(chars)
    return found


def _drawn(ch: str) -> bool:
    """Whether a character needs a glyph: not a control, a format mark
    (joiners, direction marks) or a variation selector."""
    return unicodedata.category(ch)[0] != "C" and \
        not 0xFE00 <= ord(ch) <= 0xFE0F and not 0xE0100 <= ord(ch) <= 0xE01EF


def script_face(text: str, own: Optional[str] = None) -> Optional[str]:
    """The face to draw `text` in when its own face (by default the
    theme's) lacks some of its characters: the first of SCRIPT_FACES that
    has them all, else the one that has most; None to keep its own."""
    if not text or text.isascii():
        return None
    return _script_face(text, own or LabelBase._fonts.get("Roboto", ("",))[0])


@functools.lru_cache(maxsize=512)       # a label asks again as it redraws
def _script_face(text: str, own: str) -> Optional[str]:
    lacking = {cp for cp in set(map(ord, text)) - font_characters(own)
               if _drawn(chr(cp))}
    best, most = None, 0
    for name, _file in SCRIPT_FACES:
        if lacking and name in SCRIPT_FILES:
            has = len(lacking & font_characters(SCRIPT_FILES[name]))
            if has == len(lacking):
                return name
            if has > most:
                best, most = name, has
    return best


_kivy_resolve_font_name = LabelBase.resolve_font_name


def _resolve_font_name(label) -> None:
    """Kivy's choice of font file, then ours: a face that has every
    character, and the script HarfBuzz is to shape it as."""
    _kivy_resolve_font_name(label)
    options = label.options
    face = script_face(label.text, options["font_name_r"])
    if face:
        options["font_name_r"] = SCRIPT_FILES[face]
    options["font_script_name"] = shaping_script(label.text)


LabelBase.resolve_font_name = _resolve_font_name

# ---- light text on a computer's screen (16.0) ---------------------------------
# Kivy blends a glyph's soft edges in sRGB, which draws light strokes on a
# dark ground thinner than they are. On a computer's screen (density under
# LIFT_BELOW) the serif's hairlines faded: "hard to read, though the right
# size" (Windows, dark theme). There the edges of text lighter than the
# page are lifted, as a system's own text renderer does; dark text, which
# sRGB blending already darkens, and every phone's denser screen are left
# as they were.
TEXT_LIFT, LIFT_BELOW = 1.45, 1.75
_LIFT_TABLE = bytes(round(255 * (v / 255) ** (1 / TEXT_LIFT))
                    for v in range(256))
_kivy_render_end = CoreLabel._render_end


def _lightness(rgb) -> float:
    return .2126 * rgb[0] + .7152 * rgb[1] + .0722 * rgb[2]


def _render_end(label):
    data = _kivy_render_end(label)
    if data is not None and data.width > 1 and \
            Metrics.density < LIFT_BELOW and \
            _lightness(label.options["color"]) > _lightness(C(T.bg)) + .1:
        level = data.mipmaps[0]             # [w, h, rgba bytes, rowlength]
        pixels = bytearray(level[2])
        pixels[3::4] = pixels[3::4].translate(_LIFT_TABLE)   # the alpha
        level[2] = bytes(pixels)
    return data


CoreLabel._render_end = _render_end

# What HarfBuzz must be told to join Arabic's letters, form the scripts of
# India's clusters and stack South-East Asia's marks: SDL_ttf shapes a
# label as the script it is set to, and Kivy sets Latin.
#: ISO 15924 code: the blocks of a script that needs shaping.
SHAPED_SCRIPTS = (
    ("Hebr", "\u0590-\u05ff\ufb1d-\ufb4f"),
    ("Arab", "\u0600-\u06ff\u0750-\u077f\u0870-\u08ff\ufb50-\ufdff"
             "\ufe70-\ufeff"),
    ("Thaa", "\u0780-\u07bf"),
    ("Deva", "\u0900-\u097f\ua8e0-\ua8ff"),
    ("Beng", "\u0980-\u09ff"),
    ("Guru", "\u0a00-\u0a7f"),
    ("Gujr", "\u0a80-\u0aff"),
    ("Orya", "\u0b00-\u0b7f"),
    ("Taml", "\u0b80-\u0bff"),
    ("Telu", "\u0c00-\u0c7f"),
    ("Knda", "\u0c80-\u0cff"),
    ("Mlym", "\u0d00-\u0d7f"),
    ("Sinh", "\u0d80-\u0dff"),
    ("Thai", "\u0e00-\u0e7f"),
    ("Laoo", "\u0e80-\u0eff"),
    ("Tibt", "\u0f00-\u0fff"),
    ("Mymr", "\u1000-\u109f\ua9e0-\ua9ff\uaa60-\uaa7f"),
    ("Khmr", "\u1780-\u17ff\u19e0-\u19ff"),
)
_SHAPED = re.compile("[" + "".join(b for _c, b in SHAPED_SCRIPTS) + "]")
_SCRIPT_OF = [(code, re.compile(f"[{blocks}]"))
              for code, blocks in SHAPED_SCRIPTS]


def shaping_script(text: str) -> str:
    """The script a text is shaped as: the first in it that needs it, or
    Latin (Kivy's)."""
    found = None if text.isascii() else _SHAPED.search(text)
    if not found:
        return "Latn"
    return next(code for code, blocks in _SCRIPT_OF
                if blocks.match(found.group()))

# Kivy breaks a line only at a space. A run with none, as a Chinese
# sentence is (and a Thai, Lao, Khmer or Burmese one: their words are not
# spaced either), it cuts wherever the room runs out, so a full stop could
# start a line, an opening bracket end one, or a vowel be parted from its
# letter. A wrapped label whose text has those scripts is broken into
# lines here first, by the rules Chinese and Japanese type keeps, and the
# others between syllables (between words would take a dictionary); Kivy
# lays out the lines it is given.
#: Scripts written without spaces between words.
UNSPACED_TEXT = re.compile(CJK_TEXT.pattern[:-1] +
                           "\u0e00-\u0eff\u1000-\u109f\u1780-\u17ff]")
#: What may not start a line, and what may not end one: CJK's closing and
#: opening punctuation, and the vowels of Thai and Lao written after their
#: letter, and before it.
NO_LINE_START = frozenset("，。、；：？！）］｝〕〉》」』】〗〙”’…‥—・·ー々"
                          "ぁぃぅぇぉっゃゅょゎァィゥェォッャュョヮヵヶ"
                          "!%),.:;?]}" "ะาำๅๆฯະາຳໆ")
NO_LINE_END = frozenset("（［｛〔〈《「『【〖〘“‘([{" "เแโใไເແໂໃໄ")
#: Khmer's and Burmese's signs that set the next letter under this one.
_STACKS = frozenset("\u17d2\u1039")
#: The vowel signs and marks of the unspaced scripts, which stay with
#: the letter before them.
_MARKS = frozenset(chr(cp) for start, end in ((0x0E00, 0x0EFF),
                                              (0x1000, 0x109F),
                                              (0x1780, 0x17FF),
                                              (0x3000, 0x30FF))
                   for cp in range(start, end + 1)
                   if unicodedata.category(chr(cp))[0] == "M")
_PIECE = re.compile(" +|\n|" + UNSPACED_TEXT.pattern + "|[^ \n" +
                    UNSPACED_TEXT.pattern[1:-1] + "]+")
_MARKUP_TAG = re.compile(r"(\[.*?\])")


def line_pieces(text: str) -> list:
    """What a line may break between: each CJK character and each
    syllable of the other unspaced scripts, each other word, each run of
    spaces and each line break; with a mark held to its letter, a letter
    stacked under another held to it, and the punctuation that may not
    start (or end) a line held to the piece before (or after) it."""
    pieces, hold = [], False
    for piece in _PIECE.findall(text):
        word = not piece.isspace()
        if pieces and word and (hold or piece[0] in NO_LINE_START or
                                piece[0] in _MARKS):
            pieces[-1] += piece
        else:
            pieces.append(piece)
        hold = word and (piece[-1] in NO_LINE_END or piece[-1] in _STACKS)
    return pieces


def line_breaks(text: str, width: float, extent) -> list:
    """Where `text` must break to fit `width`, as `extent` (a text's
    (width, height)) measures: each break's (start, end), which takes in
    the spaces ending its line. A piece wider than a whole line is left
    on its own, for Kivy to cut."""
    breaks, line, at = [], "", 0
    for piece in line_pieces(text):
        if piece == "\n":
            line = ""
        elif line.strip() and not piece.isspace() and \
                extent(line + piece)[0] > width:
            breaks.append((at - len(line) + len(line.rstrip(" ")), at))
            line = piece
        else:
            line += piece
        at += len(piece)
    return breaks


def break_lines(text: str, width: float, extent,
                markup: bool = False) -> str:
    """`text` with a line break wherever line_breaks puts one. In markup
    the lines are measured without the tags, and a break goes in after
    any tag at its place."""
    parts = _MARKUP_TAG.split(text) if markup else [text]
    shown, place, at = "", [], 0         # place: each shown character's
    for i, part in enumerate(parts):     # index in `text`
        if i % 2 == 0:
            shown += part
            place += range(at, at + len(part))
        at += len(part)
    place.append(at)
    out, done = "", 0
    for start, end in line_breaks(shown, width, extent):
        start, end = place[start], place[end]
        if text[start:end].strip(" "):      # a tag among the spaces
            start = end
        out += text[done:start] + "\n"
        done = end
    return out + text[done:]


# ---- right to left (15.1) ---------------------------------------------------
# Kivy lays a line out left to right, in the order its characters are
# stored. Arabic and Hebrew run right to left, and a number or a Latin word
# in them left to right, so each line is first put in the order it is
# shown, by the Unicode bidirectional algorithm (UAX #9; explicit
# embeddings and isolates are taken as neutral). HarfBuzz still joins
# Arabic's letters as they are read: told that text in a right-to-left
# script runs left to right, it takes it as already in display order.
#: Hebrew, Arabic, Syriac, Thaana, N'Ko and the rest of their blocks,
#: their presentation forms, and the right-to-left mark.
RTL_TEXT = re.compile("[\u0590-\u08ff\u200f\ufb1d-\ufdff\ufe70-\ufefe"
                      "\U00010800-\U00010fff\U0001e800-\U0001efff]")
_STRONG = ("L", "R", "AL")
_NEUTRAL = frozenset(("B", "S", "WS", "ON"))
_EXPLICIT = frozenset(("LRE", "RLE", "LRO", "RLO", "PDF", "LRI", "RLI",
                       "FSI", "PDI"))
#: Bracket pairs (BidiBrackets.txt, those in everyday use); U+2329 and
#: U+232A are the same brackets as U+3008 and U+3009.
BRACKETS = {"(": ")", "[": "]", "{": "}", "\u2045": "\u2046",
            "\u3008": "\u3009", "\u300a": "\u300b", "\u300c": "\u300d",
            "\u300e": "\u300f", "\u3010": "\u3011", "\u3014": "\u3015",
            "\uff08": "\uff09", "\uff3b": "\uff3d", "\uff5b": "\uff5d"}
_SAME_BRACKET = {"\u2329": "\u3008", "\u232a": "\u3009"}
#: What a character becomes where text runs right to left (the everyday
#: pairs of BidiMirroring.txt).
MIRRORED = {**BRACKETS, **{v: k for k, v in BRACKETS.items()},
            "<": ">", ">": "<", "\u00ab": "\u00bb", "\u00bb": "\u00ab",
            "\u2039": "\u203a", "\u203a": "\u2039", "\u2264": "\u2265",
            "\u2265": "\u2264", "\u2329": "\u232a", "\u232a": "\u2329"}


def _as_strong(kind: str) -> str:
    return "R" if kind in ("R", "AL", "EN", "AN") else kind


def bidi_levels(text: str, base: Optional[int] = None) -> tuple:
    """(the paragraph's level, each character's) for one paragraph: 0 for
    left to right, 1 for right to left, 2 for left to right inside right
    to left. `base` sets the paragraph's; by default its first strong
    character does (P2, P3). Rule names are UAX #9's."""
    classes = [unicodedata.bidirectional(ch) or "L" for ch in text]
    if base is None:
        base = next((int(c != "L") for c in classes if c in _STRONG), 0)
    sos = "R" if base else "L"
    n, types, prev = len(text), [], sos
    for c in classes:                    # W1: marks are what they follow
        if c in ("NSM", "BN") or c in _EXPLICIT:
            c = "ON" if c == "NSM" and prev in _EXPLICIT else prev
        types.append(c)
        prev = c
    last = sos
    for i, t in enumerate(types):        # W2: digits after Arabic letters
        if t in _STRONG:
            last = t
        elif t == "EN" and last == "AL":
            types[i] = "AN"
    types = ["R" if t == "AL" else t for t in types]                # W3
    for i in range(1, n - 1):            # W4: separators inside numbers
        a, t, b = types[i - 1], types[i], types[i + 1]
        if t == "ES" and a == b == "EN" or \
                t == "CS" and a == b and a in ("EN", "AN"):
            types[i] = a
    i = 0
    while i < n:                         # W5: terminators by a number
        j = i
        while j < n and types[j] == "ET":
            j += 1
        if j > i and (i and types[i - 1] == "EN" or
                      j < n and types[j] == "EN"):
            types[i:j] = ["EN"] * (j - i)
        i = max(j, i + 1)
    types = ["ON" if t in ("ES", "ET", "CS") else t for t in types]  # W6
    last = sos
    for i, t in enumerate(types):        # W7: digits after Latin
        if t in ("L", "R"):
            last = t
        elif t == "EN" and last == "L":
            types[i] = "L"
    _pair_brackets(text, classes, types, sos)                      # N0
    i = 0
    while i < n:                         # N1, N2: runs of neutrals
        j = i
        while j < n and types[j] in _NEUTRAL:
            j += 1
        if j > i:
            before = _as_strong(types[i - 1]) if i else sos
            after = _as_strong(types[j]) if j < n else sos
            types[i:j] = [before if before == after else sos] * (j - i)
        i = max(j, i + 1)
    if base:                                                    # I1, I2
        return base, [2 if t in ("L", "EN", "AN") else 1 for t in types]
    return base, [1 if t == "R" else 2 if t in ("EN", "AN") else 0
                  for t in types]


def _pair_brackets(text: str, classes: list, types: list, sos: str) -> None:
    """N0: a pair of brackets takes the direction of what it holds when
    that is the paragraph's, or when the text before them has it too."""
    closing = {v: k for k, v in BRACKETS.items()}
    stack, pairs = [], []
    for i, ch in enumerate(text):
        ch = _SAME_BRACKET.get(ch, ch)
        if types[i] != "ON":
            continue
        if ch in BRACKETS:
            if len(stack) == 63:
                break
            stack.append((BRACKETS[ch], i))
        elif ch in closing:
            for k in range(len(stack) - 1, -1, -1):
                if stack[k][0] == ch:
                    pairs.append((stack[k][1], i))
                    del stack[k:]
                    break
    for start, end in sorted(pairs):
        inside = {_as_strong(t) for t in types[start + 1:end]} & {"L", "R"}
        if not inside:
            continue
        side = sos
        if sos not in inside:
            side = next((_as_strong(t) for t in reversed(types[:start])
                         if _as_strong(t) in ("L", "R")), sos)
        for k in (start, end):           # with any marks that follow
            types[k] = side
            k += 1
            while k < len(text) and classes[k] == "NSM":
                types[k] = side
                k += 1


def _continues(text: str, i: int) -> bool:
    """Whether text[i] belongs with the character before it, as HarfBuzz
    groups them: a mark, a joiner and the emoji it joins, a skin tone, a
    flag's second letter, a tag."""
    cp = ord(text[i])
    if unicodedata.category(text[i])[0] == "M" or cp == 0x200D or \
            0x1F3FB <= cp <= 0x1F3FF or 0xE0020 <= cp <= 0xE007F:
        return True
    if text[i - 1] == "\u200d":
        return unicodedata.category(text[i]) == "So"
    return 0x1F1E6 <= cp <= 0x1F1FF and 0x1F1E6 <= ord(text[i - 1]) <= \
        0x1F1FF and not _continues(text, i - 1)


def display_order(text: str, levels: list, base: int) -> list:
    """The indices of one line's characters in the order they are shown
    (L1 to L3): whitespace ending the line at the paragraph's level, runs
    reversed from the highest level down, and each cluster (_continues)
    kept in its own order."""
    levels = list(levels)
    trailing = True
    for i in range(len(text) - 1, -1, -1):                        # L1
        kind = unicodedata.bidirectional(text[i])
        if kind in ("S", "B"):
            levels[i], trailing = base, True
        elif trailing and (kind in ("WS", "BN") or kind in _EXPLICIT):
            levels[i] = base
        else:
            trailing = False
    groups = []
    for i in range(len(text)):                                    # L3
        if groups and _continues(text, i):
            groups[-1].append(i)
        else:
            groups.append([i])
    top = max(levels, default=0)
    lowest = min((v for v in levels if v % 2), default=top + 1)
    for level in range(top, lowest - 1, -1):                      # L2
        i = 0
        while i < len(groups):
            j = i
            while j < len(groups) and levels[groups[j][0]] >= level:
                j += 1
            groups[i:j] = groups[i:j][::-1]
            i = max(j, i + 1)
    return [i for group in groups for i in group]


def starts_rtl(text: str) -> bool:
    """Whether the first character of `text` with a direction runs right
    to left (P2)."""
    if not RTL_TEXT.search(text):
        return False
    return next((unicodedata.bidirectional(ch) for ch in text
                 if unicodedata.bidirectional(ch) in _STRONG), "L") != "L"


def shown_line(text: str) -> str:
    """One line as it is shown: in display order, and mirrored where it
    runs right to left (L4)."""
    base, levels = bidi_levels(text)
    return "".join(MIRRORED.get(text[i], text[i]) if levels[i] % 2
                   else text[i] for i in display_order(text, levels, base))


def _markup_runs(text: str) -> list:
    """Kivy markup as runs of (the tags open on it, their closing tags,
    its plain text)."""
    runs, open_tags = [], []
    for i, part in enumerate(_MARKUP_TAG.split(text)):
        if i % 2:
            name = part[1:-1].split("=", 1)[0]
            names = [n for n, _tag in open_tags]
            if not name.startswith("/"):
                open_tags.append((name, part))
            elif name[1:] in names:
                del open_tags[len(names) - 1 - names[::-1].index(name[1:])]
        elif part:
            runs.append(("".join(tag for _n, tag in open_tags),
                         "".join(f"[/{n}]" for n, _t in reversed(open_tags)),
                         part.replace("&bl;", "[").replace("&br;", "]")
                         .replace("&amp;", "&")))
    return runs or [("", "", "")]


def _fitting(text: str, width: float, extent) -> int:
    """How many of `text`'s characters fit `width` with an ellipsis after
    them, never parting a cluster."""
    low, high = 0, len(text)
    while low < high:
        mid = (low + high + 1) // 2
        if extent(text[:mid].rstrip() + "\u2026")[0] <= width:
            low = mid
        else:
            high = mid - 1
    while 0 < low < len(text) and _continues(text, low):
        low -= 1
    return low


def display_text(text: str, width: Optional[float], extent,
                 markup: bool = False, one_line: bool = False) -> tuple:
    """(`text` as it is shown, whether it begins right to left): broken
    into lines that fit `width` in reading order (line_breaks), then each
    line in display order; on one line, shortened at the end it is read
    to, with an ellipsis. In markup, each piece of text keeps its tags."""
    runs = _markup_runs(text) if markup else [("", "", text)]
    shown = "".join(run[2] for run in runs)
    owner = [k for k, run in enumerate(runs) for _ch in run[2]]
    breaks = []
    if one_line:
        shown = shown.replace("\n", " ")
        if width and extent(shown)[0] > width:
            shown = shown[:_fitting(shown, width, extent)].rstrip()
            owner = owner[:len(shown)] + [owner[max(len(shown) - 1, 0)]]
            shown += "\u2026"
    elif width:
        breaks = line_breaks(shown, width, extent)

    def line(start: int, end: int, at: int, base: int, levels: list):
        """One line in display order, each piece of it in its tags."""
        pieces = []                     # [run, text] in the order shown
        for i in display_order(shown[start:end], levels[start - at:end - at],
                               base):
            ch = shown[start + i]
            if levels[start - at + i] % 2:
                ch = MIRRORED.get(ch, ch)
            if pieces and pieces[-1][0] == owner[start + i]:
                pieces[-1][1] += ch
            else:
                pieces.append([owner[start + i], ch])
        if not markup:
            return "".join(piece for _run, piece in pieces)
        return "".join(runs[run][0] + escape_markup(piece) + runs[run][1]
                       for run, piece in pieces)

    lines, at, rtl = [], 0, None
    for paragraph in shown.split("\n"):
        end = at + len(paragraph)
        base, levels = bidi_levels(paragraph)
        rtl = base if rtl is None else rtl
        start = at
        while breaks and breaks[0][0] <= end:
            cut, resume = breaks.pop(0)
            lines.append(line(start, cut, at, base, levels))
            start = resume
        lines.append(line(start, end, at, base, levels))
        at = end + 1
    return "\n".join(lines), bool(rtl)


try:
    from kivy.core.text._text_sdl2 import _SurfaceContainer
except ImportError:                     # another text library: left as is
    _SurfaceContainer = None


def _shape_as(label, script: str, direction: str = "ltr") -> None:
    """Set the script and direction the label's font is shaped in. SDL_ttf
    keeps one of each for each open font, set when it draws and used too
    when it measures: drawing a space sets them. The label's own options
    are left as they were."""
    if _SurfaceContainer is None:
        return
    options = label.options
    own = options["font_script_name"], options["font_direction"]
    options["font_script_name"], options["font_direction"] = script, direction
    try:
        _SurfaceContainer(1, 1).render(label, " ", 0, 0)
    except Exception:
        log.debug("could not set the font's script", exc_info=True)
    finally:
        options["font_script_name"], options["font_direction"] = own


def _laid_out(label, text: str, script: str) -> str:
    """The text Kivy is to lay out: right to left put in display order
    (display_text), an unspaced script broken into lines (break_lines),
    else as it is. A right-to-left paragraph that wraps lines up on the
    right."""
    options, width = label.options, label.text_size[0]
    markup = isinstance(label, MarkupLabel)
    one_line = options["shorten"] or options.get("max_lines") == 1
    left, _top, right, _bottom = options["padding"]
    room = width - left - right if width else None
    if RTL_TEXT.search(text):
        _shape_as(label, script, "rtl")      # measured in reading order
        try:
            shown, rtl = display_text(text, room, label.get_cached_extents(),
                                      markup, one_line)
        finally:
            _shape_as(label, script)          # Kivy measures what is shown
        if rtl and room and not one_line and options["halign"] == "left":
            options["halign"], label._fext_rtl = "right", True
        return shown
    if room and not one_line and UNSPACED_TEXT.search(text) and not (
            markup and re.search(r"&|\[/?(size|font)", text)):
        return break_lines(text, room, label.get_cached_extents(), markup)
    return text


def _breaking_lines(render):
    """Kivy's `render`, whose first pass lays the text out and second
    draws it, for the text _laid_out gives. Around both, the label's font
    is set to shape in the label's script, and back to Latin after, as
    every other label expects to find it."""
    def breaking(label, real: bool = False):
        text, options = label.text, label.options
        if not real and getattr(label, "_fext_rtl", False):
            options["halign"], label._fext_rtl = "left", False  # its own
        if text.isascii():
            return render(label, real)
        script = options["font_script_name"]
        if script != "Latn":
            _shape_as(label, script)
        try:
            shown = text if real else _laid_out(label, text, script)
            if shown == text:
                return render(label, real)
            label.text = shown
            try:
                return render(label, real)
            finally:
                label.text = text
        finally:
            if script != "Latn":
                _shape_as(label, "Latn")
    return breaking


LabelBase.render = _breaking_lines(LabelBase.render)
MarkupLabel.render = _breaking_lines(MarkupLabel.render)


def use_theme(name: str) -> None:
    """Apply a palette, and the face and capitals of its theme set."""
    apply_theme(name)
    register_fonts(T.theme_set)


# =============================================================================
#  Small shared utilities (DRY helpers)
# =============================================================================
def b64e(raw: bytes) -> str:
    return base64.b64encode(raw).decode("ascii")


def b64d(text: str) -> bytes:
    return base64.b64decode(text.encode("ascii"), validate=True)


def sha256_hex(raw: bytes) -> str:
    return hashlib.sha256(raw).hexdigest()


def now_iso() -> str:
    return datetime.now(timezone.utc).isoformat()


def stamp_seconds(value) -> Optional[float]:
    """An ISO 8601 time (as sanitize_stamp takes it) in seconds since
    1970, UTC where it names no zone; None if it is not one."""
    stamp = sanitize_stamp(value, "")
    if not stamp:
        return None
    at = datetime.fromisoformat(stamp[:-1] + "+00:00"
                                if stamp.endswith("Z") else stamp)
    return (at if at.tzinfo else at.replace(tzinfo=timezone.utc)).timestamp()


def sanitize_stamp(value, fallback: str) -> str:
    """A time as a sender or the relay gave it, if it is one — ISO 8601,
    at most 40 characters — and `fallback` otherwise (v12). It is signed
    along with the message, but signed is not the same as well-formed: a
    list or a number there made the message impossible to store, so it was
    never acknowledged and came back on every connect."""
    if isinstance(value, str) and 10 <= len(value) <= 40:
        try:
            datetime.fromisoformat(value[:-1] + "+00:00"
                                   if value.endswith("Z") else value)
            return value
        except ValueError:
            pass
    return fallback


def short_addr(address: str, n: int = 12) -> str:
    return f"{address[:n]}…" if len(address) > n else address


def person_name(contact: Optional[dict], address: str, n: int = 14) -> str:
    """A contact as the screens name them: their username, or the start of
    their address; "Deleted User" while the relay says it has no one there
    (16.0: a relay reset, an account gone — LocalStore.set_gone)."""
    contact = contact or {}
    if contact.get("gone"):
        return tr("Deleted User")
    return contact.get("username") or short_addr(address, n)


def single_line_text(text: str, limit: int) -> str:
    """`text` on one line, cut to `limit` characters with an ellipsis."""
    flat = " ".join(str(text or "").split())
    return flat if len(flat) <= limit else flat[:limit - 1].rstrip() + "…"


def message_text(msg: dict) -> str:
    """The words of a message, as a person would quote them: a photo's
    caption, nothing for a voice or video message, the body otherwise."""
    kind = msg.get("kind") or "text"
    if kind in MEDIA_MIME:
        try:
            ext = json.loads(msg.get("ext") or "{}")
        except (TypeError, ValueError):
            ext = {}
        media = ext.get("media") if isinstance(ext, dict) else None
        return (media or {}).get("cap", "") if kind == "image" else ""
    return msg.get("body", "")


_CONTROL_CHARS = re.compile(r"[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]")


def sanitize_text(text: str) -> str:
    """Client-side input sanitization for outgoing messages: strips dangerous
    control characters (keeps \\n and \\t), trims edges, enforces a hard
    length cap. SQL injection is separately impossible because both the local
    store and the server use parameterized queries exclusively."""
    if not isinstance(text, str):
        return ""
    text = _CONTROL_CHARS.sub("", text)
    text = text.strip()
    return text[:MAX_MESSAGE_CHARS]


_TOKEN_RE = re.compile(r"^[A-Za-z0-9_-]{1,64}$")
_HEX64_RE = re.compile(r"^[0-9a-f]{64}$")


def _str(value, limit: int) -> Optional[str]:
    return value[:limit] if isinstance(value, str) else None


def _int(value, low: int, high: int) -> Optional[int]:
    if isinstance(value, bool) or not isinstance(value, int):
        return None
    return value if low <= value <= high else None


def sanitize_media(media) -> Optional[dict]:
    """Validate a peer-supplied media reference field by field.

    The block it came in is authenticated, but authenticated is not the same
    as well-formed: a buggy or hostile client can sign anything. Every field
    is type-checked and bounded before it reaches the database or the
    screen, and anything unrecognised is dropped rather than passed through.
    """
    if not isinstance(media, dict):
        return None
    kind = media.get("kind")
    if not isinstance(kind, str) or kind not in MEDIA_MIME:
        return None
    blob, sha = _str(media.get("blob"), 64), _str(media.get("sha"), 64)
    mime = _str(media.get("mime"), 40)
    size = _int(media.get("size"), 1, MAX_MEDIA_BYTES)
    try:
        key_ok = len(b64d(media.get("key", ""))) == 32
    except (TypeError, ValueError):
        key_ok = False
    if not (blob and _TOKEN_RE.match(blob) and sha and _HEX64_RE.match(sha)
            and mime in MEDIA_MIME[kind] and size and key_ok):
        return None
    out = {"kind": kind, "blob": blob, "sha": sha, "mime": mime,
           "size": size, "key": media["key"]}
    for field, low, high in (("w", 1, 20000), ("h", 1, 20000),
                             ("dur", 0, MAX_VOICE_SECONDS * 1000 + 999)):
        value = _int(media.get(field), low, high)
        if value is not None:
            out[field] = value
    for field, limit in (("thumb", 24000), ("wave", 400)):
        value = _str(media.get(field), limit + 1)
        if value is not None and len(value) <= limit:
            try:
                b64d(value)
                out[field] = value
            except (TypeError, ValueError):
                pass
    caption = _str(media.get("cap"), 1000)
    if caption:
        out["cap"] = sanitize_text(caption)
    return out


# ---- v11: links -------------------------------------------------------------------
# Links in messages can be opened (after saying where they lead). Previews
# are off unless turned on in Settings; then the SENDER's phone fetches a
# link's page as the message is written — its title, a line about it, its
# site, a small picture — and the preview travels inside the message, so
# the person reading never touches the site. Only public addresses are
# fetched, a little of each page, and nothing is fetched to show one.
_URL_RE = re.compile(r"https?://[^\s<>\"'`]+", re.IGNORECASE)
PREVIEW_PAGE_BYTES = 512 * 1024
PREVIEW_IMAGE_BYTES = 1024 * 1024
PREVIEW_THUMB_EDGE = 160


_OPENS = {")": "(", "]": "[", "}": "{"}


def _trim_link(found: str) -> str:
    """A link without the punctuation after it: 'see https://a.b/c.' ends
    at c, and a closing bracket stays only if the link opened one."""
    url = found
    while url:
        end = url[-1]
        if end in ".,;:!?'\">":
            url = url[:-1]
        elif end in _OPENS and url.count(end) > url.count(_OPENS[end]):
            url = url[:-1]
        else:
            break
    return url


def link_spans(text: str) -> list:
    """(start, end, url) for each link in some text, in order."""
    out = []
    for found in _URL_RE.finditer(text or ""):
        url = _trim_link(found.group(0))
        if len(url) > len("https://"):
            out.append((found.start(), found.start() + len(url), url))
    return out[:32]


def links_in(text: str) -> list:
    """The http(s) links in some text, in order, each once."""
    out = []
    for _start, _end, url in link_spans(text):
        if url not in out:
            out.append(url)
    return out[:8]


def link_host(url: str) -> str:
    """The site a link leads to, as it really is. A name written in
    letters borrowed from other alphabets (to pass for another site) shows
    its plain xn-- form beside it; a site's name put before an @ is not
    taken for the site, which is the one after it."""
    from urllib.parse import urlsplit
    try:
        host = (urlsplit(url).hostname or "").rstrip(".")
    except ValueError:
        host = ""
    if not host:
        return url
    try:
        plain = host.encode("idna").decode("ascii")
    except UnicodeError:
        plain = host
    try:
        shown = plain.encode("ascii").decode("idna")
    except UnicodeError:
        shown = host
    return f"{shown}  ({plain})" if shown != plain else plain


def link_warning(url: str) -> str:
    """What to know about a link before opening it ('' if nothing)."""
    import ipaddress
    from urllib.parse import urlsplit
    try:
        parts = urlsplit(url)
        host = parts.hostname or ""
    except ValueError:
        return tr("This link is malformed.")
    notes = []
    if "xn--" in link_host(url):
        notes.append(tr("Its name is spelled with letters from other "
                        "alphabets — it may be dressed up as another site."))
    try:
        ipaddress.ip_address(host)
        notes.append(tr("It names no site, only a number."))
    except ValueError:
        pass
    if parts.username is not None:
        notes.append(tr("Text before an @ in a link is not where it leads."))
    if parts.scheme == "http":
        notes.append(tr("Not encrypted: the network on the way can read "
                        "and change the page."))
    return " ".join(notes)


def link_markup(text: str, spans: list, color: str) -> str:
    """Text as Kivy markup, each link in `color`, underlined, and a ref
    (its index in `spans`) that a tap can find."""
    out, at = [], 0
    for i, (start, end, _url) in enumerate(spans):
        out.append(escape_markup(text[at:start]))
        out.append(f"[ref={i}][color={color}][u]"
                   f"{escape_markup(text[start:end])}[/u][/color][/ref]")
        at = end
    out.append(escape_markup(text[at:]))
    return "".join(out)


def link_previews_enabled() -> bool:
    return bool(load_prefs().get("link_previews", False))


def _public_addresses(host: str) -> list:
    """Every address a host name has, if all of them are public ones, else
    []: a preview never reaches into the phone's own network."""
    import ipaddress
    try:
        infos = socket.getaddrinfo(host, None, proto=socket.IPPROTO_TCP)
    except (OSError, UnicodeError):
        return []
    found = []
    for info in infos:
        try:
            address = ipaddress.ip_address(info[4][0].split("%")[0])
        except ValueError:
            return []
        if not address.is_global:
            return []
        if str(address) not in found:
            found.append(str(address))
    return found


def _public_host(host: str) -> bool:
    return bool(_public_addresses(host))


def _opened(raw: bytes, encoding: str, limit: int) -> Optional[bytes]:
    """A body as the site sent it, opened to at most `limit` bytes. Pages
    are asked for uncompressed; one compressed anyway is opened only that
    far, so a small download cannot swell into a huge one."""
    import zlib
    encoding = (encoding or "").strip().lower()
    if encoding in ("", "identity"):
        return raw[:limit]
    if encoding in ("gzip", "x-gzip"):
        tries = (16 + zlib.MAX_WBITS,)
    elif encoding == "deflate":
        tries = (zlib.MAX_WBITS, -zlib.MAX_WBITS)
    else:
        return None
    for wbits in tries:
        try:
            return zlib.decompressobj(wbits).decompress(raw, limit)
        except zlib.error:
            continue
    return None


def _fetch_capped(url: str, limit: int, accept: str) -> Optional[tuple]:
    """(final url, content type, at most `limit` bytes) — following no
    more than three redirects, each to a public address — or None.

    The connection is made to an address that was checked, never to the
    name looked up again: a name can answer with a public address first
    and a private one a moment later, and so reach into the network this
    device is on. Proxies are not used: the check is of where the page is.
    """
    from urllib.parse import urljoin, urlsplit
    import urllib3
    for _hop in range(4):
        try:
            parts = urlsplit(url)
            host = (parts.hostname or "").rstrip(".")
            name = host.encode("idna").decode("ascii") if host else ""
            port = parts.port
        except (ValueError, UnicodeError):
            return None
        if parts.scheme not in ("http", "https") or not name:
            return None
        addresses = _public_addresses(name)
        if not addresses:
            return None
        secure = parts.scheme == "https"
        default = 443 if secure else 80
        port = port or default
        shown = f"[{name}]" if ":" in name else name
        headers = {"Host": shown if port == default else f"{shown}:{port}",
                   "User-Agent": "Mozilla/5.0 (link preview)",
                   "Accept": accept, "Accept-Encoding": "identity"}
        target = (parts.path or "/") + (f"?{parts.query}" if parts.query
                                        else "")
        r = pool = None
        for address in addresses[:4]:
            options = {"timeout": urllib3.Timeout(connect=3, read=4),
                       "retries": False, "maxsize": 1}
            if secure:
                import certifi
                pool = urllib3.HTTPSConnectionPool(
                    address, port, cert_reqs="CERT_REQUIRED",
                    ca_certs=certifi.where(), server_hostname=name,
                    assert_hostname=name, **options)
            else:
                pool = urllib3.HTTPConnectionPool(address, port, **options)
            try:
                r = pool.urlopen("GET", target, headers=headers,
                                 redirect=False, preload_content=False,
                                 decode_content=False)
                break
            except urllib3.exceptions.ConnectTimeoutError:
                pool.close()          # not reached there: try the next one
            except (urllib3.exceptions.HTTPError, OSError, ValueError):
                pool.close()
                return None
        if r is None:
            return None
        try:
            if r.status in (301, 302, 303, 307, 308):
                location = r.headers.get("location", "")
                if not location:
                    return None
                url = urljoin(url, location)
                continue
            if r.status != 200:
                return None
            data = _opened(r.read(limit, decode_content=False),
                           r.headers.get("content-encoding", ""), limit)
            if data is None:
                return None
            return url, r.headers.get("content-type", ""), data
        except (urllib3.exceptions.HTTPError, OSError, ValueError):
            return None
        finally:
            r.close()
            pool.close()
    return None


def _page_meta(page: str) -> dict:
    """og: and twitter: properties, and the <title>, of an HTML page. Each
    search runs once over the page: a page made of endless unclosed tags
    costs no more to read than any other."""
    import html as _html
    meta = {}
    for tag in re.findall(r"<meta\b[^>]{0,2000}>", page,
                          re.IGNORECASE)[:300]:
        attrs = dict((k.lower(), _html.unescape(v2 or v1))
                     for k, v1, v2 in re.findall(
                         r'([a-zA-Z:_-]+)\s*=\s*(?:"([^"]*)"|\'([^\']*)\')',
                         tag))
        key = (attrs.get("property") or attrs.get("name") or "").lower()
        if key and "content" in attrs and key not in meta:
            meta[key] = attrs["content"].strip()
    start = re.search(r"<title\b", page, re.IGNORECASE)
    opened = page.find(">", start.end()) if start else -1
    close = re.compile(r"</title\s*>", re.IGNORECASE).search(page, opened) \
        if opened >= 0 else None
    if close:
        meta.setdefault("title",
                        _html.unescape(page[opened + 1:close.start()]).strip())
    return meta


def fetch_link_preview(url: str) -> Optional[dict]:
    """{u, t, d, s, i}: a link's title, description, site and a small
    JPEG (base64) — fetched by the sender's phone, or None."""
    from urllib.parse import urljoin, urlsplit
    got = _fetch_capped(url, PREVIEW_PAGE_BYTES, "text/html")
    if got is None or "html" not in got[1].lower():
        return None
    final, ctype, data = got
    charset = re.search(r"charset=([\w-]+)", ctype)
    try:
        page = data.decode(charset.group(1) if charset else "utf-8",
                           "replace")
    except LookupError:                 # a character set Python lacks
        page = data.decode("utf-8", "replace")
    meta = _page_meta(page)
    title = meta.get("og:title") or meta.get("twitter:title") or \
        meta.get("title") or ""
    if not title:
        return None
    out = {"u": url, "t": single_line_text(title, 200),
           "d": single_line_text(meta.get("og:description") or
                                 meta.get("description") or "", 300),
           "s": single_line_text(meta.get("og:site_name") or
                                 (urlsplit(final).hostname or ""), 80)}
    image = meta.get("og:image") or meta.get("twitter:image")
    if image:
        picture = _fetch_capped(urljoin(final, image), PREVIEW_IMAGE_BYTES,
                                "image/*")
        im = open_foreign_image(picture[2], PREVIEW_THUMB_EDGE) \
            if picture is not None else None
        if im is not None:
            import io as _io
            buf = _io.BytesIO()
            im.save(buf, "JPEG", quality=60, optimize=True)
            if buf.tell() <= 16 * 1024:
                out["i"] = b64e(buf.getvalue())
    return out


def sanitize_preview(lp, body: str) -> Optional[dict]:
    """A link preview someone sent, field by field: for a link that is in
    the message itself, short texts, and a small real JPEG."""
    if not isinstance(lp, dict):
        return None
    url = _str(lp.get("u"), 2000)
    if not url or url not in links_in(body):
        return None
    out = {"u": url}
    for key, limit in (("t", 200), ("d", 300), ("s", 80)):
        text = _str(lp.get(key), limit)
        if text:
            out[key] = single_line_text(sanitize_text(text), limit)
    if "t" not in out:
        return None
    thumb = _str(lp.get("i"), 24000)
    if thumb:
        try:
            raw = b64d(thumb)
            if raw[:3] == b"\xff\xd8\xff" and len(raw) <= 16 * 1024:
                out["i"] = thumb
        except (TypeError, ValueError):
            pass
    return out


def open_url(url: str) -> None:
    """The phone's or computer's browser, at `url`: a web link, and
    nothing else (18.1: never a file, or another app's own kind of link,
    whoever asks)."""
    if not re.match(r"https?://", url or "", re.IGNORECASE):
        raise ValueError("not a web link")
    if IS_ANDROID:
        autoclass, _ = _jni()
        Intent = autoclass("android.content.Intent")
        intent = Intent(Intent.ACTION_VIEW,
                        autoclass("android.net.Uri").parse(url))
        intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
        android_context().startActivity(intent)
        return
    import webbrowser
    webbrowser.open(url)


def sanitize_ext(x) -> dict:
    """The parts of a peer's extension block we keep: reply quote, forwarded
    mark, automatic-reply mark (18.1), media reference. Routing fields
    (to/cid/xv/k) are consumed by the sync layer and never stored."""
    out = {}
    if not isinstance(x, dict):
        return out
    reply = x.get("reply")
    if isinstance(reply, dict):
        quoted = {}
        cid = _str(reply.get("cid"), 64)
        if cid and _TOKEN_RE.match(cid):
            quoted["cid"] = cid
        snip = _str(reply.get("snip"), 300)
        if snip:
            quoted["snip"] = sanitize_text(snip)[:300]
        author = _str(reply.get("from"), 64)
        if author and valid_address(author):
            quoted["from"] = author
        if reply.get("kind") in ("text", *MEDIA_MIME):
            quoted["kind"] = reply["kind"]
        if quoted:
            out["reply"] = quoted
    if x.get("fwd") in (1, True):
        out["fwd"] = 1
    if x.get("auto") in (1, True):
        out["auto"] = 1                       # 18.1 (AWAY): an away reply
    media = sanitize_media(x.get("media"))
    if media:
        out["media"] = media
    mentions = sanitize_mentions(x.get("mn"))
    if mentions:
        out["mn"] = mentions
    plan = sanitize_plan(x.get("plan"))
    if plan is not None:
        out["plan"] = plan                    # 17.2: a planned call
    topic = sanitize_topic_id(x.get("tp"))
    if topic:
        out["tp"] = topic                     # 17.4: in a group's topic
    return out


#: 17.2 (SCHEDULE): a message kept on this device until its time (ext.at),
#: drawn with its clock; not in the outbox until then.
MSG_SCHEDULED = -2
#: A planned call's card offers Join from this long before its time...
PLAN_EARLY = 10 * 60
#: ...until this long after it; its reminder comes this long before.
PLAN_LATE, PLAN_REMIND = 2 * 3600, 5 * 60


def sanitize_plan(raw) -> Optional[dict]:
    """A planned call (x.plan, 17.2): its id, its time, voice or video."""
    if not isinstance(raw, dict):
        return None
    pid = _str(raw.get("id"), 32)
    at = _int(raw.get("at"), 1, 2 ** 40)
    if not pid or not _CALL_ID_RE.match(pid) or at is None:
        return None
    return {"id": pid, "at": at, "v": raw.get("v") is True}


def plan_state(plan: dict, now: Optional[float] = None) -> str:
    """'soon' (more than PLAN_EARLY ahead), 'open' (Join), or 'past'."""
    now = time.time() if now is None else now
    if now < plan["at"] - PLAN_EARLY:
        return "soon"
    return "open" if now <= plan["at"] + PLAN_LATE else "past"


def send_later_choices(now: Optional[float] = None) -> list:
    """Send later's times (17.2): (label, Unix time), from now on."""
    now = time.time() if now is None else now
    day = datetime.fromtimestamp(now).replace(hour=0, minute=0, second=0,
                                               microsecond=0)
    evening = (day + timedelta(hours=20)).timestamp()
    tomorrow = day + timedelta(days=1)
    out = [(tr("In an hour"), now + 3600)]
    if evening - now > 30 * 60:
        out.append((tr("This evening, 20:00"), evening))
    out += [(tr("Tomorrow, 09:00"), (tomorrow + timedelta(hours=9))
             .timestamp()),
            (tr("Tomorrow, 20:00"), (tomorrow + timedelta(hours=20))
             .timestamp())]
    return out


def parse_send_time(text: str, now: Optional[float] = None
                    ) -> Optional[float]:
    """A time typed as 'YYYY-MM-DD HH:MM' or 'HH:MM' (today, or tomorrow
    if that is past), in this device's time; None if it is not one or is
    not ahead."""
    now = time.time() if now is None else now
    text = (text or "").strip()
    try:
        if len(text) <= 5:
            hour, minute = (int(p) for p in text.split(":"))
            base = datetime.fromtimestamp(now).replace(
                hour=hour, minute=minute, second=0, microsecond=0)
            at = base.timestamp()
            at = at if at > now else (base + timedelta(days=1)).timestamp()
        else:
            at = datetime.strptime(text, "%Y-%m-%d %H:%M").timestamp()
    except ValueError:
        return None
    return at if at > now + 30 else None


#: The most people one group message can mention (16.2, I7).
MENTIONS_MAX = 32
#: "@" and the start of a name, at the end of what is written (the composer
#: offers the group's members whose names begin so).
MENTION_TYPED = re.compile(r"(?:^|\s)@([^\s@]{0,32})$")


def sanitize_mentions(value) -> list:
    """The addresses a group message mentions (x.mn, 16.2), as sent: each
    a valid address, once, at most MENTIONS_MAX."""
    if not isinstance(value, list):
        return []
    seen = []
    for item in value[:MENTIONS_MAX]:
        if isinstance(item, str) and valid_address(item) and \
                item not in seen:
            seen.append(item)
    return seen


def sanitize_ext_with_body(x, body: str) -> dict:
    """sanitize_ext, plus what can only be checked against the text: a
    link preview (v11) must be of a link the message holds."""
    out = sanitize_ext(x)
    preview = sanitize_preview(x.get("lp"), body) if isinstance(x, dict) \
        else None
    if preview:
        out["lp"] = preview
    return out


# ---- v9.1 groups and reactions ----------------------------------------------
# A group is a list of members that every member keeps; the relay never knows
# one exists. A group message travels as one ordinary 1:1 envelope per
# member, each carrying {"grp": {"id", "v"}} in its signed extension block,
# so it is as end-to-end encrypted, recipient-bound and replay-proof as a
# direct message. Membership changes are signed control messages from the
# group's admin, applied only when their version is newer.
GROUP_PREFIX = "g:"            # messages.peer for a group's conversation
MAX_GROUP_MEMBERS = 32         # pairwise fan-out: one send per member
MAX_GROUP_NAME = 64
_GID_RE = re.compile(r"^[0-9a-f]{32}$")
#: Offered first in the reaction strip, in this order.
QUICK_REACTIONS = ("\U0001F44D", "\u2764\ufe0f", "\U0001F602", "\U0001F62E",
                   "\U0001F622", "\U0001F64F")
#: v12: how many reactions one person may give one message. A fourth
#: replaces the oldest.
MAX_REACTIONS = 3


def group_peer(gid: str) -> str:
    return GROUP_PREFIX + gid


def gid_of(peer: Optional[str]) -> Optional[str]:
    """The group id behind a conversation key, or None for a direct chat."""
    if isinstance(peer, str) and peer.startswith(GROUP_PREFIX):
        gid = peer[len(GROUP_PREFIX):]
        return gid if _GID_RE.match(gid) else None
    return None


def sanitize_gid(value) -> Optional[str]:
    return value if isinstance(value, str) and _GID_RE.match(value) else None


def sanitize_emoji(value) -> Optional[str]:
    """A reaction: one emoji, which may be a sequence (skin tone, flag,
    ZWJ family) of up to 16 code points. '' means "take it back". Anything
    containing ASCII, letters, spaces or control characters is refused, so
    a reaction can never smuggle text onto someone's screen."""
    if value == "":
        return ""
    if not isinstance(value, str) or not 1 <= len(value) <= 16:
        return None
    for ch in value:
        o = ord(ch)
        if o < 0xa0 or ch.isspace() or ch.isalpha() or ch.isdigit():
            return None
    if all(ch in "\u200d\ufe0f\ufe0e" for ch in value):
        return None
    return value


def sanitize_reactions(value) -> Optional[list]:
    """v12: all of someone's reactions to a message (a react control's
    'es'), oldest first: a list of at most MAX_REACTIONS emoji, each as
    sanitize_emoji takes it, none twice; [] takes them all back. Refused
    whole (None) if it is anything else."""
    if not isinstance(value, list) or len(value) > MAX_REACTIONS:
        return None
    emojis = [sanitize_emoji(e) for e in value]
    if any(not e for e in emojis) or len(set(emojis)) != len(emojis):
        return None
    return emojis


def sanitize_group_state(raw) -> Optional[dict]:
    """Validate a peer-supplied group state, refusing it whole if any part
    is wrong. Every member's address must be the hash of the key given for
    it, so nobody can put a key of their choosing under someone else's
    address and read that person's share of the group's messages."""
    if not isinstance(raw, dict):
        return None
    gid = sanitize_gid(raw.get("id"))
    name = sanitize_text(_str(raw.get("name"), 400) or "")[:MAX_GROUP_NAME]
    version = _int(raw.get("v"), 1, 2 ** 31 - 1)
    admin = _str(raw.get("admin"), 64)
    members = raw.get("members")
    if not (gid and name.strip() and version and admin and
            isinstance(members, list) and
            2 <= len(members) <= MAX_GROUP_MEMBERS):
        return None
    out, seen = [], set()
    for member in members:
        if not isinstance(member, dict):
            return None
        address = _str(member.get("a"), 64)
        key = (_str(member.get("k"), 66) or "").lower()
        if not address or address in seen or not valid_address(address):
            return None
        try:
            pub = bytes.fromhex(key)
            compressed_to_pub(pub)
        except ValueError:
            return None
        if address_from_pub_bytes(pub) != address:
            return None
        username = _str(member.get("u"), 32)
        entry = {"a": address, "k": key}
        if username and valid_username(username):
            entry["u"] = username
        out.append(entry)
        seen.add(address)
    if admin not in seen:
        return None
    state = {"id": gid, "name": name.strip(), "v": version, "admin": admin,
             "members": out}
    admins = sanitize_group_admins(raw.get("ad"), seen, admin)
    if admins:
        state["ad"] = admins                   # 18.0: its other admins
    log = sanitize_admin_log(raw.get("lg"))
    if log:
        state["lg"] = log                      # 18.0: what admins did
    rules = sanitize_group_rules(raw.get("r"),
                                 seen - {admin} - set(admins))
    if rules:
        state["r"] = rules                     # 17.4: what members may do
    topics = sanitize_group_topics(raw.get("tp"))
    if topics:
        state["tp"] = topics                   # 17.4: its topics
    return state


# ---- 17.4: a group's topics ------------------------------------------------------
# A group's admin may divide it into topics, each a thread of its own
# beside General (every message that names none). The list rides in the
# group's state ("tp": {"on", "list": [{"id", "n", "c"}]}), set
# by the admin alone; a message names its topic in x.tp. The chat shows one
# topic, or all of them with each message's topic beside its author. Turned
# off, nothing is lost: every message shows in the one chat with its topic's
# name, and the list is kept, so turning topics on again brings each back. A
# closed topic ("c") takes new messages from the admin alone. An app before
# 17.4 shows the one chat, as ever, and writes to General.
MAX_TOPICS = 32
MAX_TOPIC_NAME = 48
_TOPIC_RE = re.compile(r"^[0-9a-f]{8}$")


def sanitize_topic_id(value) -> str:
    """A topic's id (8 hex), or "" (General) for anything else."""
    return value if isinstance(value, str) and _TOPIC_RE.match(value) else ""


def sanitize_group_topics(raw) -> dict:
    """A group's topics (17.4) as a state gives them: {} for none, else
    {"on": bool, "list": [{"id", "n", "c"}]}: ids unique, names cleaned, at
    most MAX_TOPICS; anything else left out."""
    if not isinstance(raw, dict) or not isinstance(raw.get("list"), list):
        return {}
    kept, seen = [], set()
    for entry in raw["list"][:MAX_TOPICS]:
        if not isinstance(entry, dict):
            continue
        tid = sanitize_topic_id(entry.get("id"))
        name = sanitize_text(_str(entry.get("n"), 200) or "")
        name = name[:MAX_TOPIC_NAME].strip()
        if tid and name and tid not in seen:
            kept.append({"id": tid, "n": name, "c": entry.get("c") is True})
            seen.add(tid)
    if not kept and raw.get("on") is not True:
        return {}
    return {"on": raw.get("on") is True, "list": kept}


def topic_names(group: Optional[dict]) -> dict:
    """id -> name of a group's topics (17.4), on or off."""
    return {t["id"]: t["n"] for t in
            ((group or {}).get("topics") or {}).get("list", [])}


# ---- 17.4: what a group's members may do ------------------------------------
# Defaults for every member, and a restriction on one: the admin may turn
# off, for every member but themselves, sending messages, sending photos
# and voice messages, or starting calls; or stop one member doing any of
# those, for a while or until lifted. The rules ride in the group's state
# ("r"), so only its admin sets them and every member's app keeps them. The
# sender's app does not send what they stop; each receiver holds what is
# sent anyway (by an app before 17.4, or one that has not heard yet), judged
# by when the relay took it, so what waited on the relay from before a stop
# still arrives. Joining a call, reacting and deleting one's own messages
# are never stopped. Times are the relay's (ApiClient.relay_now), so every
# member's app agrees on them whatever its own clock says.
#
#   "r": {"deny": {right: since, ...},                        every member
#         "lim": {address: {"deny": [right, ...], "at": since,
#                           "until": its end, or 0}}}         one member
GROUP_RIGHTS = ("send", "media", "calls")
#: What each right stops, as a sentence's noun ("your {what}").
GROUP_RIGHT_WORDS = {"send": N_("messages"),
                     "media": N_("photos, voice and video messages"),
                     "calls": N_("new calls")}
#: How long a restriction lasts, as the admin chooses (0: until lifted).
GROUP_LIMITS = ((3600, N_("An hour")), (86400, N_("A day")),
                (7 * 86400, N_("A week")), (0, N_("No end")))


def _relay_time(value) -> Optional[float]:
    """A time in the relay's seconds, as a peer's rules give it, or None."""
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        return None
    return float(value) if 0 < value < 4e9 else None


def sanitize_group_rules(raw, members) -> dict:
    """A group's rules (17.4) as a state gives them, keeping what holds
    together: known rights, times the relay could have given, and
    restrictions of `members` (its admin is never one). The rest is left
    out, not guessed. {} is "no rules"."""
    if not isinstance(raw, dict):
        return {}
    out = {}
    deny = raw.get("deny") if isinstance(raw.get("deny"), dict) else {}
    off = {right: _relay_time(deny.get(right)) for right in GROUP_RIGHTS}
    off = {right: at for right, at in off.items() if at is not None}
    if off:
        out["deny"] = off
    lim = raw.get("lim") if isinstance(raw.get("lim"), dict) else {}
    kept = {}
    for address, entry in lim.items():
        if address not in members or not isinstance(entry, dict) or \
                not isinstance(entry.get("deny"), list):
            continue
        rights = [r for r in GROUP_RIGHTS if r in entry["deny"]]
        at = _relay_time(entry.get("at"))
        until = entry.get("until")
        until = 0.0 if until == 0 else _relay_time(until)
        if rights and at is not None and until is not None and \
                (not until or until > at):
            kept[address] = {"deny": rights, "at": at, "until": until}
    if kept:
        out["lim"] = kept
    if raw.get("pin") is True:          # 19.0: members may pin messages
        out["pin"] = True
    return out


def group_may_pin(group: Optional[dict], who: str) -> bool:
    """19.0 (PINS26): may `who` pin and unpin in `group`, a stored row?
    Its owner and the admins who may change its name and photo; every
    member too where its rules say so ("pin")."""
    if not group or group.get("state") != "active":
        return False
    if group_can(group, who, "info"):
        return True
    return bool((group.get("rules") or {}).get("pin")) and \
        who in {m["a"] for m in group.get("members") or []}


def pin_line(msg: dict) -> str:
    """A pinned message in one line: its first words, or its kind."""
    text = message_text(msg).strip()
    if text:
        return text.splitlines()[0]
    return tr(QUOTE_NAMES.get(msg.get("kind"), N_("Message")))


def group_denied(rules: dict, admins: set, who: str, right: str,
                 at: float) -> Optional[tuple]:
    """Did a group's rules stop `who` doing `right` at `at` (the relay's
    time)? None if not; else (the right that stopped it, when that ends —
    0 for "when the admin says" — and whether it is `who`'s own
    restriction). Photos and voice messages stop with messages; no admin
    (18.0: of `admins`, every admin of the group) is ever stopped."""
    if not rules or who in admins:
        return None
    rights = ("send", "media") if right == "media" else (right,)
    deny = rules.get("deny") or {}
    for r in rights:
        if r in deny and at >= deny[r]:
            return r, 0.0, False
    entry = (rules.get("lim") or {}).get(who)
    if entry and entry["at"] <= at and \
            (not entry["until"] or at < entry["until"]):
        for r in rights:
            if r in entry["deny"]:
                return r, entry["until"], True
    return None


def group_rights_words(rights) -> str:
    """'messages, new calls': what `rights` stop, in GROUP_RIGHTS' order."""
    return ", ".join(tr(GROUP_RIGHT_WORDS[r]) for r in GROUP_RIGHTS
                     if r in rights)


# ---- 18.0: a group's admins ---------------------------------------------------
# Beside its owner (its maker, or the next member should they leave; the
# state's "admin"), a group may have other admins, each with some of an
# admin's rights. They ride in the state ("ad": {address: {"r":
# [rights], "by": who made them admin}}), with a log of what every admin did
# ("lg": the newest ADMIN_LOG_MAX entries {"v", "a", "e", "t", "at"}). An app
# takes a new state from any admin of the state it holds whose rights cover
# every change in it (admin_change_allowed); two at the same version are
# settled alike on every phone (state_wins). Apps before 18.0 follow the
# owner alone.
ADMIN_RIGHTS = ("info", "add", "remove", "rules", "topics", "delete",
                "admins")
ADMIN_RIGHT_WORDS = {
    "info": N_("Change the group's name, photo and timer"),
    "add": N_("Add members"),
    "remove": N_("Remove members"),
    "rules": N_("Set what members can do, and restrict them"),
    "topics": N_("Manage topics"),
    "delete": N_("Delete members' messages"),
    "admins": N_("Make admins, with rights of their own"),
}
ADMIN_LOG_MAX = 50
#: What an admin log entry says was done ("t": its member, name or count).
ADMIN_LOG_EVENTS = ("name", "photo", "timer", "add", "remove", "rules",
                    "restrict", "topics", "admin", "rights", "unadmin",
                    "delete")


def sanitize_group_admins(raw, members: set, owner: str) -> dict:
    """A state's other admins: {address: {"r": [rights], "by": address}},
    each a member but the owner, with known rights in ADMIN_RIGHTS' order;
    anything else left out."""
    if not isinstance(raw, dict):
        return {}
    out = {}
    for address, entry in list(raw.items())[:MAX_GROUP_MEMBERS]:
        if address not in members or address == owner or \
                not isinstance(entry, dict) or \
                not isinstance(entry.get("r"), list):
            continue
        rights = [r for r in ADMIN_RIGHTS if r in entry["r"]]
        by = entry.get("by")
        if rights:
            out[address] = {"r": rights,
                            "by": by if by in members else owner}
    return out


def sanitize_admin_log(raw) -> list:
    """A state's admin log: at most ADMIN_LOG_MAX entries {"v", "a", "e",
    "at"} (and "t", a member's address, a name or a count), oldest first;
    anything malformed left out."""
    if not isinstance(raw, list):
        return []
    out = []
    for entry in raw[-ADMIN_LOG_MAX:]:
        if not isinstance(entry, dict):
            continue
        version = _int(entry.get("v"), 1, 2 ** 31 - 1)
        who = _str(entry.get("a"), 64)
        at = _relay_time(entry.get("at"))
        if not (version and who and valid_address(who) and at and
                entry.get("e") in ADMIN_LOG_EVENTS):
            continue
        item = {"v": version, "a": who, "e": entry["e"], "at": at}
        target = sanitize_text(_str(entry.get("t"), 80) or "").strip()
        if target:
            item["t"] = target
        out.append(item)
    return out


def group_admins(group: Optional[dict]) -> set:
    """Every admin of a group as this phone holds it: its owner and the
    others."""
    if not group:
        return set()
    return {group["admin"]} | set(group.get("admins") or {})


def group_can(group: Optional[dict], who: str, right: str) -> bool:
    """May `who` do `right` (one of ADMIN_RIGHTS) in `group`, a stored row?
    Its owner may do everything; another admin, what their rights say."""
    if not group:
        return False
    if who == group["admin"]:
        return True
    entry = (group.get("admins") or {}).get(who)
    return bool(entry) and right in entry["r"]


#: What an admin log entry says, by its event ({member}: whom it names).
ADMIN_LOG_WORDS = {
    "name": N_("{who} renamed the group “{group}”"),
    "photo": N_("{who} changed the group's photo"),
    "add": N_("{who} added {members}"),
    "remove": N_("{who} removed {member}"),
    "rules": N_("{who} changed what members can do"),
    "restrict": N_("{who} changed {member}'s restriction"),
    "topics": N_("{who} changed the topics"),
    "admin": N_("{who} made {member} an admin"),
    "rights": N_("{who} changed {member}'s rights as an admin"),
    "unadmin": N_("{who} removed {member} as an admin"),
    "delete": N_("{who} deleted {member}'s messages"),
}
#: ...those whose member is this device's person, said to them.
ADMIN_LOG_YOU = {
    "restrict": N_("{who} changed your restriction"),
    "rights": N_("{who} changed your rights as an admin"),
    "delete": N_("{who} deleted your messages"),
}


def admin_log_line(entry: dict, name: Callable[[str, bool], str],
                   me: str = "") -> str:
    """18.0: what an admin log entry says, to `me`; `name(address, start)`
    names someone (at the start of the line, or in it)."""
    who, target, event = name(entry["a"], True), entry.get("t", ""), \
        entry["e"]
    if target and target == me and event in ADMIN_LOG_YOU:
        return tr(ADMIN_LOG_YOU[event], who=who)
    if event == "timer":
        return timer_event(who, int(target) if target.isdigit() else 0)
    if event == "topics" and target:
        return tr("{who} added the topic “{name}”", who=who, name=target)
    if event == "unadmin" and target == entry["a"]:
        return tr("{who} is no longer an admin", who=who)
    if event == "delete" and not target:
        return tr("{who} deleted members' messages", who=who)
    member = name(target, False) if valid_address(target) else target
    return tr(ADMIN_LOG_WORDS[event], who=who, group=target, member=member,
              members=member)


def group_row_state(group: dict) -> dict:
    """A group as LocalStore keeps it (a row of its), as the state it holds:
    what is sent to its members. Its rules and topics (17.4), its other
    admins and log (18.0), only when there are some."""
    state = {"id": group["gid"], "name": group["name"],
             "v": group["version"], "admin": group["admin"],
             "members": group["members"]}
    for key, part in (("r", "rules"), ("tp", "topics"), ("ad", "admins"),
                      ("lg", "log")):
        if group[part]:
            state[key] = group[part]
    return state


def state_body(state: dict) -> tuple:
    """A group's state as two are compared for a change: all of it but its
    version and log."""
    return tuple(state.get(k) or None for k in
                 ("name", "admin", "members", "r", "tp", "ad"))


def state_wins(held: dict, state: dict, sender: str) -> bool:
    """Is `state`, from `sender`, newer than the one held (a stored row)? A
    higher version is. At the same version (two admins at once), the
    owner's, else the lower address's — the same answer on every phone."""
    if state["v"] != held["version"]:
        return state["v"] > held["version"]
    by = held.get("by") or held["admin"]

    def rank(address):
        return (address != held["admin"], address)
    return rank(sender) < rank(by)


def admin_change_allowed(held: dict, state: dict, sender: str) -> bool:
    """18.0: may `sender`, an admin of the group as this phone holds it
    (`held`, a stored row), publish `state`? The owner may change anything;
    another admin only what their rights cover, never who the owner is, and
    other admins only those they made (with no more than their own
    rights)."""
    if sender == held["admin"]:
        return True
    entry = (held.get("admins") or {}).get(sender)
    if not entry or state["admin"] != held["admin"]:
        return False
    rights = set(entry["r"])
    old = {m["a"] for m in held["members"]}
    new = {m["a"] for m in state["members"]}
    before, after = held.get("admins") or {}, state.get("ad") or {}
    if new - old and "add" not in rights:
        return False
    for gone in old - new:
        if "remove" not in rights or gone == held["admin"] or (
                gone in before and before[gone]["by"] != sender):
            return False
    if state["name"] != held["name"] and "info" not in rights:
        return False
    both = (old & new) - set(before) - set(after)

    def rules(r):
        """What members may do, among those in both states, not admins."""
        r = dict(r or {})
        lim = {a: e for a, e in (r.get("lim") or {}).items() if a in both}
        r.pop("lim", None)
        if lim:
            r["lim"] = lim
        return r
    if rules(held.get("rules")) != rules(state.get("r")) and \
            "rules" not in rights:
        return False
    if (held.get("topics") or {}) != (state.get("tp") or {}) and \
            "topics" not in rights:
        return False
    for address in (set(before) | set(after)) & new:
        was, now = before.get(address), after.get(address)
        if was == now or (address == sender and now is None):
            continue                         # unchanged, or stepping down
        if "admins" not in rights or (was and was["by"] != sender) or (
                now and (now["by"] != sender or
                         not set(now["r"]) <= rights)):
            return False
    return True


def topics_events(who: str, old: dict, new: dict, mine: bool = False
                  ) -> list:
    """17.4: what a change of a group's topics says in its chat, by `who`
    (the admin; `mine`: this device's person, "You")."""
    lines, before = [], {t["id"]: t for t in old.get("list", [])}
    if bool(old.get("on")) != bool(new.get("on")):
        lines.append(tr("You turned topics on" if new.get("on") else
                        "You turned topics off: every message shows in one "
                        "chat", who=who) if mine else
                     tr("{who} turned topics on" if new.get("on") else
                        "{who} turned topics off: every message shows in one "
                        "chat", who=who))
    for topic in new.get("list", []):
        was = before.get(topic["id"])
        if was is None:
            lines.append(tr("You added the topic “{name}”", name=topic["n"])
                         if mine else tr("{who} added the topic “{name}”",
                                         who=who, name=topic["n"]))
            continue
        if was["n"] != topic["n"]:
            lines.append(tr("You renamed the topic “{old}” to “{name}”",
                            old=was["n"], name=topic["n"]) if mine else
                         tr("{who} renamed the topic “{old}” to “{name}”",
                            who=who, old=was["n"], name=topic["n"]))
        if was["c"] != topic["c"]:
            lines.append(tr("You closed the topic “{name}”" if topic["c"]
                            else "You reopened the topic “{name}”",
                            name=topic["n"]) if mine else
                         tr("{who} closed the topic “{name}”" if topic["c"]
                            else "{who} reopened the topic “{name}”",
                            who=who, name=topic["n"]))
    return lines


def message_rights(x: dict) -> tuple:
    """The rights a group message needs, by its x-block: a call's invite
    "calls", a photo or voice message "media", a planned call "send" and
    "calls", the rest "send"."""
    if x.get("k") == "call":
        return ("calls",)
    if x.get("k") == "media":
        return ("media",)
    return ("send", "calls") if x.get("plan") else ("send",)


#: Said to a member when a right is off for every member.
GROUP_ONLY_ADMIN = {
    "send": N_("Only the group's admins can send messages here"),
    "media": N_("Only the group's admins can send photos, voice and "
                "video messages here"),
    "calls": N_("Only the group's admins can start calls here")}


def group_stop_words(stop: Optional[tuple]) -> str:
    """What a stop (MessagingMixin.group_rule's) says to the one stopped,
    or "" for none."""
    if stop is None:
        return ""
    right, until, own = stop
    if not own:
        return tr(GROUP_ONLY_ADMIN[right])
    what = tr(GROUP_RIGHT_WORDS[right])
    if until:
        return tr("An admin has stopped your {what} here until {when}",
                  what=what, when=when_text(until))
    return tr("An admin has stopped your {what} here", what=what)


# ---- v11: disappearing messages ------------------------------------------------
# A chat's timer is set by either side (in a group, by its admin) with a
# 'timer' control; every message sent while it is on carries its own `ttl`,
# and each app deletes its copy that long after sending it, or after reading
# it. Old releases ignore both, so the setting says when someone's app does
# not take part (contacts.caps & CAP_TIMER).
TIMER_CHOICES = ((0, N_("Off")), (300, N_("5 minutes")),
                 (3600, N_("1 hour")), (8 * 3600, N_("8 hours")),
                 (86400, N_("1 day")), (7 * 86400, N_("1 week")),
                 (28 * 86400, N_("4 weeks")))
_TIMER_SECONDS = {seconds for seconds, _label in TIMER_CHOICES}


def sanitize_timer(value) -> Optional[int]:
    """A timer's seconds if they are one of the choices offered, else None."""
    if isinstance(value, bool) or not isinstance(value, int):
        return None
    return value if value in _TIMER_SECONDS else None


def timer_label(seconds: int) -> str:
    """How long a timer is, as the app says it: "1 hour", "Off"."""
    label = next((label for s, label in TIMER_CHOICES if s == seconds), None)
    return tr(label) if label else tr("{n} seconds", n=int(seconds))


def timer_event(name: str, seconds: int) -> str:
    """The line in the chat that says who changed the timer, and to what."""
    if not seconds:
        return tr("{name} turned off disappearing messages", name=name)
    return tr("{name} set messages to disappear {duration} after they are "
              "read", name=name, duration=timer_label(seconds))


# ---- v11: verifying a contact ---------------------------------------------------
# Contacts are found through the relay's directory, so a relay that lied
# could hand out the wrong address for a name. Two people close that by
# comparing, in person or on a call, a code worked out from both their
# keys — the same on both phones, and different if either key is not the
# one its owner holds — or by scanning the QR code on the other's phone.
def safety_code(pub_a: str, pub_b: str) -> str:
    """Twelve groups of five digits from two public keys (order does not
    matter). Hashed many times over, so searching for another key with the
    same code is slow."""
    a, b = sorted((bytes.fromhex(pub_a), bytes.fromhex(pub_b)))
    digest = b"fext.safety.v1|" + a + b
    for _ in range(5200):
        digest = hashlib.sha512(digest + a + b).digest()
    return " ".join(f"{int.from_bytes(digest[i * 5:i * 5 + 5], 'big') % 100000:05d}"
                    for i in range(12))


def address_in_qr(text: str) -> Optional[str]:
    """The address a scanned Ferritext QR code names: a profile's public
    bundle (JSON), or the bare address."""
    text = (text or "").strip()
    if text.startswith("{"):
        try:
            data = json.loads(text)
        except (ValueError, RecursionError):
            return None
        if isinstance(data, dict) and data.get("app") == WIRE_APP_TAG:
            text = str(data.get("address") or "")
    return text if valid_address(text) else None


def read_qr_image(path: str) -> Optional[str]:
    """The text of a QR code in a photo: ZXing on Android
    (org.fext.qr.QrReader), OpenCV or pyzbar on a computer when one is
    installed. None: none found, or nothing here can read one."""
    if IS_ANDROID:
        try:
            autoclass, _ = _jni()
            text = autoclass("org.fext.qr.QrReader").read(path)
            return str(text) if text else None
        except Exception:
            log.exception("could not read a QR code")
            return None
    try:
        import cv2                                        # type: ignore
        image = cv2.imread(path)
        if image is not None:
            detector = cv2.QRCodeDetector()
            for picture in (image, 255 - image):
                text, _points, _code = detector.detectAndDecode(picture)
                if text:
                    return text
    except Exception:
        pass
    try:
        from PIL import Image, ImageOps
        from pyzbar.pyzbar import decode as zbar          # type: ignore
        with Image.open(path) as picture:
            gray = picture.convert("L")
            for candidate in (gray, ImageOps.invert(gray)):
                for found in zbar(candidate):
                    return found.data.decode("utf-8", "replace")
    except Exception:
        pass
    return None


def can_read_qr() -> bool:
    if IS_ANDROID:
        return True
    import importlib.util as iu
    return any(iu.find_spec(m) is not None for m in ("cv2", "pyzbar"))


# ---- v11: encrypted backup -------------------------------------------------------
# One file holds what this device keeps for Ferritext: each identity's key
# and record, its database (chats, contacts, groups), the pictures and,
# when asked, the photos and voice notes. It is a tar stream sealed in
# 1 MiB chunks with AES-256-GCM, under a key scrypt derives from a
# passphrase; the first chunk holds only a known phrase, so a wrong
# passphrase is told apart from a damaged file. Each chunk's associated
# data carries its number and whether it is the last, so a file cut
# short, reordered or altered does not open;
# the header in front (the format, scrypt's settings, when and by what it
# was made) is bound to every chunk. Nothing is restored until the whole
# file has been read and found intact.
BACKUP_MAGIC = b"FEXTBACKUP\x00\x01"
BACKUP_SUFFIX = ".fextbackup"
BACKUP_CHUNK = 1 << 20
BACKUP_MIN_PASSPHRASE = 8
_BACKUP_CHECK = b"fext.backup.v1"
_BACKUP_FINAL = 0x80000000
_BACKUP_FILE = re.compile(r"^[A-Za-z0-9_.-]{1,96}$")
_BACKUP_NAME = re.compile(
    r"^(?:manifest\.json|identities\.json|"
    r"db/store_[1-9A-HJ-NP-Za-km-z]{25,40}\.db|"
    r"(?:pictures|media|recordings)/[A-Za-z0-9_.-]{1,96})$")


class BackupError(Exception):
    """A backup that cannot be made or opened; the message says why, to
    the person using the app."""


_DAMAGED = N_("This file is damaged.")


def _backup_key(passphrase: str, kdf) -> bytes:
    if not isinstance(kdf, dict) or kdf.get("name") != "scrypt":
        raise BackupError(tr("This backup was made by a newer Ferritext — "
                             "update this one first."))
    try:
        n, r, p = int(kdf["n"]), int(kdf["r"]), int(kdf["p"])
        salt = b64d(kdf["salt"])
    except (KeyError, TypeError, ValueError):
        raise BackupError(tr(_DAMAGED))
    # Bounded, so a file made to look like a backup cannot ask for hours of
    # work or gigabytes of memory.
    if not (2 ** 10 <= n <= 2 ** 20 and n & (n - 1) == 0 and 1 <= r <= 32
            and n * r <= 2 ** 21 and 1 <= p <= 4 and len(salt) >= 16):
        raise BackupError(tr(_DAMAGED))
    from cryptography.hazmat.primitives.kdf.scrypt import Scrypt
    secret = unicodedata.normalize("NFKC", passphrase).encode("utf-8")
    return Scrypt(salt=salt, length=32, n=n, r=r, p=p,
                  backend=default_backend()).derive(secret)


def _chunk_ad(bound: bytes, index: int, final: bool) -> bytes:
    return bound + index.to_bytes(4, "big") + (b"\x01" if final else b"\x00")


class _SealedWriter:
    """Where a backup's plaintext is written: it leaves in sealed chunks."""

    def __init__(self, out, key: bytes, bound: bytes):
        self._out, self._aead, self._bound = out, AESGCM(key), bound
        self._prefix = os.urandom(8)
        self._buf = bytearray()
        self._index = 0
        self.written = 0
        self._seal(_BACKUP_CHECK, False)

    def write(self, data) -> int:
        self._buf += data
        while len(self._buf) >= BACKUP_CHUNK:
            self._seal(bytes(self._buf[:BACKUP_CHUNK]), False)
            del self._buf[:BACKUP_CHUNK]
        self.written += len(data)
        return len(data)

    def _seal(self, data: bytes, final: bool) -> None:
        nonce = self._prefix + self._index.to_bytes(4, "big")
        sealed = self._aead.encrypt(nonce, data,
                                    _chunk_ad(self._bound, self._index, final))
        word = len(sealed) | (_BACKUP_FINAL if final else 0)
        self._out.write(word.to_bytes(4, "big") + nonce + sealed)
        self._index += 1

    def finish(self) -> None:
        self._seal(bytes(self._buf), True)
        self._buf.clear()


class _SealedReader:
    """A backup's plaintext, read out of its sealed chunks."""

    def __init__(self, src, key: bytes, bound: bytes):
        self._src, self._aead, self._bound = src, AESGCM(key), bound
        self._buf = bytearray()
        self._index = 0
        self._done = False

    def read(self, size: int = -1) -> bytes:
        while not self._done and (size < 0 or len(self._buf) < size):
            self._open_next()
        size = len(self._buf) if size < 0 else min(size, len(self._buf))
        out = bytes(self._buf[:size])
        del self._buf[:size]
        return out

    def _open_next(self) -> None:
        from cryptography.exceptions import InvalidTag
        head = self._src.read(4)
        if len(head) < 4:
            raise BackupError(tr("This backup is incomplete — it was cut "
                                 "short when it was made or copied."))
        word = int.from_bytes(head, "big")
        final, length = bool(word & _BACKUP_FINAL), word & ~_BACKUP_FINAL
        if not 16 <= length <= BACKUP_CHUNK + 16:
            raise BackupError(tr(_DAMAGED))
        nonce, sealed = self._src.read(12), self._src.read(length)
        if len(nonce) < 12 or len(sealed) < length:
            raise BackupError(tr("This backup is incomplete — it was cut "
                                 "short when it was made or copied."))
        try:
            plain = self._aead.decrypt(
                nonce, sealed, _chunk_ad(self._bound, self._index, final))
        except InvalidTag:
            raise BackupError(tr("Wrong passphrase.") if self._index == 0
                              else tr(_DAMAGED))
        if self._index == 0:
            if plain != _BACKUP_CHECK or final:
                raise BackupError(tr(_DAMAGED))
        else:
            self._buf += plain
        self._index += 1
        if final:
            self._done = True
            if self._src.read(1):
                raise BackupError(tr(_DAMAGED))

    def finish(self) -> None:
        """Read to the end, so all of it is known to be intact."""
        while not self._done:
            self._open_next()


def _file_name(path) -> str:
    """The last part of a stored path (of this device, or another's)."""
    name = re.split(r"[\\/]", str(path or ""))[-1]
    return name if _BACKUP_FILE.match(name) else ""


def default_backup_name() -> str:
    return f"Ferritext backup {datetime.now().strftime('%Y-%m-%d')}" + \
        BACKUP_SUFFIX


def discard_cache_file(path: Optional[str]) -> None:
    """Delete a working copy in this app's cache folder (and only there)."""
    if not path:
        return
    try:
        target = Path(path).resolve()
        if (DATA_DIR / "cache").resolve() in target.parents and \
                target.is_file():
            target.unlink()
    except OSError:
        pass


def default_backup_dir() -> Path:
    documents = Path.home() / "Documents"
    return documents if documents.is_dir() else Path.home()


def size_text(n: int) -> str:
    for unit, step in (("GB", 1 << 30), ("MB", 1 << 20), ("KB", 1 << 10)):
        if n >= step:
            return f"{n / step:.1f} {unit}"
    return tr("{n} bytes", n=n)


def backup_media_size(keys: "IdentityManager") -> tuple:
    """(how many, bytes): the photos and voice notes a backup would hold."""
    found = {}
    for ident in keys.identities:
        db_path = IdentityManager.store_path_for(ident["address"])
        if not db_path.is_file():
            continue
        try:
            db = sqlite3.connect(str(db_path))
            try:
                for (stored,) in db.execute(
                        "SELECT media_path FROM messages WHERE media_path IS "
                        "NOT NULL AND media_path != ''"):
                    here = MEDIA_DIR / _file_name(stored)
                    if _file_name(stored) and here.is_file():
                        found[here.name] = here.stat().st_size
            finally:
                db.close()
        except sqlite3.Error:
            pass
    return len(found), sum(found.values())


def backup_sealing(passphrase: str) -> tuple:
    """(scrypt's settings, the key) a backup is sealed with: a new salt
    each time; an automatic backup keeps one pair (17.0, AutoBackup)."""
    if len(passphrase) < BACKUP_MIN_PASSPHRASE:
        raise BackupError(tr("Use a passphrase of at least {n} characters.",
                             n=BACKUP_MIN_PASSPHRASE))
    kdf = {"name": "scrypt", "n": 2 ** 15, "r": 8, "p": 1,
           "salt": b64e(os.urandom(16))}
    return kdf, _backup_key(passphrase, kdf)


def make_backup(keys: "IdentityManager", passphrase: str, out_path,
                include_media: bool = True,
                progress: Optional[Callable[[float], None]] = None,
                sealing: Optional[tuple] = None,
                include_recordings: bool = False) -> dict:
    """Write this device's backup to `out_path`, sealed with `passphrase`
    (or `sealing`, from backup_sealing: an automatic backup's, made once
    from its passphrase). {path, size, identities: [{address, label,
    username, messages}], media: count, recordings: count}. Either way it
    opens with the passphrase, on any device. Call recordings only if
    asked (17.2, F18: Settings › Calls › Recordings in backups)."""
    out_path = Path(out_path)
    idents = [dict(i) for i in keys.identities]
    if not idents:
        raise BackupError(tr("There is nothing on this device to back up "
                             "yet."))
    kdf, key = sealing or backup_sealing(passphrase)
    header = {"v": 1, "made": now_iso(), "by": f"{APP_NAME} {APP_VERSION}",
              "kdf": kdf}
    head = json.dumps(header, separators=(",", ":")).encode("utf-8")
    prefix = BACKUP_MAGIC + len(head).to_bytes(4, "big") + head
    cache = DATA_DIR / "cache"
    cache.mkdir(parents=True, exist_ok=True)
    staging = Path(tempfile.mkdtemp(prefix="backup_", dir=str(cache)))
    part = out_path.with_name(out_path.name + ".part")
    files, pictures, media, listed = [], {}, {}, []
    try:
        for ident in idents:
            address = ident["address"]
            db_path = IdentityManager.store_path_for(address)
            count = 0
            if db_path.is_file():
                snap = staging / db_path.name
                src, dst = sqlite3.connect(str(db_path)), \
                    sqlite3.connect(str(snap))
                try:
                    src.backup(dst)       # a consistent copy, even while open
                finally:
                    dst.close()
                    src.close()
                files.append((f"db/{db_path.name}", snap))
                db = sqlite3.connect(str(snap))
                try:
                    count = db.execute(
                        "SELECT COUNT(*) FROM messages WHERE kind IS NULL OR "
                        "kind != 'event'").fetchone()[0]
                    for (stored,) in db.execute(
                            "SELECT path FROM pictures WHERE path IS NOT NULL"):
                        found = PICTURES_DIR / _file_name(stored)
                        if _file_name(stored) and found.is_file():
                            pictures[found.name] = found
                    if include_media:
                        for (stored,) in db.execute(
                                "SELECT media_path FROM messages WHERE "
                                "media_path IS NOT NULL AND media_path != ''"):
                            found = MEDIA_DIR / _file_name(stored)
                            if _file_name(stored) and found.is_file():
                                media[found.name] = found
                except sqlite3.Error:
                    log.warning("backup: %s has no pictures or media tables",
                                db_path.name)
                finally:
                    db.close()
            own = own_picture_path(address)
            if own.is_file():
                pictures[own.name] = own
            listed.append({"address": address,
                           "label": ident.get("label") or "",
                           "username": ident.get("username"),
                           "messages": count})
        entries = [
            ("manifest.json", json.dumps({
                "v": 1, "made": header["made"], "identities": listed,
                "media": bool(include_media)}).encode("utf-8")),
            ("identities.json", json.dumps({"identities": idents}
                                           ).encode("utf-8"))]
        files += [(f"pictures/{n}", f) for n, f in sorted(pictures.items())]
        files += [(f"media/{n}", f) for n, f in sorted(media.items())]
        recordings = kept_recordings() if include_recordings else []
        files += [(f"recordings/{f.name}", f) for f in recordings]
        total = sum(len(data) for _n, data in entries) + \
            sum(f.stat().st_size for _n, f in files)
        with open(part, "wb") as raw:
            raw.write(prefix)
            sealed = _SealedWriter(raw, key, hashlib.sha256(prefix).digest())
            with tarfile.open(fileobj=sealed, mode="w|",
                              format=tarfile.PAX_FORMAT) as tar:
                for name, data in entries:
                    info = tarfile.TarInfo(name)
                    info.size, info.mtime = len(data), int(time.time())
                    tar.addfile(info, io.BytesIO(data))
                for name, found in files:
                    info = tarfile.TarInfo(name)
                    with open(found, "rb") as fh:
                        info.size = os.fstat(fh.fileno()).st_size
                        info.mtime = int(time.time())
                        tar.addfile(info, fh)
                    if progress is not None:
                        progress(min(1.0, sealed.written / max(1, total)))
            sealed.finish()
            raw.flush()
            os.fsync(raw.fileno())
        replace_file(part, out_path)
        if progress is not None:
            progress(1.0)
    except OSError as exc:
        raise BackupError(tr("The backup could not be written: {reason}.",
                             reason=exc.strerror or exc))
    finally:
        shutil.rmtree(staging, ignore_errors=True)
        if part.exists():
            try:
                part.unlink()
            except OSError:
                pass
    return {"path": str(out_path), "size": out_path.stat().st_size,
            "identities": listed, "media": len(media),
            "recordings": len(recordings)}


def read_backup_header(path) -> dict:
    """The clear header of a backup: when and by what it was made."""
    with open(path, "rb") as raw:
        return _read_header(raw)[0]


def _read_header(raw) -> tuple:
    if raw.read(len(BACKUP_MAGIC)) != BACKUP_MAGIC:
        raise BackupError(tr("This is not a Ferritext backup."))
    word = raw.read(4)
    length = int.from_bytes(word, "big") if len(word) == 4 else 0
    if not 2 <= length <= 4096:
        raise BackupError(tr(_DAMAGED))
    head = raw.read(length)
    try:
        header = json.loads(head.decode("utf-8"))
    except (UnicodeDecodeError, ValueError, RecursionError):
        raise BackupError(tr(_DAMAGED))
    if not isinstance(header, dict):
        raise BackupError(tr(_DAMAGED))
    if header.get("v") != 1:
        raise BackupError(tr("This backup was made by a newer Ferritext — "
                             "update this one first."))
    return header, BACKUP_MAGIC + word + head


def _store_messages(path: Path) -> int:
    if not path.is_file():
        return 0
    try:
        db = sqlite3.connect(str(path))
        try:
            return db.execute("SELECT COUNT(*) FROM messages WHERE kind IS "
                              "NULL OR kind != 'event'").fetchone()[0]
        finally:
            db.close()
    except sqlite3.Error:
        return 0


def _check_store(snapshot: Path) -> None:
    """A backed-up database that SQLite finds sound, with its messages."""
    try:
        db = sqlite3.connect(str(snapshot))
        try:
            sound = db.execute("PRAGMA quick_check").fetchone()[0] == "ok"
            db.execute("SELECT COUNT(*) FROM messages").fetchone()
        finally:
            db.close()
    except sqlite3.Error:
        sound = False
    if not sound:
        raise BackupError(tr(_DAMAGED))


def _place_store(snapshot: Path, target: Path) -> None:
    """Put a restored database (checked: _check_store) in place, its paths
    made this device's."""
    for leftover in (Path(str(target) + "-wal"), Path(str(target) + "-shm")):
        if leftover.exists():
            leftover.unlink()
    db = sqlite3.connect(str(snapshot))
    try:
        for row_id, stored in db.execute(
                "SELECT id, media_path FROM messages WHERE media_path IS NOT "
                "NULL AND media_path != ''").fetchall():
            here = MEDIA_DIR / _file_name(stored)
            db.execute("UPDATE messages SET media_path = ? WHERE id = ?",
                       (str(here) if _file_name(stored) and here.is_file()
                        else None, row_id))
        for peer, stored in db.execute(
                "SELECT peer, path FROM pictures WHERE path IS NOT NULL"
                ).fetchall():
            here = PICTURES_DIR / _file_name(stored)
            db.execute("UPDATE pictures SET path = ? WHERE peer = ?",
                       (str(here) if _file_name(stored) and here.is_file()
                        else None, peer))
        db.commit()
    except sqlite3.Error:
        raise BackupError(tr(_DAMAGED))
    finally:
        db.close()
    shutil.move(str(snapshot), str(target))


def restore_backup(keys: "IdentityManager", path, passphrase: str,
                   progress: Optional[Callable[[float], None]] = None
                   ) -> dict:
    """Add what a backup holds to this device. An identity it does not
    have arrives with its chats; one it has keeps its own, unless they are
    empty. {added, replaced, kept: [names], messages: count}. The app's
    open database must be closed first (see RestoreSheet)."""
    path = Path(path)
    total = max(1, path.stat().st_size)
    cache = DATA_DIR / "cache"
    cache.mkdir(parents=True, exist_ok=True)
    staging = Path(tempfile.mkdtemp(prefix="restore_", dir=str(cache)))
    try:
        got = {}
        with open(path, "rb") as raw:
            header, prefix = _read_header(raw)
            key = _backup_key(passphrase, header.get("kdf"))
            reader = _SealedReader(raw, key, hashlib.sha256(prefix).digest())
            try:
                with tarfile.open(fileobj=reader, mode="r|") as tar:
                    for member in tar:
                        name = member.name
                        if not member.isfile() or name in got or \
                                not _BACKUP_NAME.match(name):
                            continue
                        dest = staging / name.replace("/", "__")
                        source = tar.extractfile(member)
                        with open(dest, "wb") as fh:
                            shutil.copyfileobj(source, fh, 1 << 20)
                        got[name] = dest
                        if progress is not None:
                            progress(min(0.95, raw.tell() / total))
            except tarfile.TarError:
                raise BackupError(tr(_DAMAGED))
            reader.finish()
        if "identities.json" not in got:
            raise BackupError(tr(_DAMAGED))
        try:
            records = json.loads(got["identities.json"].read_text("utf-8"))[
                "identities"]
            if not isinstance(records, list):
                raise TypeError("identities")
        except (ValueError, KeyError, TypeError, RecursionError):
            raise BackupError(tr(_DAMAGED))
        # Every database is checked before anything here changes (16.0: a
        # damaged one was found out only after its identity was added).
        for name, staged in got.items():
            if name.startswith("db/"):
                _check_store(staged)
        PICTURES_DIR.mkdir(parents=True, exist_ok=True)
        MEDIA_DIR.mkdir(parents=True, exist_ok=True)
        if any(name.startswith("recordings/") for name in got):
            recordings_dir().mkdir(parents=True, exist_ok=True)
        for name, staged in got.items():
            folder = {"pictures": PICTURES_DIR, "media": MEDIA_DIR,
                      "recordings": recordings_dir()}.get(
                name.split("/", 1)[0])
            if folder is not None and not (folder / name.split("/")[1]
                                           ).exists():
                shutil.move(str(staged), str(folder / name.split("/")[1]))
        summary = {"added": [], "replaced": [], "kept": [], "messages": 0}
        for record in records:
            if not isinstance(record, dict):
                continue
            address = record.get("address")
            try:
                priv = int(str(record.get("private_key_hex")), 16)
                ok = 0 < priv < _N and address == address_from_pub_bytes(
                    pub_to_compressed(priv_to_pub(priv)))
            except (TypeError, ValueError):
                ok = False
            if not ok:
                continue
            name = record.get("label") or record.get("username") or \
                short_addr(address, 10)
            snapshot = got.get(f"db/store_{address}.db")
            target = IdentityManager.store_path_for(address)
            if keys.find(address) is None:
                keys.restore_identity(record)
                summary["added"].append(name)
            elif snapshot is not None and _store_messages(target) == 0:
                summary["replaced"].append(name)
            else:
                summary["kept"].append(name)
                continue
            if snapshot is not None:
                summary["messages"] += _store_messages(snapshot)
                _place_store(snapshot, target)
        if progress is not None:
            progress(1.0)
        return summary
    except OSError as exc:
        raise BackupError(tr("The backup could not be read: {reason}.",
                             reason=exc.strerror or exc))
    finally:
        shutil.rmtree(staging, ignore_errors=True)


MEDIA_AAD = b"fext.media.v1"


def compress_image(path: str) -> tuple:
    """Shrink a photo for sending: (jpeg_bytes, width, height, thumb_b64).

    Fits it inside IMAGE_MAX_EDGE, re-encodes it as a progressive JPEG and,
    by not passing them on, drops EXIF and every other metadata block —
    which is where phones keep the GPS position a photo was taken at. The
    camera's rotation flag is applied to the pixels first, because dropping
    it would otherwise turn portrait photos on their side.
    """
    from PIL import Image, ImageOps
    import io as _io
    with Image.open(path) as source:
        source.load()
        try:
            image = ImageOps.exif_transpose(source)
        except Exception:                        # malformed EXIF: ignore it
            image = source.copy()
    if image.mode in ("RGBA", "LA", "P"):
        image = image.convert("RGBA")
        flat = Image.new("RGB", image.size, (255, 255, 255))
        flat.paste(image, mask=image.split()[-1])
        image = flat
    else:
        image = image.convert("RGB")
    image.thumbnail((IMAGE_MAX_EDGE, IMAGE_MAX_EDGE), Image.LANCZOS)
    out = _io.BytesIO()
    image.save(out, "JPEG", quality=IMAGE_JPEG_QUALITY, optimize=True,
               progressive=True)
    thumb = image.copy()
    thumb.thumbnail((THUMB_EDGE, THUMB_EDGE), Image.LANCZOS)
    small = _io.BytesIO()
    thumb.save(small, "JPEG", quality=THUMB_QUALITY)
    return out.getvalue(), image.width, image.height, b64e(small.getvalue())


def voice_label(duration_ms: int, what: str = "Voice") -> str:
    """A voice message's body: what an app that cannot play it shows. It
    goes to the other phone in English; shown_body translates it there."""
    seconds = max(0, int(round((duration_ms or 0) / 1000.0)))
    return f"{what} message ({seconds // 60}:{seconds % 60:02d})"


def video_label(duration_ms: int) -> str:
    """A video message's body: all an app before 18.1 shows of it."""
    return voice_label(duration_ms, "Video")


_TIMED_BODY = re.compile(r"(Voice|Video) message \((\d+:\d\d)\)")


def shown_body(kind: str, body: str) -> str:
    """A message's body as this phone shows it: the English the sender's
    app wrote for a photo, a voice or a video message, in this phone's
    language."""
    if kind == "image" and body == "Photo":
        return tr("Photo")
    timed = _TIMED_BODY.fullmatch(body or "")
    if timed and (kind, timed.group(1)) == ("voice", "Voice"):
        return tr("Voice message ({time})", time=timed.group(2))
    if timed and (kind, timed.group(1)) == ("video", "Video"):
        return tr("Video message ({time})", time=timed.group(2))
    return body


def seal_media(data: bytes) -> tuple:
    """Encrypt one media file for upload. Returns (blob, key_b64, sha_hex).

    A fresh 256-bit key per file, never reused, so the relay's copy is just
    noise and forwarding a photo can share its reference without sharing any
    other key. The key travels inside the end-to-end envelope; `sha` lets
    the recipient reject a corrupted or substituted download BEFORE trying
    to decrypt it.
    """
    key, nonce = os.urandom(32), os.urandom(12)
    blob = nonce + AESGCM(key).encrypt(nonce, data, MEDIA_AAD)
    return blob, b64e(key), hashlib.sha256(blob).hexdigest()


def open_media(blob: bytes, key_b64: str, sha_hex: str) -> bytes:
    """Verify and decrypt a downloaded blob; raises ValueError on mismatch."""
    if hashlib.sha256(blob).hexdigest() != sha_hex:
        raise ValueError("media failed its integrity check")
    if len(blob) < 12 + 16:
        raise ValueError("media blob is truncated")
    try:
        return AESGCM(b64d(key_b64)).decrypt(blob[:12], blob[12:], MEDIA_AAD)
    except Exception:
        raise ValueError("media could not be decrypted")


def media_suffix(kind: str, mime: Optional[str]) -> str:
    """The file extension a received photo or voice note is saved under —
    by its type, so a desktop opens it with the right program."""
    if kind == "image":
        return "jpg"
    if kind == "voice":
        return {"audio/wav": "wav", "audio/ogg": "ogg", "audio/aac": "aac",
                "audio/3gpp": "3gp", "audio/amr": "amr"}.get(mime or "",
                                                              "m4a")
    if kind == "video":
        return "mp4"
    return "bin"


def discard_media_file(path: Optional[str]) -> None:
    """Delete a decrypted media file — but only one inside MEDIA_DIR, so a
    corrupted database row can never point this at anything else."""
    if not path:
        return
    try:
        target = Path(path).resolve()
        if MEDIA_DIR.resolve() in target.parents and target.is_file():
            target.unlink()
    except OSError:
        log.warning("could not remove media file %s", path)


# ---- v9.1.2 pictures: files and pixels -----------------------------------------
def own_picture_path(address: str) -> Path:
    """Where an identity on this device keeps its own picture. Named by the
    address alone, so the menu can show every identity's picture without
    opening each one's database."""
    return PICTURES_DIR / f"me_{address}.jpg"


def peer_picture_path(owner: str, peer: str) -> Path:
    """Where identity `owner` keeps the picture `peer` sent it (a contact's
    own, or a group's). One file per identity and peer: identities on one
    device keep apart what they were sent, as they do their chats."""
    tag = hashlib.sha256(f"{owner}|{peer}".encode("utf-8")).hexdigest()[:24]
    return PICTURES_DIR / f"p_{tag}.jpg"


def write_picture(path: Path, data: bytes) -> bool:
    """Put a picture in place whole: a reader never sees half of one."""
    try:
        PICTURES_DIR.mkdir(parents=True, exist_ok=True)
        tmp = path.with_name(path.name + ".tmp")
        tmp.write_bytes(data)
        replace_file(tmp, path)
        return True
    except OSError:
        log.warning("could not write picture %s", path.name)
        return False


def discard_picture_file(path) -> None:
    """Delete a picture — but only one inside PICTURES_DIR."""
    if not path:
        return
    try:
        target = Path(path).resolve()
        if PICTURES_DIR.resolve() in target.parents and target.is_file():
            target.unlink()
    except OSError:
        log.warning("could not remove picture %s", path)


def next_picture_version(previous: int) -> int:
    """A picture's version is a time in seconds, and always rises. Set after
    reinstalling, when the old number is forgotten, a new picture still
    counts as newer than the one everybody holds."""
    return max(int(previous or 0) + 1, int(time.time()))


def open_picture_source(path: str):
    """A photo to make a picture from: upright, RGB, and no bigger than
    cropping needs (a JPEG is decoded at a reduced scale to begin with)."""
    from PIL import Image, ImageOps
    with Image.open(path) as source:
        if source.width * source.height > 64_000_000:
            raise ValueError("photo too large")
        source.draft("RGB", (PICTURE_SOURCE_EDGE, PICTURE_SOURCE_EDGE))
        source.load()
        try:
            image = ImageOps.exif_transpose(source)
        except Exception:                        # malformed EXIF: ignore it
            image = source.copy()
    if image.mode in ("RGBA", "LA", "P"):
        image = image.convert("RGBA")
        flat = Image.new("RGB", image.size, (255, 255, 255))
        flat.paste(image, mask=image.split()[-1])
        image = flat
    else:
        image = image.convert("RGB")
    image.thumbnail((PICTURE_SOURCE_EDGE, PICTURE_SOURCE_EDGE), Image.LANCZOS)
    return image


def picture_jpeg(image, box=None) -> bytes:
    """A picture to keep and send: the square `box` of `image` (left, top,
    right, bottom in its pixels; the centre square when None), as a JPEG of
    PICTURE_EDGE pixels at the best quality that fits PICTURE_MAX_BYTES.
    It is drawn afresh from the pixels, so nothing else in the original
    file — camera details, the place it was taken — goes with it."""
    from PIL import Image
    import io as _io
    if box is None:
        side = min(image.size)
        left, top = (image.width - side) // 2, (image.height - side) // 2
        box = (left, top, left + side, top + side)
    square = image.crop(tuple(int(round(v)) for v in box)).convert("RGB")
    data = b""
    # A photo fits at the first size; only something like noise, which a
    # JPEG cannot squeeze, ever needs a smaller one.
    for edge in (PICTURE_EDGE, 256, 192, 128):
        sized = square.resize((edge, edge), Image.LANCZOS)
        for quality in (86, 80, 72, 64, 56, 48, 40):
            out = _io.BytesIO()
            sized.save(out, "JPEG", quality=quality, optimize=True)
            data = out.getvalue()
            if len(data) <= PICTURE_MAX_BYTES:
                return data
    return data


def clean_picture(raw: bytes) -> Optional[bytes]:
    """Someone else's picture, made safe to keep: refused unless it is a
    modest JPEG, PNG or WebP, and otherwise decoded and drawn again here,
    so the file this device keeps is always one it wrote itself."""
    from PIL import Image
    import io as _io
    if not raw or len(raw) > PICTURE_ACCEPT_BYTES:
        return None
    try:
        with Image.open(_io.BytesIO(raw), formats=FOREIGN_FORMATS) as image:
            if image.format not in FOREIGN_FORMATS:
                return None
            if not (16 <= image.width <= 1024 and 16 <= image.height <= 1024):
                return None
            image.load()
            return picture_jpeg(image.convert("RGB"))
    except Exception:
        return None


def image_header(data: bytes) -> Optional[tuple]:
    """(format, width, height) of a JPEG, PNG or WebP of a sane size, read
    from its header alone — or None. Nothing is decoded: a few kilobytes
    can claim enough pixels to fill a phone's memory."""
    from PIL import Image
    import io as _io
    try:
        with Image.open(_io.BytesIO(data), formats=FOREIGN_FORMATS) as image:
            kind, (width, height) = image.format, image.size
    except Exception:
        return None
    if kind not in FOREIGN_FORMATS or \
            not 1 <= width <= FOREIGN_MAX_EDGE or \
            not 1 <= height <= FOREIGN_MAX_EDGE or \
            width * height > FOREIGN_MAX_PIXELS:
        return None
    return kind, width, height


def open_foreign_image(data: bytes, box: int):
    """A picture from elsewhere as an RGB image no bigger than `box` pixels
    a side — upright, transparency on white, a JPEG decoded at a reduced
    scale from the start — or None if it is not one of a sane size."""
    from PIL import Image, ImageOps
    import io as _io
    if image_header(data) is None:
        return None
    try:
        with Image.open(_io.BytesIO(data), formats=FOREIGN_FORMATS) as source:
            source.draft("RGB", (box, box))
            source.load()
            try:
                image = ImageOps.exif_transpose(source)
            except Exception:                    # malformed EXIF: ignore it
                image = source.copy()
        if image.mode in ("RGBA", "LA", "P", "PA"):
            image = image.convert("RGBA")
            flat = Image.new("RGB", image.size, (255, 255, 255))
            flat.paste(image, mask=image.split()[-1])
            image = flat
        else:
            image = image.convert("RGB")
        image.thumbnail((box, box), Image.LANCZOS)
        return image
    except Exception:
        return None


def safe_received_image(data: bytes) -> Optional[bytes]:
    """A photo someone sent, made safe to show (v12): kept as it came if it
    is a JPEG no bigger than RECEIVED_KEEP_EDGE, drawn again here at that
    size if it is a bigger one or a PNG or WebP, and refused (None) if it
    is not a picture of a sane size at all."""
    import io as _io
    header = image_header(data)
    if header is None:
        return None
    kind, width, height = header
    if kind == "JPEG" and max(width, height) <= RECEIVED_KEEP_EDGE:
        return data
    image = open_foreign_image(data, RECEIVED_KEEP_EDGE)
    if image is None:
        return None
    out = _io.BytesIO()
    image.save(out, "JPEG", quality=85, optimize=True, progressive=True)
    return out.getvalue()


def valid_username(name: str) -> bool:
    return bool(re.match(r"^[A-Za-z0-9_]{3,32}$", name))


def valid_address(value: str) -> bool:
    if not re.match(r"^F[1-9A-HJ-NP-Za-km-z]{20,40}$", value):
        return False
    try:
        b58check_decode(value)
        return True
    except ValueError:
        return False


# =============================================================================
#  MessageFlowLog — the client half of the golden-tick audit trail
# =============================================================================
class MessageFlowLog:
    """Mirrors the relay's flow log, line for line and format for format, so
    the two can be diffed when a message goes missing.

        ✓    1/3   the relay accepted our ciphertext (or: we accepted theirs)
        ✓✓   2/3   the recipient holds it
        ✓✓✓  3/3   the recipient read it

    Every line carries who -> whom and a fragment of the ciphertext. The
    fragment is the join key: it is the one value that exists identically on
    both sides of the wire, so `grep` on it lines a client's story up against
    the relay's without either side having to log anything sensitive.

    PRIVACY NOTE. Unlike the relay, this process legitimately holds
    plaintext — and it stays out of the log regardless. What lands here is
    what the relay could already see: addresses, sizes, timings. Message
    bodies never appear.
    """

    _TIERS = {0: "·  ", 1: "✓  ", 2: "✓✓ ", 3: "✓✓✓"}
    _LABELS = {0: "queued locally (not yet on the relay)",
               1: "accepted by relay",
               2: "delivered to recipient",
               3: "read by recipient"}

    #: How much base64 ciphertext to echo. Matches the relay's default.
    FRAGMENT_CHARS = 24

    @classmethod
    def fragment(cls, envelope: Optional[dict]) -> str:
        """The head of the base64 ciphertext plus its true byte length —
        opaque, but unique enough to identify one message anywhere."""
        if not isinstance(envelope, dict):
            return "ct=?"
        ct = envelope.get("ciphertext", "")
        if not isinstance(ct, str):
            return "ct=?"
        try:
            size = len(b64d(ct))
        except (ValueError, TypeError):
            size = 0
        head = ct[:cls.FRAGMENT_CHARS] + ("…" if len(ct) > cls.FRAGMENT_CHARS
                                          else "")
        return f"ct={head} ({size}B)"

    @staticmethod
    def who(address: str, username: Optional[str] = None) -> str:
        short = (address if len(address) <= 14
                 else f"{address[:6]}…{address[-4:]}")
        return f"{username}({short})" if username else short

    @classmethod
    def tick(cls, tier: int, server_id, sender: str, recipient: str,
             extra: str = "") -> None:
        flow_log.info("%s %d/3  #%s  %s -> %s  %s%s",
                      cls._TIERS.get(tier, "?"), tier,
                      server_id if server_id else "-", sender, recipient,
                      cls._LABELS.get(tier, ""),
                      f"  {extra}" if extra else "")

    @classmethod
    def failed(cls, sender: str, recipient: str, reason: str,
               extra: str = "") -> None:
        flow_log.warning("✗   0/3  %s -> %s  NOT SENT: %s%s",
                         sender, recipient, reason,
                         f"  {extra}" if extra else "")

    @classmethod
    def dropped(cls, server_id, sender: str, reason: str) -> None:
        """An INBOUND message we could not take custody of. Loud on purpose:
        this is the exact moment at which a message is at risk of being lost,
        and the whole 2/3-tick bug was this path failing quietly."""
        flow_log.error("✗   in   #%s  from %s  NOT STORED: %s "
                       "(withholding ack so the relay keeps its copy)",
                       server_id if server_id else "-", sender, reason)

    @classmethod
    def let_go(cls, server_id, sender: str, what: str) -> None:
        """An INBOUND frame deliberately taken and set aside or refused —
        acknowledged, so the relay forgets it (v11: from a blocked
        contact)."""
        flow_log.info("⏸   in   #%s  from %s  %s (acknowledged)",
                      server_id if server_id else "-", sender, what)


def open_folder_in_explorer(path: Path) -> bool:
    """Reveal `path` in the OS file manager (desktop only). On mobile there
    is no file manager to open into the app sandbox; callers show the path
    as text instead. Returns True when a file manager was launched."""
    path.mkdir(parents=True, exist_ok=True)
    if IS_MOBILE:
        return False
    system = platform.system()
    try:
        if system == "Windows":
            os.startfile(str(path))                  # type: ignore[attr-defined]
        elif system == "Darwin":
            subprocess.Popen(["open", str(path)])
        else:
            subprocess.Popen(["xdg-open", str(path)])
        return True
    except OSError:
        return False


def run_on_ui(fn: Callable, *args) -> None:
    """Hop onto the Kivy main thread (the tkinter `after(0, …)` of this app).
    ALL widget mutation from worker threads goes through here."""
    Clock.schedule_once(lambda _dt: fn(*args), 0)


# =============================================================================
#  Platform glue — Android through pyjnius, with desktop fallbacks
# =============================================================================
# Everything Android-specific lives here so the rest of the file stays
# platform-neutral. Each entry point is defensive: on a desktop, or if a
# device's media stack misbehaves, the caller gets an exception or a False
# and turns it into a status line. None of it may take the app down.

REQ_PICK_IMAGE = 4711
REQ_TAKE_PHOTO = 4712
REQ_SAVE_FILE = 4713          # v11: where a backup goes
REQ_OPEN_FILE = 4714          # v11: a backup to restore
REQ_PICK_FOLDER = 4715        # 17.0: where automatic backups go
REQ_SHARE_SCREEN = 4716       # 18.0: Android's yes to sharing the screen
NOTIFY_CHANNEL = "messages"


def _jni():
    from jnius import autoclass, cast            # Android only
    return autoclass, cast


def android_context():
    """The Activity in the app process; the Service in the sync service."""
    autoclass, _ = _jni()
    activity = autoclass("org.kivy.android.PythonActivity").mActivity
    if activity is not None:
        return activity
    return autoclass("org.kivy.android.PythonService").mService


#: The app's own Java classes that call threads use (17.1). Android looks
#: for an app's classes from a thread Java started (the UI thread here);
#: from one Python started it sees the system's alone, and a call's sound
#: failed with ClassNotFoundException. pyjnius keeps a class once found,
#: so these are found on the UI thread before a call's threads start.
#: 17.2: the decoder too, a class of its own (VideoCall$Decoder), which
#: the emulators' self-test found missing: their picture would not decode.
#: 18.0: the screen's, which starts on its sender's thread: its stop
#: callback, pyjnius's proxy (a Python Runnable is one) and the share
#: service ({package}: the app's, which p4a names its services after).
SHARE_SERVICE_CLASS = "{package}.Service" + SHARE_SERVICE_NAME.capitalize()
ANDROID_CALL_CLASSES = ("org.fext.call.CallAudio", "org.fext.call.VideoCall",
                        "org.fext.call.VideoCall$Decoder",
                        "org.fext.call.ProjectionStop",
                        "org.jnius.NativeInvocationHandler",
                        SHARE_SERVICE_CLASS)


def android_find_call_classes() -> None:
    """UI thread, as a call begins (Android; cheap once found). Not on
    Android 5, where calls do not start (ANDROID_CALLS_SDK)."""
    if not IS_ANDROID or android_calls_too_old():
        return
    for name in ANDROID_CALL_CLASSES:
        try:
            if "{package}" in name:
                name = name.format(
                    package=android_context().getPackageName())
            _jni()[0](name)
        except Exception:
            log.exception("android: %s was not found", name)


#: 17.3 (ANDROID5): calls from Android 6 (API 23). A call's sound
#: (CallAudio.java) names AudioDeviceInfo, a class of Android 6, so Android
#: 5 cannot load it (the Devices run on API 21, 17.2.1); there the call
#: buttons say so, and a call offered is answered "unavailable" with a
#: missed call's card. Messages and the rest run on Android 5.
ANDROID_CALLS_SDK = 23
_SDK: list = []


def android_sdk() -> int:
    """Android's API level (21: 5.0, 23: 6.0), read once."""
    if not _SDK:
        autoclass, _ = _jni()
        _SDK.append(int(autoclass("android.os.Build$VERSION").SDK_INT))
    return _SDK[0]


def android_calls_too_old() -> bool:
    """17.3: Android 5, where calls cannot run. False where the level
    cannot be read (not a phone: the suites that play one)."""
    if not IS_ANDROID:
        return False
    try:
        return android_sdk() < ANDROID_CALLS_SDK
    except Exception:
        return False


def _charseq(text: str):
    autoclass, cast = _jni()
    return cast("java.lang.CharSequence", autoclass("java.lang.String")(text))


def android_request_permissions(permissions: list, callback=None) -> None:
    """Runtime permissions (Android 6+). Missing ones are simply asked for;
    the OS remembers a refusal, so asking again is harmless."""
    try:
        from android.permissions import request_permissions
        request_permissions(permissions, callback)
    except Exception:
        log.exception("could not request %s", permissions)


def android_has_permission(permission: str) -> bool:
    try:
        from android.permissions import check_permission
        return bool(check_permission(permission))
    except Exception:
        return False


def leave_jvm() -> None:
    """A thread that used Java leaves the JVM before it ends (Android):
    one that does not stays on Android's list of threads for good."""
    if IS_ANDROID:
        try:
            from jnius import detach
            detach()
        except Exception:
            pass


def off_ui(work: Callable[[], None]) -> None:
    """Run `work` on a thread of its own, off the UI thread; on Android it
    leaves the JVM when done, as every thread that used Java must."""
    def run() -> None:
        try:
            work()
        finally:
            leave_jvm()
    threading.Thread(target=run, daemon=True).start()


def android_share_text(text: str) -> None:
    autoclass, cast = _jni()
    Intent = autoclass("android.content.Intent")
    intent = Intent(Intent.ACTION_SEND)
    intent.setType("text/plain")
    intent.putExtra(Intent.EXTRA_TEXT, _charseq(text))
    android_context().startActivity(
        Intent.createChooser(intent, _charseq(tr("Share"))))


def android_share_image(path: str) -> None:
    """Share a photo with another app.

    Other apps cannot read this app's private storage, and Android 7+
    forbids handing them file:// paths anyway, so the photo is published
    through MediaStore first and the resulting content:// URI is shared.
    (A side effect is that a shared photo also lands in the gallery.)
    """
    autoclass, cast = _jni()
    ctx = android_context()
    media = autoclass("android.provider.MediaStore$Images$Media")
    uri_text = media.insertImage(ctx.getContentResolver(), path,
                                 tr("Ferritext photo"), None)
    if not uri_text:
        raise RuntimeError("the gallery refused the photo")
    Intent = autoclass("android.content.Intent")
    intent = Intent(Intent.ACTION_SEND)
    intent.setType("image/jpeg")
    intent.putExtra(Intent.EXTRA_STREAM, cast(
        "android.os.Parcelable", autoclass("android.net.Uri").parse(uri_text)))
    intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION)
    ctx.startActivity(Intent.createChooser(intent,
                                           _charseq(tr("Share photo"))))


def _notification_id(peer: str) -> int:
    """Stable per chat, so a second message replaces the first notification
    instead of stacking. (hash() is randomised per process — useless here.)"""
    return 1000 + int(hashlib.sha256(peer.encode()).hexdigest()[:6], 16)


def android_notify(peer: str, title: str, text: str) -> None:
    """Post a 'new message' notification; tapping it opens that chat."""
    autoclass, cast = _jni()
    ctx = android_context()
    Context = autoclass("android.content.Context")
    manager = cast("android.app.NotificationManager",
                   ctx.getSystemService(Context.NOTIFICATION_SERVICE))
    Builder = autoclass("android.app.Notification$Builder")
    if android_sdk() >= 26:
        Channel = autoclass("android.app.NotificationChannel")
        importance = autoclass("android.app.NotificationManager"
                               ).IMPORTANCE_HIGH
        channel = Channel(NOTIFY_CHANNEL, _charseq(tr("Messages")),
                          importance)
        channel.setDescription(tr("New messages"))
        manager.createNotificationChannel(channel)
        builder = Builder(ctx, NOTIFY_CHANNEL)
    else:
        builder = Builder(ctx)
        builder.setPriority(1)                    # PRIORITY_HIGH
    res = ctx.getResources()
    icon = res.getIdentifier("ic_stat_ferritext", "drawable",
                             ctx.getPackageName())
    builder.setSmallIcon(icon or ctx.getApplicationInfo().icon)
    builder.setContentTitle(_charseq(title))
    builder.setContentText(_charseq(text))
    builder.setAutoCancel(True)
    # The launcher intent, not an explicit Activity class: it is what a tap
    # on the app icon would send, so it resumes the running instance.
    intent = ctx.getPackageManager().getLaunchIntentForPackage(
        ctx.getPackageName())
    Intent = autoclass("android.content.Intent")
    intent.setFlags(Intent.FLAG_ACTIVITY_SINGLE_TOP |
                    Intent.FLAG_ACTIVITY_CLEAR_TOP |
                    Intent.FLAG_ACTIVITY_NEW_TASK)
    intent.putExtra("fext_peer", peer)
    PendingIntent = autoclass("android.app.PendingIntent")
    flags = PendingIntent.FLAG_UPDATE_CURRENT
    if android_sdk() >= 23:
        flags |= PendingIntent.FLAG_IMMUTABLE    # mandatory from Android 12
    builder.setContentIntent(PendingIntent.getActivity(
        ctx, _notification_id(peer), intent, flags))
    manager.notify(_notification_id(peer), builder.build())


# ---- v11: notifications drawn by org.fext.notify.Notifier ---------------------
# A chat's notification lists its unread messages (MessagingStyle) and can
# be answered or marked read from the shade; an incoming call rings over the
# lock screen with Answer and Decline. What is done to one from the shade is
# written by NotifyReceiver.java as a small file in COMMANDS_DIR, and acted
# on by whichever sync worker is running (MessagingMixin.run_commands).
NOTIFY_LINES = 7                   # unread messages a chat's notification shows
CALL_NOTIFICATION_ID = 900         # the one incoming call (Notifier.java)
COMMANDS_DIR = DATA_DIR / "commands"


def _notifier():
    """org.fext.notify.Notifier, or None (an APK built without it)."""
    try:
        autoclass, _ = _jni()
        return autoclass("org.fext.notify.Notifier")
    except Exception:
        return None


def notification_lines(store: "LocalStore", peer: str) -> list:
    """[(author address or None, text, ms), …]: a chat's unread messages,
    oldest first, as its notification lists them."""
    out = []
    for msg in store.unread_messages(peer, NOTIFY_LINES):
        kind = msg.get("kind") or "text"
        text = message_text(msg)
        if kind == "image":
            text = tr("Photo · {caption}", caption=text) if text else \
                tr("Photo")
        elif kind in ("voice", "video"):
            text = shown_body(kind, msg.get("body") or "") or \
                tr(QUOTE_NAMES[kind])
        try:
            at = datetime.fromisoformat(str(msg["created_at"]).replace(
                "Z", "+00:00")).timestamp()
        except (TypeError, ValueError):
            at = time.time()
        out.append((msg.get("author"), single_line_text(text, 300),
                    int(at * 1000)))
    return out


def android_message_notification(app, peer: str, title: str,
                                 fallback: str) -> None:
    """Post (or update) a chat's notification: its unread messages, with
    Reply and Mark as read. Falls back to a plain one without Notifier."""
    notifier = _notifier()
    lines = notification_lines(app.store, peer) if notifier else []
    if notifier is None or not lines:
        android_notify(peer, title, fallback)
        return
    group = peer.startswith(GROUP_PREFIX)
    senders = []
    for author, _text, _at in lines:
        if not group:
            senders.append(title)
            continue
        contact = app.store.get_contact(author or "") or {}
        senders.append(person_name(contact, author or "", 10))
    count = len(app.store.unread_for(peer))
    notifier.messages(
        android_context(), _notification_id(peer), peer, title, group,
        senders, [t for _a, t, _w in lines], [w for _a, _t, w in lines],
        not app.store.is_blocked(peer) and app.conversation_kind(peer) !=
        "self", app.keys.address,
        trn("{n} new message", "{n} new messages", count))


def android_notification_words() -> None:
    """Give Notifier.java its words in the app's language: the channels'
    names, Reply, Answer… It keeps them for when the app is not running."""
    notifier = _notifier() if IS_ANDROID else None
    if notifier is None:
        return
    words = {"messages": tr("Messages"), "messages_about": tr("New messages"),
             "calls": tr("Calls"), "calls_about": tr("Incoming voice calls"),
             "you": tr("You"), "reply": tr("Reply"),
             "read": tr("Mark as read"), "incoming": tr("Incoming voice call"),
             "decline": tr("Decline"), "answer": tr("Answer"),
             "ready": tr("Ready for new messages"),
             "service": tr("Receive messages while closed")}
    try:
        notifier.setWords(android_context(), list(words),
                          list(words.values()))
    except Exception:
        log.exception("could not give the notifications their words")


def android_call_notification(app, peer: str, call_id: str,
                              name: str) -> bool:
    """Ring for an incoming call while the app is not on screen: over the
    lock screen where Android allows it, with Answer and Decline."""
    notifier = _notifier()
    if notifier is None:
        return False
    notifier.incomingCall(android_context(), CALL_NOTIFICATION_ID, peer,
                          call_id, name, app.keys.address)
    return True


def android_full_screen_allowed() -> bool:
    """Whether a call may ring over the lock screen (Android 14 asks)."""
    if not IS_ANDROID:
        return True
    notifier = _notifier()
    try:
        return notifier is None or bool(notifier.fullScreenAllowed(
            android_context()))
    except Exception:
        return True


def android_open_full_screen_settings() -> None:
    """Android 14's page for letting this app ring over the lock screen."""
