class AttachPreviewModal(Sheet):
    """See the photo and add a caption before it is compressed and sent.
    A `temporary` photo (a copy this app made) is deleted once it has been
    sent, or set aside."""

    def __init__(self, app: "FextApp", path: str,
                 temporary: bool = False) -> None:
        super().__init__(tr("Send photo"))
        self.app, self.path, self.temporary = app, path, temporary
        self._sent = False
        if temporary:
            self.bind(on_dismiss=lambda *_a: None if self._sent
                      else discard_media_file(self.path))
        self.add(KivyImage(source=path, allow_stretch=True, keep_ratio=True,
                           size_hint_y=None,
                           height=min(dp(300), Window.height * 0.4)))
        self.caption = self.add(Field(hint=tr("Add a caption…"),
                                      on_enter=self._send))
        self.add(hint(tr("Sent compressed, with its location and camera "
                         "details removed.")))
        self.add(button_row(Btn(tr("Cancel"), kind="quiet",
                                on_release=lambda _w: self.dismiss()),
                            Btn(tr("Send"),
                                on_release=lambda _w: self._send())))

    def _send(self) -> None:
        self._sent = True
        self.dismiss()
        self.app.send_image(self.path, sanitize_text(self.caption.text),
                            temporary=self.temporary)


class VideoNoteSheet(Sheet):
    """Recording a video message (18.1): what the camera sees (as a
    mirror, like a call's own picture), Record, then the time against the
    minute it may last, Delete and Send. When the minute is up it is sent
    by itself, as a voice message is at its limit. Once it records, only
    Delete and Send close it: a tap beside it must not lose a recording.
    It stops where it is (stop_here) when the camera fails, a call begins
    on this device or the app leaves the screen: what was recorded waits
    for Send or Delete."""

    def __init__(self, app: "FextApp", recorder: "VideoNoteRecorder",
                 note: str = "") -> None:
        super().__init__(tr("Video message"))
        self.app, self.recorder = app, recorder
        self._serial, self._texture, self._sent = 0, None, False
        self._stopped = False
        self.view = self.add(KivyImage(
            allow_stretch=True, keep_ratio=True, size_hint_y=None,
            height=min(dp(360), Window.height * 0.5)))
        most = recorder.max_seconds      # less where the relay takes less
        self.time = self.add(InfoLabel(
            tr("Up to a minute, with sound") if most == MAX_VIDEO_SECONDS
            else tr("Up to {time}, with sound", time=call_clock(most)),
            color=T.text_2, halign="center"))
        if note:
            self.add(hint(note))
        self.record = Btn(tr("Record"), on_release=lambda _w: self._record())
        buttons = [Btn(tr("Cancel"), kind="quiet",
                       on_release=lambda _w: self.dismiss())]
        if hasattr(recorder.coder, "flip"):          # a phone's two cameras
            buttons.append(Btn(tr("Other camera"), kind="quiet",
                               on_release=lambda _w: recorder.flip()))
        self.before = self.add(button_row(*buttons, self.record))
        self.during = button_row(
            Btn(tr("Delete"), kind="quiet",
                on_release=lambda _w: self.dismiss()),
            Btn(tr("Send"), on_release=lambda _w: self._send()))
        self._tick = Clock.schedule_interval(self._draw, 1 / 24)
        self.bind(on_dismiss=self._closed)

    def _draw(self, _dt) -> None:
        recorder = self.recorder
        got = recorder.preview((int(self.view.width), int(self.view.height)))
        if got is not None and got[0] != self._serial:
            self._serial = got[0]
            self._texture = frame_texture(self._texture, got[1:], True)
            if self.view.texture is not self._texture:
                self.view.texture = self._texture
            self.view.canvas.ask_update()
        if recorder.recording and recorder.error:
            self.stop_here()                         # the camera failed
        if self._stopped:
            self.time.text = tr("Recording stopped at {time}",
                                time=call_clock(recorder.elapsed_ms // 1000))
        elif recorder.recording:
            self.time.text = tr("Recording · {time} of {most}",
                                time=call_clock(recorder.elapsed_ms // 1000),
                                most=call_clock(recorder.max_seconds))
            if recorder.ended:
                self._send()
        elif recorder.coder.error:
            self.time.text = tr("Couldn't open the camera")
            self.record.disabled = True

    def _record(self) -> None:
        try:
            self.recorder.start()
        except Exception as exc:
            log.warning("could not start a video message: %s", exc)
            self.app._set_status(tr("Couldn't start recording — is a "
                                    "microphone connected?"), T.alert)
            self.dismiss()
            return
        self.time.color = C(T.alert)
        self.auto_dismiss = False        # no tap beside it, no Back
        self.body.remove_widget(self.before)
        self.add(self.during)

    def stop_here(self) -> None:
        """Nothing more is recorded: the camera failed, a call began on
        this device or the app left the screen. The camera and the
        microphone are let go at once; what was recorded waits for Send
        or Delete. A sheet that was not recording yet closes."""
        if not self.recorder.recording:
            self.dismiss()
        elif not self._stopped:
            self._stopped = True
            self.time.color = C(T.text_2)
            try:
                self.recorder.stop()
            except Exception:
                log.exception("a video message's recording would not stop")

    def _send(self) -> None:
        if self._sent:
            return
        if self.recorder.elapsed_ms < 700:        # as a voice message
            self.app._set_status(tr("That was too short to send"), T.accent)
        else:
            self._sent = True
            self.app.send_video(self.recorder)
        self.dismiss()

    def _closed(self, *_a) -> None:
        self._tick.cancel()
        if not self._sent:
            self.recorder.cancel()


class _CropFrame(StencilView):
    """The round window a picture is framed in. Only touches that start
    inside it are its own: the photo behind reaches far past its edges.
    A mouse wheel calls `on_zoom(factor, point)`."""

    def __init__(self, on_zoom: Callable, **kw):
        super().__init__(**kw)
        self._on_zoom = on_zoom

    def on_touch_down(self, touch):
        if not self.collide_point(*touch.pos):
            return False
        if touch.is_mouse_scrolling:
            if touch.button in ("scrolldown", "scrollup"):
                self._on_zoom(1.12 if touch.button == "scrolldown"
                              else 1 / 1.12, touch.pos)
            return True
        return super().on_touch_down(touch)


_CROP_SHADE: dict = {}


def crop_shade_texture():
    """Dark outside a circle, clear inside, with a smooth edge: laid over
    the photo being framed, it shows what the round picture will hold."""
    if "tex" not in _CROP_SHADE:
        from PIL import Image, ImageDraw
        side = 512
        big = Image.new("L", (side * 4, side * 4), 150)
        ImageDraw.Draw(big).ellipse((0, 0, side * 4 - 1, side * 4 - 1),
                                    fill=0)
        shade = Image.new("RGBA", (side, side), (0, 0, 0, 0))
        shade.putalpha(big.resize((side, side), Image.LANCZOS))
        _CROP_SHADE["tex"] = texture_from_pil(shade)
    return _CROP_SHADE["tex"]


class PictureCropSheet(Sheet):
    """Frame a picture: the photo behind a round window — drag it into
    place, pinch (or scroll) to size it. What the circle holds becomes the
    picture; `on_done(jpeg_bytes)` gets it. A `temporary` photo (a copy this
    app made) is deleted when the sheet closes."""

    ZOOM = 4.0                       # at most this far past "just covers"

    def __init__(self, path: str, on_done: Callable[[bytes], None],
                 title: str = "",
                 temporary: bool = False) -> None:
        super().__init__(title or tr("Profile photo"))
        self.on_done, self.path, self.temporary = on_done, path, temporary
        self.image = open_picture_source(path)          # raises if unusable
        if temporary:
            self.bind(on_dismiss=lambda *_a: discard_media_file(self.path))
        side = int(min(dp(300), Window.width - dp(44), Window.height * 0.46))
        self.side = side
        holder = AnchorLayout(size_hint_y=None, height=side)
        self.view = RelativeLayout(size_hint=(None, None), size=(side, side))
        frame = _CropFrame(self.zoom, size_hint=(None, None),
                           size=(side, side))
        width, height = self.image.size
        self._cover = side / float(min(width, height))
        self.scatter = Scatter(do_rotation=False, auto_bring_to_front=False,
                               size_hint=(None, None), size=(width, height),
                               scale_min=self._cover,
                               scale_max=self._cover * self.ZOOM)
        self.scatter.add_widget(KivyImage(
            texture=texture_from_pil(self.image), size=(width, height),
            size_hint=(None, None), pos=(0, 0), allow_stretch=True,
            keep_ratio=False))
        frame.add_widget(self.scatter)
        self.view.add_widget(frame)
        shade = Widget(size_hint=(None, None), size=(side, side))
        with shade.canvas:
            Color(1, 1, 1, 1)
            Rectangle(texture=crop_shade_texture(), pos=(0, 0),
                      size=(side, side))
            Color(1, 1, 1, .85)
            SmoothLine(circle=(side / 2, side / 2, side / 2 - .5),
                       width=max(1.0, dp(.8)))
        self.view.add_widget(shade)
        holder.add_widget(self.view)
        # Outside the sheet's scrolling body, which would take every drag.
        self.card.add_widget(holder, index=1)
        self.scatter.scale = self._cover
        self.scatter.center = (side / 2, side / 2)
        self.scatter.bind(on_transform_with_touch=lambda *_a: self._clamp())
        self.add(hint(tr("Drag the photo to place it; pinch to make it "
                         "larger or smaller.") if IS_MOBILE else
                      tr("Drag the photo to place it; scroll to make it "
                         "larger or smaller.")))
        self.add(button_row(Btn(tr("Cancel"), kind="quiet",
                                on_release=lambda _w: self.dismiss()),
                            Btn(tr("Use photo"),
                                on_release=lambda _w: self._use())))
        self._fit()

    def zoom(self, factor: float, anchor) -> None:
        scatter = self.scatter
        target = min(max(scatter.scale * factor, scatter.scale_min),
                     scatter.scale_max)
        if target != scatter.scale:
            from kivy.graphics.transformation import Matrix
            step = target / scatter.scale
            scatter.apply_transform(Matrix().scale(step, step, step),
                                    anchor=anchor)
        self._clamp()

    def _clamp(self) -> None:
        """Keep the photo covering the whole window: never smaller than
        it, never pulled far enough to show what lies past its edge."""
        scatter, side = self.scatter, self.side
        if scatter.scale < self._cover:
            scatter.scale = self._cover
        (x, y), (w, h) = scatter.bbox
        dx = -x if x > 0 else (side - (x + w) if x + w < side else 0)
        dy = -y if y > 0 else (side - (y + h) if y + h < side else 0)
        if dx or dy:
            from kivy.graphics.transformation import Matrix
            scatter.apply_transform(Matrix().translate(dx, dy, 0))

    def crop_box(self) -> tuple:
        """The window, in the photo's pixels (left, top, right, bottom)."""
        width, height = self.image.size
        x0, y0 = self.scatter.to_local(0, 0)
        x1, y1 = self.scatter.to_local(self.side, self.side)
        left, right = max(0.0, min(x0, x1)), min(float(width), max(x0, x1))
        bottom, top = max(0.0, min(y0, y1)), min(float(height), max(y0, y1))
        edge = min(right - left, top - bottom)        # square, inside it
        return (left, height - bottom - edge, left + edge, height - bottom)

    def _use(self) -> None:
        try:
            data = picture_jpeg(self.image, self.crop_box())
        except Exception:
            log.exception("could not make the picture")
            return
        self.dismiss()
        self.on_done(data)


class CameraSheet(Sheet):
    """A photo from the computer's camera: what it sees, and a shutter."""

    def __init__(self, on_photo: Callable[[str], None]) -> None:
        super().__init__(tr("Take a photo"))
        from kivy.uix.camera import Camera as CameraView
        self.on_photo = on_photo
        self.view = CameraView(play=True, resolution=(1280, 720),
                               allow_stretch=True, keep_ratio=True,
                               size_hint_y=None,
                               height=min(dp(320), Window.height * 0.45))
        self.add(self.view)
        self.add(button_row(Btn(tr("Cancel"), kind="quiet",
                                on_release=lambda _w: self.dismiss()),
                            Btn(tr("Take photo"),
                                on_release=lambda _w: self._shoot())))
        self.bind(on_dismiss=lambda *_a: setattr(self.view, "play", False))

    def _shoot(self) -> None:
        texture = self.view.texture
        if texture is None:
            return
        MEDIA_DIR.mkdir(parents=True, exist_ok=True)
        path = str(MEDIA_DIR / f"shot_{uuid.uuid4().hex}.png")
        try:
            # Texture.save writes the texture's rows as they are stored.
            # A camera stores the picture's top row first and flips the
            # texture only for display (a negative height in its uvs); a
            # texture drawn by GL holds its bottom row first. Either way the
            # file must come out the way the picture is seen.
            texture.save(path, flipped=texture.uvsize[1] >= 0)
        except Exception:
            log.exception("could not save the camera's picture")
            return
        self.dismiss()
        self.on_photo(path)


