# =============================================================================
#  Swipes (v11, touch screens)
# =============================================================================
SWIPE_START = dp(16)    # this far sideways, and plainly more than up or down
SWIPE_REPLY = dp(64)    # a message slid this far to the left is replied to
SWIPE_MOUSE = False     # a computer's mouse drag selects text instead (tests)
SWIPE_KINDS = ("back", "menu", "reply")


def window_pos(widget, x: float, y: float) -> tuple:
    """Where a point a touch handler of `widget` was given lies on the
    window. A handler sees the touch in its parent's coordinates (a
    MotionEvent itself knows nothing of windows)."""
    parent = widget.parent
    return parent.to_window(x, y) if parent is not None else (x, y)


def hits(widget, wx: float, wy: float) -> bool:
    """Is window point (wx, wy) on `widget`? (collide_point wants the
    parent's coordinates — a scroll view's own are its contents'.)"""
    parent = widget.parent
    if parent is None:
        return False
    return widget.collide_point(*parent.to_widget(wx, wy))


def swiped(touch) -> bool:
    """Has a page taken this touch for a swipe (so it is no tap or hold)?"""
    return touch.ud.get("fext_swipe") in SWIPE_KINDS


def _take_touch(touch, owner) -> None:
    """A page takes a touch for a swipe: whatever else holds it lets go —
    a scroll view without passing it on as a tap, a button without
    firing."""
    for ref in list(touch.grab_list):
        widget = ref()
        if widget is None or widget is owner:
            continue
        touch.ungrab(widget)
        if isinstance(widget, ScrollView):
            touch.ud[widget._get_uid("svavoid")] = True
            if getattr(widget, "_touch", None) is touch:
                widget._touch = None
            Clock.unschedule(widget._change_touch_mode)
        elif isinstance(widget, ButtonBehavior):
            widget.state = "normal"


class SwipeGestures:
    """Sideways swipes on a page (v11). To the right: back to the page
    beneath, which shows as the page follows the finger — or, on the chat
    list, the menu comes in with it. To the left on a message: reply to it.
    A swipe is decided early, once plainly sideways, and taken from what
    lies below so it never also counts as a tap; where it may start is the
    page's to say (never in the composer or on a voice note's waveform).
    On a computer a mouse drag selects text instead."""

    def swipe_kind(self, touch, dx: float) -> Optional[str]:
        """'back', 'menu' or 'reply' for a swipe starting here, or None."""
        return None

    # ---- deciding --------------------------------------------------------------
    def on_touch_move(self, touch):
        page = touch.ud.get("fext_swipe_page")
        if page is self:
            if touch.grab_current is self:
                self._swipe_follow(touch)
            return True
        if page is None and touch.grab_current is None and \
                touch.ud.get("fext_swipe") is None and \
                (SWIPE_MOUSE or getattr(touch, "device", "") != "mouse"):
            dx, dy = touch.x - touch.ox, touch.y - touch.oy
            if abs(dy) > SWIPE_START and abs(dy) >= abs(dx):
                touch.ud["fext_swipe"] = "none"          # a scroll
            elif abs(dx) > SWIPE_START and abs(dx) > 1.8 * abs(dy):
                kind = self.swipe_kind(touch, dx)
                if kind and self._swipe_start(touch, kind):
                    touch.ud["fext_swipe"] = kind
                    _take_touch(touch, self)
                    touch.grab(self)
                    touch.ud["fext_swipe_page"] = self
                    touch.ud["fext_swipe_v"] = (touch.x, time.monotonic(), 0.0)
                    return True
                touch.ud["fext_swipe"] = "none"
        return super().on_touch_move(touch)

    def on_touch_up(self, touch):
        if touch.ud.get("fext_swipe_page") is self:
            if touch.grab_current is self:
                touch.ungrab(self)
                self._swipe_finish(touch)
            return True
        return super().on_touch_up(touch)

    # ---- following -----------------------------------------------------------------
    def _swipe_start(self, touch, kind: str) -> bool:
        if kind == "back":
            return self._back_begin()
        if kind == "menu":
            return self.app.drawer_drag_begin()
        if kind == "reply":
            return self.reply_swipe_begin(touch)
        return False

    def _swipe_follow(self, touch) -> None:
        x, t, _v = touch.ud["fext_swipe_v"]
        now = time.monotonic()
        if now > t:
            touch.ud["fext_swipe_v"] = (touch.x, now, (touch.x - x) / (now - t))
        dx = touch.x - touch.ox
        kind = touch.ud.get("fext_swipe")
        if kind == "back":
            self._back_follow(dx)
        elif kind == "menu":
            self.app.drawer_drag(dx)
        elif kind == "reply":
            self.reply_swipe_follow(dx)

    def _swipe_finish(self, touch) -> None:
        dx = touch.x - touch.ox
        speed = touch.ud.get("fext_swipe_v", (0, 0, 0.0))[2]
        kind = touch.ud.get("fext_swipe")
        if kind == "back":
            self._back_end(dx > self.width * 0.33 or
                           (speed > dp(800) and dx > dp(40)))
        elif kind == "menu":
            self.app.drawer_drag_end(dx, speed)
        elif kind == "reply":
            self.reply_swipe_end(dx)

    # ---- back: the page follows the finger, the one beneath shows -----------------
    def _back_begin(self) -> bool:
        app = self.app
        target = app.back_target()
        if target is None or app.manager.current != self.name:
            return False
        name, action = target
        sm = app.manager
        under = sm.get_screen(name)
        if name == "chats":
            app.repaint_list_if_stale()
        if under.parent is None:
            # Beneath this page, as LayerTransition lays it going back.
            super(ScreenManager, sm).add_widget(under, len(sm.children))
        under.x, under.opacity = sm.x, 1
        self._swipe_under, self._swipe_back = under, action
        return True

    def _back_follow(self, dx: float) -> None:
        sm = self.app.manager
        self.x = sm.x + max(0.0, dx)
        self.opacity = 1 - 0.3 * min(1.0, max(0.0, dx) / max(1, self.width))

    def _back_end(self, go: bool) -> None:
        sm, under = self.app.manager, self._swipe_under
        action = self._swipe_back

        def settle(*_a):
            if under.parent is not None and under is not sm.current_screen:
                sm.real_remove_widget(under)
            if go:
                self.app.navigate_instantly(action)
            self.x, self.opacity = sm.x, 1
        if motion(1):
            anim = Animation(x=sm.x + (self.width if go else 0),
                             opacity=0.6 if go else 1, d=0.13, t="out_quad")
            anim.bind(on_complete=settle)
            anim.start(self)
        else:
            settle()

    # ---- reply (ConversationScreen) ----------------------------------------------------
    def reply_swipe_begin(self, touch) -> bool:
        return False

    def reply_swipe_follow(self, dx: float) -> None:
        pass

    def reply_swipe_end(self, dx: float) -> None:
        pass


# =============================================================================
#  The chat list — the "home" screen
# =============================================================================
BULLET = "•"
FLEURON = "❦"                 # ❦ — the empty page's ornament


class CallButton(ButtonBehavior, BoxLayout):
    """A round call control with its name beneath. `kind` 'end' is red,
    'accept' green; a plain one fills in while it is on (mute, speaker).
    Drawn in the theme's colours, or another palette's (set_palette)."""

    def __init__(self, icon: str, caption: str, on_tap: Callable,
                 kind: str = "plain", **kw):
        kw.setdefault("size_hint", (None, None))
        kw.setdefault("size", (dp(88), dp(64) + dp(8) + line_height(13.5)))
        super().__init__(orientation="vertical", spacing=dp(8), **kw)
        self.icon, self.kind, self.on = icon, kind, False
        self.palette: Optional[dict] = None
        self.disc = Widget(size_hint=(None, None), size=(dp(64), dp(64)),
                           pos_hint={"center_x": .5})
        self.add_widget(self.disc)
        self.caption = Label(text=caption, font_size=fs(13.5),
                             color=C(T.text_2), size_hint_y=None,
                             height=line_height(13.5), halign="center")
        self.caption.bind(size=lambda w, v: setattr(w, "text_size", v))
        self.add_widget(self.caption)
        self.disc.bind(pos=self._draw, size=self._draw)
        self.bind(state=self._draw)
        self.bind(on_release=lambda _w: on_tap())
        self._draw()

    def set_on(self, on: bool, icon: Optional[str] = None,
               caption: Optional[str] = None) -> None:
        self.on = on
        if icon:
            self.icon = icon
        if caption:
            self.caption.text = caption
        self._draw()

    def set_palette(self, palette: Optional[dict]) -> None:
        """A THEMES palette to draw in (over a picture,
        picture_palette()); None: the theme's own."""
        if palette is not self.palette:
            self.palette = palette
            self._draw()

    def _draw(self, *_a) -> None:
        d = self.disc
        d.canvas.clear()
        p = self.palette or THEMES[T.name]
        self.caption.color = C(p["text_2"])
        if self.kind == "end":
            fill, ink = p["alert"], p["on_alert"]
        elif self.kind == "accept":
            fill, ink = p["ok"], p["on_alert"]
        elif self.on:
            fill, ink = p["text"], p["bg"]
        else:
            fill, ink = p["surface_hi"], p["text"]
        with d.canvas:
            Color(*C(fill))
            SmoothEllipse(pos=d.pos, size=d.size)
            if self.state == "down":
                Color(0, 0, 0, .18)
                SmoothEllipse(pos=d.pos, size=d.size)
            draw_icon(self.icon, d.center_x, d.center_y, dp(28), C(ink))


class CallPicture(Widget):
    """The other side of a 1-to-1 call (17.0): their camera filling the
    call's screen, or the screen they share, whole."""

    def __init__(self, frames: Callable, user: str, **kw) -> None:
        super().__init__(**kw)
        self.frames, self.user, self.track = frames, user, "v"
        self.bind(pos=self.refresh, size=self.refresh)

    def refresh(self, *_a) -> None:
        self.canvas.clear()
        tex = self.frames(self.user, self.track)
        if tex is None or not self.width:
            return
        tw, th = tex.size
        k = (max if self.track == "v" else min)(self.width / tw,
                                                 self.height / th)
        with self.canvas:
            Color(1, 1, 1, 1)
            Rectangle(texture=tex, size=(tw * k, th * k),
                      pos=(self.center_x - tw * k / 2,
                           self.center_y - th * k / 2))


class MeterBars(Widget):
    """Four bars, `lit` of them coloured (F16): red at one, the accent at
    two, the green of ok at three or four."""

    lit = NumericProperty(0)

    def __init__(self, **kw) -> None:
        kw.setdefault("size_hint", (None, None))
        kw.setdefault("size", (dp(20), dp(14)))
        super().__init__(**kw)
        self.bind(pos=self._draw, size=self._draw, lit=self._draw)

    def _draw(self, *_a) -> None:
        self.canvas.clear()
        tint = T.alert if self.lit == 1 else T.accent if self.lit == 2 \
            else T.ok
        gap = dp(2)
        width = (self.width - 3 * gap) / 4
        with self.canvas:
            for i in range(4):
                Color(*C(tint if i < self.lit else T.rule_strong))
                RoundedRectangle(pos=(self.x + i * (width + gap), self.y),
                                 size=(width, self.height * (.3 + .7 * i / 3)),
                                 radius=[dp(1)])


class CallMeter(ButtonBehavior, BoxLayout):
    """A call's way at a glance (F16, 17.2): its bars and a line (the way,
    the delay); a tap tells the numbers (FextApp.show_call_meter)."""

    def __init__(self, on_tap: Callable, **kw) -> None:
        kw.setdefault("size_hint", (None, None))
        kw.setdefault("height", TOUCH)             # a whole tap target
        kw.setdefault("spacing", dp(6))
        kw.setdefault("padding", [dp(8), 0])
        super().__init__(**kw)
        self.bars = MeterBars(pos_hint={"center_y": .5})
        self.label = single_line("", fs(13.5), T.text_3, size_hint_x=None)
        self.add_widget(self.bars)
        self.add_widget(self.label)
        self.bind(on_release=lambda _w: on_tap())
        self.set(0, "")

    def set(self, bars: int, text: str) -> None:
        self.bars.lit = bars
        self.label.text = text
        self.label.texture_update()
        self.label.width = self.label.texture_size[0]
        self.width = max(TOUCH, self.padding[0] + self.bars.width +
                         self.spacing + self.label.width + self.padding[2])


class ReactionSheet(Sheet):
    """React, in a group's call (17.2): the quick reactions in a row; the
    one tapped shows over your tile, for everyone, for a few seconds."""

    def __init__(self, on_pick: Callable[[str], None]) -> None:
        super().__init__(tr("React"))
        row = BoxLayout(size_hint_y=None, height=dp(56), spacing=dp(4))
        for emoji in QUICK_REACTIONS:
            row.add_widget(EmojiKey(emoji, lambda e: self._pick(on_pick, e),
                                    size=(dp(52), dp(52))))
        self.add(row)

    def _pick(self, on_pick: Callable[[str], None], emoji: str) -> None:
        self.dismiss()
        on_pick(emoji)


class WhenSheet(MenuSheet):
    """When (17.2, SCHEDULE): an hour from now, this evening, tomorrow
    morning or evening, or a time typed (Pick a time)."""

    def __init__(self, title: str, on_pick: Callable[[float], None]) -> None:
        items = [("clock", label, lambda at=at: on_pick(at))
                 for label, at in send_later_choices()]
        items.append(("edit", tr("Pick a time…"),
                      lambda: TimeSheet(title, on_pick).open()))
        super().__init__(items, title=title)


class TimeSheet(Sheet):
    """A time typed: HH:MM (the next one), or YYYY-MM-DD HH:MM."""

    def __init__(self, title: str, on_pick: Callable[[float], None]) -> None:
        super().__init__(title, subtitle=tr("HH:MM, or YYYY-MM-DD HH:MM, in "
                                            "this device's time"))
        self.on_pick = on_pick
        self.field = self.add(Field(label=tr("Time"), on_enter=self._set))
        self.status = self.status_label()
        self.add(Btn(tr("Set"), on_release=lambda _w: self._set()))

    def _set(self) -> None:
        at = parse_send_time(self.field.text)
        if at is None:
            self.set_status(self.status, tr("Not a time ahead"), T.alert)
            return
        self.dismiss()
        self.on_pick(at)


class PlanCardRow(AnchorLayout):
    """A planned call's card in the chat (17.2, SCHEDULE), on the side of
    whoever planned it: voice or video, when, and Join from a little before
    it until a while after."""

    def __init__(self, msg: dict, screen, **kw) -> None:
        kw.setdefault("size_hint_y", None)
        kw.setdefault("padding", [dp(12), dp(6)])
        super().__init__(anchor_x="right" if msg["direction"] == "out"
                         else "left", **kw)
        plan = message_ext(msg)["plan"]
        state = plan_state(plan)
        card = BoxLayout(orientation="vertical", size_hint=(None, None),
                         width=dp(300), padding=[dp(16), dp(12)],
                         spacing=dp(10))
        paint_round(card, T.surface_hi, radius=dp(16))
        top = BoxLayout(size_hint_y=None, height=dp(40), spacing=dp(12))
        top.add_widget(call_disc(plan["v"], state == "open"))
        words = BoxLayout(orientation="vertical")
        words.add_widget(single_line(tr("Planned video call") if plan["v"]
                                     else tr("Planned voice call"), fs(16),
                                     T.text, bold=True))
        words.add_widget(single_line(when_text(plan["at"]), fs(13.5),
                                     T.text_2))
        top.add_widget(words)
        card.add_widget(top)
        self.join = None
        if state == "open":
            self.join = Btn(tr("Join"), size_hint_y=None, height=dp(44),
                            on_release=lambda _w: screen.app.join_plan(
                                msg["peer"], plan))
            card.add_widget(self.join)
        elif state == "past":
            card.add_widget(single_line(
                tr("Its time has passed"), fs(13.5), T.text_3,
                size_hint_y=None, height=line_height(13.5)))
        card.height = sum(w.height for w in card.children) + dp(24) + \
            dp(10) * (len(card.children) - 1)
        self.add_widget(card)
        self.height = card.height + dp(12)


class CallMeterSheet(Sheet):
    """The numbers behind a call's bars (F16), measured here as it goes."""

