class RemoteRestartSheet(Sheet):
    """19.0.1: restart their computer from afar, saying first whether it
    will be back by itself (it signs in by itself, as it told)."""

    def __init__(self, app: "FextApp") -> None:
        call = app.call
        signs_in = (call.rc_state or {}).get("si") if call else None
        super().__init__(tr("Restart {name}'s computer?", name=app.call_name(
            call.peer) if call else ""), subtitle=tr(
            "It signs in by itself: Ferritext should be back within a few "
            "minutes, and connects again by itself.") if signs_in is True
            else tr("It does not sign in by itself: after the restart it "
                    "waits at the sign-in screen, and cannot be reached "
                    "until someone signs in.") if signs_in is False
            else tr("Ferritext connects again once it is back, if it signs "
                    "in by itself."))
        self.app = app
        self.add(button_row(
            Btn(tr("Cancel"), kind="quiet", on_release=lambda _w:
                self.dismiss()),
            Btn(tr("Restart"), kind="solid_danger", on_release=lambda _w:
                self._go())))

    def _go(self) -> None:
        self.dismiss()
        self.app.remote_ask({"op": "restart"})


class RemoteProgramsSheet(Sheet):
    """19.0.1: the windows open on their computer, as Task Manager's first
    page lists them: each closed from here (asked to close, as Task
    Manager's End task does; ended when it does not answer); one run as
    administrator only shown."""

    _open: Optional["RemoteProgramsSheet"] = None

    @classmethod
    def show(cls, app: "FextApp", programs: Optional[list]) -> None:
        sheet = cls._open
        if sheet is None or sheet.parent is None:
            sheet = cls._open = cls(app)
            sheet.open()
        sheet.fill(programs)

    def __init__(self, app: "FextApp") -> None:
        call = app.call
        super().__init__(tr("Programs on {name}'s computer",
                            name=app.call_name(call.peer) if call else ""))
        self.app = app

    def fill(self, programs: Optional[list]) -> None:
        self.body.clear_widgets()
        if programs is None:
            self.add(hint(tr("That computer cannot list its programs from "
                             "afar.")))
            return
        rows = []
        for p in programs:
            words = p["x"] + (" · " + tr("runs as administrator")
                              if p["a"] else "") + (
                " · " + tr("not answering") if p["h"] else "")
            close = None
            if not p["a"]:
                close = Btn(tr("End task") if p["h"] else tr("Close"),
                            kind="text", size_hint_x=None,
                            pos_hint={"center_y": .5},
                            on_release=lambda _w, q=p: self.app.remote_ask(
                                {"op": "end", "w": q["w"], "p": q["p"]}))
                close.width = close.natural_width() + dp(8)
            rows.append(ListRow("screen", p["t"], words, control=close))
        self.add(rows_card(rows, inset=0) if rows else
                 hint(tr("No windows are open on it.")))
        self.add(Btn(tr("Refresh"), kind="quiet", on_release=lambda _w:
                     self.app.remote_programs()))


class PinsSheet(Sheet):
    """19.0 (PINS26): every pinned message of a chat, newest pin first,
    with who wrote it and when: a tap shows it; Unpin each, Unpin all,
    for those who may."""

    def __init__(self, app: "FextApp", peer: str) -> None:
        super().__init__(tr("Pinned messages"))
        self.app, self.peer = app, peer
        self._fill()

    def _fill(self) -> None:
        self.body.clear_widgets()
        app, peer = self.app, self.peer
        pins = app.conversation_screen.in_topic(app.store.pins(peer))
        may = app.can_pin(peer)
        rows = []
        for msg in pins:
            unpin = None
            if may:
                unpin = Btn(tr("Unpin"), kind="text", size_hint_x=None,
                            pos_hint={"center_y": .5},
                            on_release=lambda _w, c=msg["client_msg_id"]:
                            self._unpin(c))
                unpin.width = unpin.natural_width() + dp(8)
            who = tr("You") if msg["direction"] == "out" else \
                app.conversation_screen.author_name(msg.get("author") or peer)
            try:
                when = when_text(datetime.fromisoformat(
                    msg["created_at"]).timestamp())
            except (TypeError, ValueError):
                when = ""
            rows.append(ListRow(
                "pin", pin_line(msg), tr("{who} · {when}", who=who,
                                         when=when) if when else who,
                control=unpin, on_tap=lambda c=msg["client_msg_id"]:
                self._show(c)))
        if not rows:
            self.add(hint(tr("Nothing is pinned here.")))
            return
        self.add(rows_card(rows, inset=0))
        if may and len(rows) > 1:
            self.add(Btn(tr("Unpin all"), kind="quiet",
                         on_release=lambda _w: self._unpin_all()))

    def _show(self, cid: str) -> None:
        self.dismiss()
        Clock.schedule_once(
            lambda _dt: self.app.conversation_screen.jump_to_cid(cid), 0.1)

    def _unpin(self, cid: str) -> None:
        self.app.pin_message(self.peer, cid, False)
        self._fill()

    def _unpin_all(self) -> None:
        self.app.unpin_all(self.peer)
        self.dismiss()


class RemoteAccessSheet(Sheet):
    """19.0 (REMOTE): who may connect to this computer while nobody is at
    it, each until a date; what it takes to come back by itself after a
    restart; the last sessions. The list is this identity's, kept on this
    computer only (prefs.json)."""

    def __init__(self, app: "FextApp") -> None:
        super().__init__(tr("Remote access"), subtitle=tr(
            "Someone listed here can connect to this computer from your "
            "chat's menu while you are away. It answers by itself, without "
            "sound, shares its whole screen and lets them control it; a red "
            "bar on it says who, with Stop."))
        self.app = app
        self._fill()

    def _fill(self) -> None:
        self.body.clear_widgets()
        rows = []
        for entry in remote_access_list(self.app.keys.address):
            remove = Btn(tr("Remove"), kind="text", size_hint_x=None,
                         pos_hint={"center_y": .5},
                         on_release=lambda _w, a=entry["a"]: self._remove(a))
            remove.width = remove.natural_width() + dp(8)
            rows.append(ListRow(
                "person", self._name(entry["a"]),
                tr("Until {when}", when=when_text(entry["until"]))
                if entry["until"] else tr("Until you remove them"),
                control=remove))
        self.add(rows_card(rows, inset=0) if rows else hint(tr(
            "No one is listed: this computer answers no remote session.")))
        soon = [e for e in remote_access_list(self.app.keys.address)
                if e["until"] and e["until"] - time.time() < 30 * 86400]
        if soon:                                         # 19.0.1
            self.add(hint(tr(
                "Away for longer? A grant that ends while you are away "
                "cannot be made longer from afar except by someone "
                "connected: choose Until I remove them, or a year.")))
        self.status = self.status_label()
        self.add(Btn(tr("Add someone…"), kind="quiet",
                     on_release=lambda _w: self._pick()))
        # 19.0.1 (REMOTE191): this computer's name, as the people listed
        # see it when they choose among an identity's computers.
        rename = Btn(tr("Rename"), kind="text", size_hint_x=None,
                     pos_hint={"center_y": .5},
                     on_release=lambda _w: self._rename())
        rename.width = rename.natural_width() + dp(8)
        self.add(SectionHead(tr("This computer")))
        self.add(rows_card([ListRow("screen", device_name(), tr(
            "What the people listed see it as"), control=rename)], inset=0))
        self.add(SectionHead(tr("Before you leave")))
        self.add(rows_card(self._checklist(), inset=0))
        self.add(hint(tr(
            "Whoever is listed uses this computer as you would: its files, "
            "and Ferritext with every identity in it, unless the app lock is "
            "on (it then asks for its code when a session starts). Windows "
            "lets no one control its sign-in or lock screen, or a program "
            "run as administrator. Whoever holds a listed person's keys can "
            "reach this computer: list only people you trust.")))
        sessions = remote_sessions()[:5]
        if sessions:
            self.add(SectionHead(tr("Last sessions")))
            self.add(rows_card([ListRow(
                "clock", self._name(str(s.get("who", ""))), tr(
                    "{when} · {minutes} min · by the access list"
                    if s.get("kind") == "away" else
                    "{when} · {minutes} min · allowed here",
                    when=when_text(s.get("start") or 0),
                    minutes=max(1, round(((s.get("end") or 0) -
                                          (s.get("start") or 0)) / 60))))
                for s in sessions], inset=0))

    def _name(self, address: str) -> str:
        return person_name(self.app.store.get_contact(address) or {},
                           address, 14)

    def _checklist(self) -> list:
        """19.0.1: remote_checklist, a row each: done (a tick) or to do;
        the ones Ferritext sets, with their switch."""
        switches = {"start": self._on_start, "keepup": self._on_keepup,
                    "awake": self._on_awake}
        rows = []
        for key, ok, title, words in remote_checklist():
            control = None
            if key in switches and ok is not None:
                control = ToggleSwitch(bool(ok), switches[key])
            rows.append(ListRow("check" if ok else "info", title, words,
                                control=control))
        return rows

    def _on_keepup(self, on: bool) -> None:
        save_pref("remote_keepup", bool(on))
        self.app.apply_keep_awake()

    def _rename(self) -> None:
        DeviceNameSheet(lambda name: (save_pref("device_name", name),
                                      self._fill())).open()

    def _on_start(self, on: bool) -> None:
        if not set_starts_by_itself(on):
            self.set_status(self.status, tr("The system did not take that "
                                            "setting"), T.alert)

    def _on_awake(self, on: bool) -> None:
        save_pref("remote_awake", bool(on))
        self.app.apply_keep_awake()

    def _remove(self, address: str) -> None:
        remote_access_revoke(self.app.keys.address, address)
        self.app.apply_keep_awake()
        self._fill()

    def _pick(self) -> None:
        """Someone to list: an accepted contact, not blocked, not this
        device's own identity, not listed yet."""
        app = self.app
        listed = {e["a"] for e in remote_access_list(app.keys.address)}
        people = [c for c in app.store.contacts()
                  if c["address"] not in listed and c.get("accepted") and
                  not app.store.is_blocked(c["address"]) and
                  app.keys.find(c["address"]) is None]
        if not people:
            self.set_status(self.status, tr("No other contact to add"),
                            T.text_2)
            return
        MenuSheet([("person", person_name(c, c["address"], 14),
                    lambda a=c["address"]: self._chosen(a)) for c in people],
                  title=tr("Who may connect?")).open()

    def _chosen(self, address: str) -> None:
        """Verified first (their safety code), then for how long."""
        name = self._name(address)
        if not (self.app.store.get_contact(address) or {}).get("verified"):
            MenuSheet([("lock", tr("Verify {name}…", name=name),
                        lambda: self.app.open_verify(address))],
                      title=tr("Verify {name} first", name=name),
                      subtitle=tr("Compare your safety codes, in person or "
                                  "on a call: then it is surely them who "
                                  "connects.")).open()
            return
        MenuSheet([("clock", tr(words), lambda d=days: self._grant(address, d))
                   for days, words in REMOTE_GRANTS],
                  title=tr("{name} may connect for…", name=name)).open()

    def _grant(self, address: str, days: int) -> None:
        remote_access_grant(self.app.keys.address, address, days)
        self.app.apply_keep_awake()
        self._fill()


class CallOverlay(ModalView):
    """The call, full screen: who, how far along (or how long), which way
    the sound goes, and the controls — answer or decline while it rings;
    mute, the camera, loudspeaker (a phone) or the screen (a computer) and
    hang up once it is on. 17.0: their camera fills it, this device's own
    is in a corner (a tap there turns a phone to its other camera)."""

    def __init__(self, app: "FextApp", call: "Call") -> None:
        super().__init__(size_hint=(1, 1), auto_dismiss=False,
                         background_color=(0, 0, 0, 0),
                         overlay_color=(0, 0, 0, 0))
        self.app, self.call = app, call
        self._layout = None
        self._view_keys = None
        self._view: dict = {}          # (user, track) -> what draws it
        contact = app.store.get_contact(call.peer) if app.store else None
        name = person_name(contact, call.peer, 14)
        stack = FloatLayout()
        backdrop = Widget(size_hint=(1, 1), pos_hint={"x": 0, "y": 0})
        paint_round(backdrop, T.bg, radius=0)
        stack.add_widget(backdrop)
        # 17.1: around their picture (a shared screen, letterboxed on a
        # phone) the bands' own dark, so the words over it stay readable.
        self.letterbox = Widget(size_hint=(1, 1), pos_hint={"x": 0, "y": 0},
                                opacity=0)
        paint_round(self.letterbox, picture_palette()["bg"], radius=0)
        stack.add_widget(self.letterbox)
        self.picture = CallPicture(app.call_frames, call.peer,
                                   size_hint=(1, 1),
                                   pos_hint={"x": 0, "y": 0})
        stack.add_widget(self.picture)
        # 19.0 (REMOTE): over their shared screen while this side controls
        # it: the pointer, a finger and the keys go to their computer.
        self.remote = RemoteSurface(self.picture, app.send_remote_input,
                                    size_hint=(1, 1),
                                    pos_hint={"x": 0, "y": 0})
        stack.add_widget(self.remote)
        # Over a picture, a dark band at the top and the bottom keeps the
        # words and the controls readable (17.0).
        self.scrim = Widget(size_hint=(1, 1), pos_hint={"x": 0, "y": 0},
                            opacity=0)
        self.scrim.bind(pos=self._draw_scrim, size=self._draw_scrim)
        stack.add_widget(self.scrim)
        # Placed by its pos_hint: beside the chats (17.2) the stack is not
        # at the window's left edge, and a FloatLayout moves only children
        # that have one.
        root = BoxLayout(orientation="vertical",
                         padding=[dp(24), dp(34), dp(24), dp(40)],
                         spacing=dp(6), pos_hint={"x": 0, "y": 0})
        self.kicker = CapsLabel(tr("Voice call · sealed end to end"),
                                size=10.5, color=T.text_3, halign="center")
        root.add_widget(self.kicker)
        self.top_gap = Widget(size_hint_y=.22)
        root.add_widget(self.top_gap)
        self.disc = AnchorLayout(size_hint_y=None, height=dp(136))
        self.disc.add_widget(Avatar(call.peer, name, diameter=dp(128)))
        root.add_widget(self.disc)
        root.add_widget(Widget(size_hint_y=None, height=dp(14)))
        self.name_label = InfoLabel(name, font_size=fs(28), halign="center")
        root.add_widget(self.name_label)
        self.status = single_line("", fs(17), T.text_2, italic=True,
                                  halign="center", size_hint_y=None,
                                  height=line_height(17) + dp(4))
        root.add_widget(self.status)
        # 17.2 (F16): the way's bars beside it; a tap tells the numbers.
        self.meter = CallMeter(app.show_call_meter)
        meter_row = AnchorLayout(size_hint_y=None, height=self.meter.height)
        meter_row.add_widget(self.meter)
        root.add_widget(meter_row)
        self.detail = self.meter.label
        root.add_widget(Widget())
        self.controls = BoxLayout(size_hint_y=None, height=dp(110),
                                  spacing=dp(10))
        root.add_widget(self.controls)
        stack.add_widget(root)
        session = call.session
        narrow = call_is_narrow()
        self.mine = self.face = None
        if session is not None:
            corner = (dp(104), dp(138)) if narrow else (dp(208), dp(117))
            self.mine = CallTile(
                session, session.me.user, "v", app.call_frames, tr("You"),
                disc=dp(34), size_hint=(None, None), size=corner,
                pos_hint={"right": .96, "top": .76 if narrow else .965},
                on_pin=lambda *_a: app.flip_call_camera())
            # 17.1 (multi-view): their face, while they share their screen
            # with their camera on, in the corner across from this one's.
            self.face = CallTile(
                session, call.peer, "v", app.call_frames, name, disc=dp(34),
                size_hint=(None, None), size=corner,
                pos_hint={"x": .04, "y": .24})
            for tile in (self.mine, self.face):
                tile.opacity, tile.disabled = 0, True
                stack.add_widget(tile)
        # Top left: More (17.2: the call's way and time, sound, picture in
        # picture, Settings), and a computer's Record.
        corner_box = BoxLayout(size_hint=(None, None), height=TOUCH,
                               spacing=dp(4), pos_hint={"x": .01,
                                                        "top": .985})
        self.more = IconButton("more", label=tr("More"))
        self.more.bind(on_release=lambda _w: app.call_more())
        corner_box.add_widget(self.more)
        self.record = None
        if call_recording_allowed() and not IS_MOBILE:
            self.record = IconButton("record", label=tr("Record"))
            self.record.bind(on_release=lambda _w: app.toggle_recording())
            corner_box.add_widget(self.record)
        corner_box.width = len(corner_box.children) * (TOUCH + dp(4))
        stack.add_widget(corner_box)
        # 17.3 (REACT1): a reaction over each side for a few seconds, as a
        # group's tiles show them (show_reactions), placed again whenever
        # the layout moves.
        self.their_reaction = Label(text="", font_size=sp(48),
                                    size_hint=(None, None),
                                    size=(dp(72), dp(72)))
        self.my_reaction = Label(text="", font_size=sp(36),
                                 size_hint=(None, None),
                                 size=(dp(56), dp(56)))
        stack.add_widget(self.their_reaction)
        stack.add_widget(self.my_reaction)
        stack.bind(pos=self.show_reactions, size=self.show_reactions)
        self.disc.bind(pos=self.show_reactions)
        # 19.0 (REMOTE): who is in control, at the top over everything,
        # with Stop (this computer) or Release (the side controlling).
        self.remote_band = BoxLayout(size_hint=(1, None),
                                     height=TOUCH + dp(12),
                                     padding=[dp(14), dp(6)], spacing=dp(10),
                                     pos_hint={"x": 0, "top": 1},
                                     opacity=0, disabled=True)
        paint_round(self.remote_band, T.alert, radius=0)
        self.remote_words = single_line("", fs(15), T.on_alert, bold=True)
        self.remote_band.add_widget(self.remote_words)
        self.remote_button = Btn(tr("Stop"), kind="quiet",
                                 size_hint_x=None, width=dp(110),
                                 on_release=lambda _w: self._remote_end())
        self.remote_band.add_widget(self.remote_button)
        stack.add_widget(self.remote_band)
        # 19.0.1 (REMOTE191): under it, for the side controlling, what
        # their computer says that matters (a security screen, a window run
        # as administrator in front, the access's end soon).
        self.remote_note = BoxLayout(size_hint=(1, None), height=0,
                                     padding=[dp(14), dp(8)], opacity=0,
                                     pos_hint={"x": 0, "top": 1})
        paint_round(self.remote_note, T.accent, radius=0)
        self.remote_note_words = InfoLabel("", font_size=fs(14),
                                           color=T.on_accent)
        self.remote_note.add_widget(self.remote_note_words)
        self.remote_note_words.bind(height=lambda *_a: self._place_note())
        stack.add_widget(self.remote_note)
        stack.bind(size=lambda *_a: self._place_note())
        if call_is_wide():                      # 17.2: your chats beside
            beside = BoxLayout()
            beside.add_widget(app.call_chats_sidebar())
            beside.add_widget(stack)
            self.add_widget(beside)
        else:
            self.add_widget(stack)
        side = dp(76) if narrow else dp(88)
        kw = {"size": (side, dp(64) + dp(8) + line_height(13.5))}
        self.mute = CallButton("mic", tr("Mute"),
                               lambda: app.toggle_call_mute(), **kw)
        self.camera = CallButton("video_off", tr("Camera"),
                                 lambda: app.toggle_call_camera(), **kw)
        self.share = CallButton("screen", tr("Share screen"),
                                lambda: app.toggle_call_screen(), **kw)
        self.speaker = CallButton("speaker", tr("Speaker"),
                                  lambda: app.choose_call_route(), **kw)
        self.end = CallButton("phone_end", tr("End"), lambda: app.end_call(),
                              kind="end", **kw)
        # 19.0 (REMOTE): ask to control their shared screen, and a phone's
        # keyboard while controlling it.
        self.control = CallButton("pointer", tr("Control"),
                                  lambda: app.toggle_control(), **kw)
        self.typing_button = CallButton("keyboard", tr("Keyboard"),
                                        lambda: RemoteTypeSheet(
                                            app.send_remote_input).open(),
                                        **kw)
        # 19.0.1: the keys and the computer's own help (RemoteKeysSheet).
        self.keys_button = CallButton("key", tr("Keys"), lambda:
                                      RemoteKeysSheet(app).open(), **kw)
        self.decline = CallButton("phone_end", tr("Decline"),
                                  lambda: app.decline_call(), kind="end")
        self.accept = CallButton("phone", tr("Answer"),
                                 lambda: app.answer_call(), kind="accept")
        self.refresh()

    def show_reactions(self, *_a) -> None:
        """17.3 (REACT1): each side's reaction while it is fresh
        (reaction_fresh, CALL_REACTION_SECONDS). A side shown in a tile
        (your camera's corner; their face while they present) has it drawn
        there, as a group's tiles do. Otherwise theirs is by their disc, or
        over their picture, and yours over the screen's lower middle."""
        call, session = self.call, self.call.session
        if session is None:
            return
        tiles = [t for t in (self.mine, self.face)
                 if t is not None and t.opacity]
        for tile in tiles:
            tile.refresh()
        them = session.members.get(call.peer)
        theirs = them.reaction[0] if reaction_fresh(them) and \
            self.face not in tiles else ""
        mine = session.me.reaction[0] if reaction_fresh(session.me) and \
            self.mine not in tiles else ""
        self.their_reaction.text, self.my_reaction.text = theirs, mine
        stack = self.picture.parent
        self.their_reaction.center = (
            (self.disc.center_x + dp(54), self.disc.top - dp(10))
            if self.disc.opacity else
            (stack.center_x, stack.y + stack.height * .7))
        self.my_reaction.center = (stack.center_x,
                                   stack.y + stack.height * .3)

    def _draw_scrim(self, *_a) -> None:
        """The bands: a dark ground (picture_palette's) fading into the
        picture, over a third of the height at the top and a quarter at
        the bottom. 17.2: at full strength over the outer half of each,
        where the clock and the buttons' names are, so a light shared
        screen under them leaves them readable."""
        w = self.scrim
        w.canvas.clear()
        ramp = Texture.create(size=(1, 64), colorfmt="rgba")
        r, g, b = (int(c * 255) for c in C(picture_palette()["bg"])[:3])
        ramp.blit_buffer(bytes(v for i in range(64) for v in (
            r, g, b, int(230 * min(1.0, i / 63 / .5) ** 1.1))),
            colorfmt="rgba", bufferfmt="ubyte")
        with w.canvas:
            Color(1, 1, 1, 1)
            top = w.height * .34
            Rectangle(texture=ramp, pos=(w.x, w.top - top),
                      size=(w.width, top))
            Rectangle(texture=ramp, pos=w.pos, size=(w.width, w.height * .3),
                      tex_coords=(0, 1, 1, 1, 1, 0, 0, 0))

    def shows(self) -> dict:
        """Where their camera and screen are drawn, for their engine: the
        size of each (17.1: both, their face over their screen)."""
        return {t: video_box(w.size, t) for (u, t), w in self._view.items()
                if u == self.call.peer}

    def _arrange(self, layout: str) -> None:
        if layout == self._layout:
            return
        self._layout = layout
        self.controls.clear_widgets()
        if layout == "ringing":
            parts = [Widget(), self.decline, Widget(), self.accept, Widget()]
        elif layout == "ended":
            parts = []
        else:
            # 17.1: a voice call offers no camera (a video call is chosen
            # as one); the screen may still be shared from a computer.
            # 19.0 (REMOTE): a remote session has no sound, and its
            # computer shares its screen by itself: neither shows here.
            session, remote = self.call.session, self.call.remote
            parts = [] if remote else [Widget(), self.mute] + (
                [Widget(), self.camera] if session and session.video else [])
            if remote:
                pass
            elif self.app.call_audio_has_speaker():
                parts += [Widget(), self.speaker]
            elif not IS_MOBILE:
                parts += [Widget(), self.share]
            if "control" in layout:                  # 19.0 (REMOTE)
                parts += [Widget(), self.control]
            if "keys" in layout:
                parts += [Widget(), self.typing_button]
            if "+rk" in layout:                      # 19.0.1
                parts += [Widget(), self.keys_button]
            parts += [Widget(), self.end, Widget()]
        for part in parts:
            self.controls.add_widget(part)

    def refresh(self) -> None:
        call = self.call
        if call.ended:
            self.status.text = call.summary or tr("Call ended")
            self.detail.text = ""
            self._arrange("ended")
            return
        if call.state == "incoming":
            self._arrange("ringing")
        else:
            # 19.0 (REMOTE): Control to ask; a phone controlling has
            # Keyboard in its place (Release is in the band at the top).
            controls = self.app.can_ask_control(call) or call.asks
            controlling = self.app.controlling(call)
            typing = controls and IS_MOBILE and controlling
            self._arrange("call" + ("+keys" if typing else "+control"
                                    if controls else "") +
                          ("+rk" if controlling else ""))
        self.mute.set_on(call.muted, "mic_off" if call.muted else "mic",
                         tr("Unmute" if call.muted else "Mute"))
        route = getattr(call, "route", "") or (
            "speaker" if call.speaker else "earpiece")
        if route == "bluetooth":
            self.speaker.set_on(True, "bluetooth", tr("Bluetooth"))
        elif route == "wired":
            self.speaker.set_on(False, "speaker", tr("Headset"))
        else:
            self.speaker.set_on(call.speaker, "speaker", tr("Speaker"))
        if call.state == "active":
            self.status.text = tr("Reconnecting…") if call.quiet else \
                tr("Remote session · {time}", time=call_clock(
                    call.duration())) if call.remote else \
                call_clock(call.duration())
        elif call.remote and call.state in ("calling", "ringing"):   # 19.0
            self.status.text = tr("Connecting to their computer…")
        else:
            video = call.session is not None and call.session.video
            self.status.text = tr({
                "calling": N_("Calling…"), "ringing": N_("Ringing…"),
                "incoming": N_("Incoming video call") if video else
                N_("Incoming voice call"),
                "connecting": N_("Connecting…")}.get(call.state, ""))
        engine = call.engine
        on = call.state in ("active", "connecting") and engine is not None
        self.meter.set(meter_bars(engine.way, engine.rtt_ms) if on else 0,
                       call_path_label(call.path, engine.rtt_ms)
                       if on else "")
        self.meter.opacity, self.meter.disabled = (1, False) if on \
            else (0, True)
        self._pictures()

    def _pictures(self) -> None:
        """17.0: their camera (or screen) over the screen, the disc and
        name hidden under it; this device's own camera in its corner."""
        call, session = self.call, self.call.session
        them = session.members.get(call.peer) if session else None
        track = "s" if them and them.screen else (
            "v" if them and them.camera else None)
        mine = bool(session and session.me.camera)
        face = track == "s" and them.camera and presenter_face_shown()
        if self.picture.track != (track or "v"):
            self.picture.track = track or "v"
            self.picture.refresh()
        self.picture.opacity = self.scrim.opacity = \
            self.letterbox.opacity = 1 if track else 0
        # Over their picture, light words on dark bands in either theme.
        ink = self._ink()
        self.name_label.color = C(ink["text"])
        self.status.color = C(ink["text_2"])
        self.detail.color = C(ink["text_3"])
        for button in (self.mute, self.camera, self.share, self.speaker,
                       self.end):
            button.set_palette(ink if track else None)
        # Their picture fills the screen: the disc goes, and the name and
        # the clock move up under the kicker.
        self.disc.opacity = 0 if track else 1
        self.disc.height = 0 if track else dp(136)
        self.top_gap.size_hint_y = 0.02 if track else .22
        for tile, on in ((self.mine, mine), (self.face, face)):
            if tile is not None:
                if on and tile.opacity == 0:
                    tile.refresh()
                tile.opacity, tile.disabled = (1, False) if on else (0, True)
        self.camera.set_on(mine, "video" if mine else "video_off")
        self.share.set_on(bool(session and session.me.screen))
        self._remote_state(track)
        video = track or mine or (session and session.me.screen)
        self.kicker.text = tr("Video call · sealed end to end") if video \
            else tr("Voice call · sealed end to end")
        self.show_recording()
        view = {}
        if track:
            view[(call.peer, track)] = self.picture
        if face:
            view[(call.peer, "v")] = self.face
        if mine:
            view[(session.me.user, "v")] = self.mine
        if set(view) != self._view_keys and not call.ended:
            self._view_keys, self._view = set(view), view
            self.app.call_view(view)
            self.app.call_media_changed()

    def _remote_state(self, track: Optional[str]) -> None:
        """19.0 (REMOTE): the Control button, the band, and the surface
        over their screen, as the call's control now is."""
        call, app = self.call, self.app
        controlling = app.controlling(call) and track == "s"
        asked = call.asks
        self.control.set_on(asked, "pointer", tr(
            "Release" if controlling else "Asked…" if asked else "Control"))
        if controlling:
            self.remote.start()
        else:
            self.remote.stop()
        name = app.call_name(call.peer)
        if call.lets:
            words, button = tr("{name} is controlling this computer",
                               name=name), tr("Stop")
        elif controlling:
            words, button = tr("You are controlling {name}'s computer",
                               name=name), tr("Release")
        else:
            words = button = ""
        self.remote_words.text, self.remote_button.text = words, button
        on = bool(words) and not call.ended
        self.remote_band.opacity, self.remote_band.disabled = \
            (1, False) if on else (0, True)
        note = remote_note_words(call.rc_state, name) \
            if controlling and not call.ended else ""
        if note != self.remote_note_words.text:
            self.remote_note_words.text = note
        self._place_note()

    def _place_note(self) -> None:
        """19.0.1: the note under the red band, as tall as its words."""
        note, words = self.remote_note, self.remote_note_words
        note.height = words.height + dp(16) if words.text else 0
        note.opacity = 1 if words.text else 0
        stack = note.parent
        if stack is not None and stack.height:
            below = self.remote_band.height if self.remote_band.opacity \
                else 0
            note.pos_hint = {"x": 0, "top": 1 - below / stack.height}

    def _remote_end(self) -> None:
        """The band's Stop (this computer) or Release (the other side)."""
        if self.call.lets:
            self.app.stop_control(self.call, by_hand=True)
        else:
            self.app.release_control()

    def _ink(self) -> dict:
        """The colours of the words: picture_palette()'s over a picture,
        else the theme's."""
        return picture_palette() if self.picture.opacity else \
            THEMES[T.name]

    def show_recording(self) -> None:
        """A red mark while either side records the call (F13)."""
        session, ink = self.call.session, self._ink()
        on = session is not None and session.recording()
        if on:
            self.kicker.text = "● " + tr("Recording") + " · " + \
                tr("sealed end to end")
        self.kicker.set_color(ink["alert"] if on else ink["text_3"])
        if self.record is not None and session is not None:
            self.record.set_icon("record", ink["alert"] if
                                 session.me.recording else ink["text"])

    def forget_view(self) -> None:
        """Set aside: nothing drawn until it comes back."""
        self._view_keys, self._view = None, {}
        self.app.call_view({})
        self.remote.stop()                  # 19.0: no keys taken aside


class CallFloat(ButtonBehavior, Widget):
    """A call set aside (17.2, CALLUI): a small window over the app, which
    a finger or the pointer drags anywhere, with the other side's picture
    (a group's: whoever speaks) or their disc, over a line (the time
    running, or who calls); a tap goes back to the call (a 1-to-1 call's
    screen, or `back`: a group's). In 16.2's bar's place (CallPill)."""

    def __init__(self, app: "FextApp", back: Optional[Callable] = None,
                 **kw):
        super().__init__(size_hint=(None, None), **kw)
        self.app = app
        self.size = (dp(132), dp(176)) if call_is_narrow() \
            else (dp(240), dp(150))
        self.tile: Optional[CallTile] = None
        self.label = Label(font_size=fs(13), color=C(T.text),
                           halign="center", valign="middle",
                           shorten=True, shorten_from="right")
        self.add_widget(self.label)
        self._start = self._offset = None
        self._dragged = False
        self.bind(pos=self._draw, size=self._draw, state=self._draw)
        self.bind(on_release=lambda _w: (back or app.show_call)())
        Window.bind(size=self._keep_inside)
        self.pos = (Window.width - self.width - dp(16), dp(104))
        self._keep_inside()

    def show(self, session: "CallSession", user: str, name: str,
             frames: Callable, track: str = "v") -> None:
        """Whose picture (or disc) it shows: told so as the call goes."""
        tile = self.tile
        if tile is not None and (tile.user, tile.track) == (user, track):
            tile.refresh()
            return
        if tile is not None:
            self.remove_widget(tile)
        self.tile = CallTile(session, user, track, frames, name,
                             disc=dp(48), size_hint=(None, None))
        self.add_widget(self.tile, index=len(self.children))
        self._draw()

    def shows(self) -> dict:
        """Where it draws their picture, for their engine (a 1-to-1's)."""
        return {self.tile.track: video_box(self.tile.size, self.tile.track)
                } if self.tile else {}

    def view(self) -> dict:
        """{(user, track): tile}, for the call's pictures (call_view)."""
        return {(self.tile.user, self.tile.track): self.tile} \
            if self.tile else {}

    def _draw(self, *_a) -> None:
        line = line_height(13) + dp(10)
        r = corner(dp(16))
        if self.tile is not None:
            self.tile.pos = (self.x + dp(4), self.y + line)
            self.tile.size = (self.width - dp(8), self.height - line - dp(4))
        self.label.pos, self.label.size = self.pos, (self.width, line)
        self.label.text_size = self.label.size
        self.canvas.before.clear()
        with self.canvas.before:
            Color(0, 0, 0, .30 if T.dark else .14)
            SmoothRoundedRectangle(pos=(self.x, self.y - dp(3)),
                                   size=self.size, radius=[r])
            Color(*C(T.press if self.state == "down" and not self._dragged
                     else T.surface_hi))
            SmoothRoundedRectangle(pos=self.pos, size=self.size, radius=[r])

    # Every touch on it is its own (the tile inside takes none): a drag
    # moves it; a tap (moved less than a finger's slip) goes back.
    def on_touch_down(self, touch) -> bool:
        if not self.collide_point(*touch.pos):
            return False
        self._start, self._dragged = touch.pos, False
        self._offset = (touch.x - self.x, touch.y - self.y)
        touch.grab(self)
        self.state = "down"
        return True

    def on_touch_move(self, touch) -> bool:
        if touch.grab_current is not self:
            return False
        if abs(touch.x - self._start[0]) > dp(8) or \
                abs(touch.y - self._start[1]) > dp(8):
            self._dragged = True
        if self._dragged:
            self.pos = (touch.x - self._offset[0], touch.y - self._offset[1])
            self._keep_inside()
        return True

    def on_touch_up(self, touch) -> bool:
        if touch.grab_current is not self:
            return False
        touch.ungrab(self)
        self.state = "normal"
        tapped, self._start, self._dragged = not self._dragged, None, False
        if tapped:
            self.dispatch("on_release")
        return True

    def _keep_inside(self, *_a) -> None:
        self.x = min(max(dp(4), self.x), Window.width - self.width - dp(4))
        self.y = min(max(dp(4), self.y), Window.height - self.height - dp(4))

    def set_text(self, text: str) -> None:
        self.label.text = text

    def remove(self) -> None:
        Window.unbind(size=self._keep_inside)
        if self.parent is not None:
            self.parent.remove_widget(self)


# ---- 16.1: the call screens, drawn from a CallSession -----------------------
# What they draw is the session's (CallSession); a call's pictures come from
# `frames(user, track)`, a Texture or None (None: that person's disc). The
# sound and pictures themselves, and the relay's rooms, are the next steps
# of .private/CALLS_16_1.md; until then these screens open only in the
# tests and the capture tool.

def _no_frames(_user: str, _track: str):
    return None


def call_is_narrow() -> bool:
    """A phone's layout: one column, the controls in a thumb's reach."""
    return Window.width < dp(640)


#: 19.0 (TWOPANE26): a computer's window this wide or wider (dp) shows the
#: chat list docked on its left, SIDE_WIDTH wide, and the chat, or any
#: other page, on its right (FextApp._apply_panes).
TWO_PANES_FROM, SIDE_WIDTH = 900, 340


def two_panes() -> bool:
    """A computer's window wide enough for the list beside the chat."""
    return not IS_MOBILE and Window.width >= dp(TWO_PANES_FROM)


def desktop_area() -> Optional[tuple]:
    """(left, top, width, height) in pixels of every screen together, where
    it can be read (Windows; X11): a window put back where it was is kept
    on it. None elsewhere."""
    try:
        import ctypes
        if IS_WINDOWS:
            metric = ctypes.windll.user32.GetSystemMetrics
            return metric(76), metric(77), metric(78), metric(79)
        if sys.platform.startswith("linux") and os.environ.get("DISPLAY"):
            import ctypes.util
            x11 = ctypes.CDLL(ctypes.util.find_library("X11") or
                              "libX11.so.6")
            x11.XOpenDisplay.restype = ctypes.c_void_p
            x11.XOpenDisplay.argtypes = [ctypes.c_char_p]
            x11.XDisplayWidth.argtypes = x11.XDisplayHeight.argtypes = \
                [ctypes.c_void_p, ctypes.c_int]
            x11.XCloseDisplay.argtypes = [ctypes.c_void_p]
            dpy = x11.XOpenDisplay(None)
            if dpy:
                try:
                    return 0, 0, x11.XDisplayWidth(dpy, 0), \
                        x11.XDisplayHeight(dpy, 0)
                finally:
                    x11.XCloseDisplay(dpy)
    except (OSError, AttributeError):
        pass
    return None


def window_place_ok(place: dict, area: Optional[tuple]) -> bool:
    """A remembered window's place, still on the screens: its top left at
    least 100 pixels inside them."""
    if area is None:
        return False
    left, top, width, height = area
    try:
        x, y = int(place["x"]), int(place["y"])
    except (KeyError, TypeError, ValueError):
        return False
    return left <= x <= left + width - 100 and top <= y <= top + height - 100


def call_is_wide() -> bool:
    """17.2 (CALLUI): room beside a call for your chats (CallChatsSidebar)."""
    return Window.width >= dp(1100) and not IS_MOBILE


class CallChatsSidebar(BoxLayout):
    """Your chats beside a call on a wide screen (17.2, CALLUI): a tap
    sets the call aside, in its floating window, and opens the chat."""

    WIDTH = dp(300)

    def __init__(self, app: "FextApp", **kw) -> None:
        kw.setdefault("orientation", "vertical")
        kw.setdefault("size_hint_x", None)
        kw.setdefault("width", self.WIDTH)
        kw.setdefault("padding", [dp(8), dp(12), dp(8), dp(8)])
        super().__init__(**kw)
        self.app = app
        paint_round(self, T.surface, radius=0)
        self.add_widget(CapsLabel(tr("Chats"), size=10.5, color=T.text_3,
                                  tracking=0.16, size_hint_y=None,
                                  height=dp(24)))
        scroll = ScrollView(do_scroll_x=False)
        self.rows = BoxLayout(orientation="vertical", size_hint_y=None,
                              spacing=dp(2))
        self.rows.bind(minimum_height=self.rows.setter("height"))
        scroll.add_widget(self.rows)
        self.add_widget(scroll)
        self.refresh()

    def refresh(self) -> None:
        app = self.app
        self.rows.clear_widgets()
        if app.store is None:
            return
        for row in app.store.conversations(me=app.keys.address)[:60]:
            peer = row["peer"]
            name, _kind = conversation_title(app, peer)
            unread = int(row.get("unread") or 0)
            self.rows.add_widget(ListRow(
                None, name, hint=trn("{n} new", "{n} new", unread)
                if unread else "", on_tap=lambda p=peer: app.call_open_chat(p),
                padding=[dp(8), dp(4), dp(4), dp(4)]))


class CallTile(ButtonBehavior, Widget):
    """One tile of a call: someone's camera (their disc while it is off) or
    a screen they share; their name, a muted microphone, a raised hand and
    its place in the queue, a ring while they speak. A tap pins it."""

    def __init__(self, session: "CallSession", user: str, track: str,
                 frames: Callable = _no_frames, name: str = "",
                 disc: float = dp(72), on_pin: Optional[Callable] = None,
                 **kw) -> None:
        super().__init__(**kw)
        self.session, self.user, self.track = session, user, track
        self.frames = frames
        mine = user == session.me.user
        person = name or user[:8]
        self.avatar = Avatar(user, person, diameter=disc)
        self.add_widget(self.avatar)
        if track == "s":
            caption = tr("Your screen") if mine else \
                tr("{name}'s screen", name=person)
        else:
            caption = tr("You") if mine else person
        self.caption = single_line(caption, fs(13.5), T.text,
                                   size_hint=(None, None))
        self.add_widget(self.caption)
        # A raised hand's place in the queue: 1 was raised first.
        self.place = single_line("", fs(14), T.on_accent, bold=True,
                                 size_hint=(None, None),
                                 size=(dp(24), dp(24)), halign="center")
        self.add_widget(self.place)
        # 17.2: an emoji someone reacted with, over their tile a while.
        self.reaction = Label(text="", font_size=sp(40),
                              size_hint=(None, None), size=(dp(60), dp(60)))
        self.add_widget(self.reaction)
        if on_pin is not None:
            self.bind(on_release=lambda _w: on_pin(user, track))
        self.bind(pos=self.refresh, size=self.refresh)

    def member(self) -> Optional["CallMember"]:
        if self.user == self.session.me.user:
            return self.session.me
        return self.session.members.get(self.user)

    def refresh(self, *_a) -> None:
        m = self.member()
        sending = m is not None and (m.camera if self.track == "v"
                                     else m.screen)
        tex = self.frames(self.user, self.track) if sending else None
        x, y, w, h = self.x, self.y, self.width, self.height
        r = corner(min(dp(14), w / 4, h / 4))
        muted = m is not None and self.track == "v" and not m.mic
        lh = line_height(13.5)
        self.caption.text_size = (None, None)
        self.caption.texture_update()
        cw = min(self.caption.texture_size[0] + dp(6),
                 max(dp(20), w - dp(60)))
        inset = dp(22) if muted else 0
        self.canvas.before.clear()
        self.canvas.after.clear()
        with self.canvas.before:
            Color(*C(T.surface_hi))
            SmoothRoundedRectangle(pos=self.pos, size=self.size, radius=[r])
            if tex is not None:
                tw, th = tex.size
                # A camera fills its tile; a screen is shown whole.
                k = (max if self.track == "v" else min)(w / tw, h / th)
                dw, dh = tw * k, th * k
                StencilPush()
                RoundedRectangle(pos=self.pos, size=self.size, radius=[r])
                StencilUse()
                Color(1, 1, 1, 1)
                Rectangle(texture=tex, size=(dw, dh),
                          pos=(x + (w - dw) / 2, y + (h - dh) / 2))
                StencilUnUse()
                RoundedRectangle(pos=self.pos, size=self.size, radius=[r])
                StencilPop()
            Color(*C(T.bg)[:3], .66)
            SmoothRoundedRectangle(pos=(x + dp(6), y + dp(6)),
                                   size=(cw + dp(16) + inset, lh + dp(6)),
                                   radius=[corner(dp(7))])
            if m is not None and m.hand_at and self.track == "v":
                Color(*C(T.accent))
                SmoothRoundedRectangle(pos=(x + dp(8), y + h - dp(42)),
                                       size=(dp(62), dp(34)),
                                       radius=[corner(dp(17))])
                draw_icon("hand", x + dp(26), y + h - dp(25), dp(20),
                          C(T.on_accent))
        self.avatar.opacity = 1 if tex is None and self.track == "v" else 0
        self.avatar.center = (x + w / 2, y + h / 2 + dp(4))
        self.caption.size = (cw, lh)
        self.caption.text_size = (cw, None)
        self.caption.pos = (x + dp(14) + inset, y + dp(9))
        self.reaction.text = m.reaction[0] if self.track == "v" and \
            reaction_fresh(m) else ""
        self.reaction.center = (x + w / 2, y + h - dp(40))
        hands = [p.user for p in self.session.hands()]
        up = m is not None and self.track == "v" and m.user in hands
        self.place.text = str(hands.index(m.user) + 1) if up else ""
        self.place.pos = (x + dp(40), y + h - dp(37))
        with self.canvas.after:
            if muted:
                draw_icon("mic_off", x + dp(22), y + dp(9) + lh / 2, dp(15),
                          C(T.alert))
            if self.session.speaking == self.user and self.track == "v":
                Color(*C(T.accent))
                Line(rounded_rectangle=(x + dp(1.2), y + dp(1.2),
                                        w - dp(2.4), h - dp(2.4), r),
                     width=dp(1.6))
            if self.session.pinned == (self.user, self.track):
                draw_icon("pin", x + w - dp(22), y + h - dp(22), dp(16),
                          C(T.text_2))


#: 17.2 (CALLUI): how long a reaction shows over its tile.
CALL_REACTION_SECONDS = 4.0


def reaction_fresh(member: Optional["CallMember"]) -> bool:
    return member is not None and member.reaction is not None and \
        member.reaction_seen is not None and \
        time.time() - member.reaction_seen < CALL_REACTION_SECONDS


def call_grid_columns(n: int, narrow: bool) -> int:
    """How many columns the gallery has for `n` tiles: even rows, and on a
    phone at most two side by side."""
    if n <= 1:
        return 1
    if narrow:
        return 1 if n == 2 else 2
    return 2 if n <= 4 else (3 if n <= 9 else 4)


class CallStageView(BoxLayout):
    """The call's pictures: the gallery (every tile the same size, the
    speaker ringed) or the focus view (one tile on the stage, the rest in a
    strip beneath; any tile can be pinned there)."""

    def __init__(self, session: "CallSession", frames: Callable,
                 names: Callable, on_view: Optional[Callable] = None,
                 **kw) -> None:
        kw.setdefault("orientation", "vertical")
        kw.setdefault("spacing", dp(8))
        super().__init__(**kw)
        self.session, self.frames, self.names = session, frames, names
        # 17.0: told {(user, track): tile} of the pictures in view, after
        # each change of layout or size (the relay passes only those).
        self.on_view = on_view
        self._report = Clock.create_trigger(self.report_view, 0.05)
        self._shape = None              # what the tiles were built for
        self._tiles: list = []
        self.rebuild()

    def _tile(self, user, track, disc, **kw) -> CallTile:
        tile = CallTile(self.session, user, track, self.frames,
                        self.names(user), disc=disc, on_pin=self._pin, **kw)
        tile.bind(size=lambda *_a: self._report())
        self._tiles.append(tile)
        return tile

    def report_view(self, *_a) -> None:
        """The pictures in view now: each camera that is on, and the
        others' screens (one's own shared screen is not shown back)."""
        if self.on_view is None:
            return
        shown = {}
        for tile in self._tiles:
            m = tile.member()
            sending = m is not None and (
                m.camera if tile.track == "v" else
                m.screen and m.user != self.session.me.user)
            if sending and tile.width > 1 and tile.height > 1:
                shown[(tile.user, tile.track)] = tile
        self.on_view(shown)

    def _layout(self) -> tuple:
        """Who is shown, and where (16.2): what the tiles depend on."""
        s = self.session
        star = s.stage_tile() if s.view == "focus" else None
        return (s.view, tuple(s.tiles()), call_is_narrow(), star,
                self._face(star))

    def _face(self, star: Optional[tuple]) -> Optional[str]:
        """Whose face the stage shows in its corner (17.1, multi-view): a
        shared screen's presenter's, while their camera is on, unless
        Settings › Calls says the screen alone."""
        if not star or star[1] != "s" or not presenter_face_shown():
            return None
        m = self.session.me if star[0] == self.session.me.user else \
            self.session.members.get(star[0])
        return star[0] if m is not None and m.camera else None

    def speaker_moved(self, before: Optional[str]) -> None:
        """Another voice is heard: its ring, and the last one's, redrawn —
        or, when the focus view's stage follows the speaker, the stage
        built again (16.2: rebuilding every tile took 94 ms for 16 people
        on a phone; tools/prof_call_screen.py, private)."""
        if self._layout() != self._shape:
            self.rebuild()
            return
        for tile in self._tiles:
            if tile.user in (before, self.session.speaking):
                tile.refresh()

    def _pin(self, user: str, track: str) -> None:
        if self.session.pinned == (user, track):
            self.session.unpin()
        else:
            self.session.pin(user, track)
        self.rebuild()

    def rebuild(self) -> None:
        """The tiles drawn again; built again only when who is shown, or
        where, has changed (a microphone or a hand only repaints)."""
        shape = self._layout()
        self._report()
        if shape == self._shape and self._tiles:
            for tile in self._tiles:
                tile.refresh()
            return
        self._shape, self._tiles = shape, []
        self.clear_widgets()
        tiles = self.session.tiles()
        narrow = call_is_narrow()
        if self.session.view == "focus" and len(tiles) > 1:
            star = self.session.stage_tile()
            face = self._face(star)
            stage = FloatLayout(size_hint_y=.8)
            stage.add_widget(self._tile(*star, disc=dp(104),
                                        pos_hint={"x": 0, "y": 0}))
            if face:
                stage.add_widget(self._tile(
                    face, "v", dp(34), size_hint=(.22, .28),
                    pos_hint={"right": .98, "y": .03}))
            self.add_widget(stage)
            strip = BoxLayout(spacing=dp(8), size_hint_y=.2)
            for user, track in tiles:
                if (user, track) not in (star, (face, "v")):
                    strip.add_widget(self._tile(user, track, dp(34)))
            self.add_widget(strip)
            return
        cols = call_grid_columns(len(tiles), narrow)
        rows = max(1, math.ceil(len(tiles) / cols))
        grid = GridLayout(cols=cols, spacing=dp(8))
        disc = dp(96) if rows <= 1 else (dp(72) if rows <= 2 else dp(52))
        for user, track in tiles:
            grid.add_widget(self._tile(user, track, disc))
        self.add_widget(grid)


class CallControlBar(BoxLayout):
    """The call's controls, always in view (17.2, CALLUI). On a computer, in
    three groups: the devices (the microphone and the camera, each with a
    ▾ for which one; the screen), the call's own (Raise, React, Chat,
    More), and Leave apart, with a ▾ for the host's End for everyone. On a
    phone one row: Microphone, Camera, Raise, Chat, More, Leave; the rest
    in More. Each is a full 48 dp target or more."""

    def __init__(self, screen: "ConferenceScreen", **kw) -> None:
        narrow = call_is_narrow()
        kw.setdefault("size_hint_y", None)
        kw.setdefault("height", dp(76) if narrow else dp(84))
        kw.setdefault("spacing", dp(6) if narrow else dp(10))
        kw.setdefault("padding", [dp(4) if narrow else dp(12), dp(10)])
        super().__init__(**kw)
        self.screen = screen
        # A phone's six controls at 48 dp (Android's smallest target, over
        # the spec's 44 px) fit a 360 dp screen; a computer's are larger.
        self.side = TOUCH if narrow else dp(56)
        gap = (lambda: None) if narrow else (lambda: self.add_widget(
            Widget(size_hint_x=None, width=dp(20))))     # between groups
        self.add_widget(Widget())
        self.mic = self._control("mic", tr("Microphone"), screen.toggle_mic)
        if not narrow:
            self._arrow(tr("Microphone and speaker"), screen.devices)
        self.camera = self.share = self.react = None
        if screen.session.video:                       # 17.1: voice: none
            self.camera = self._control("video", tr("Camera"),
                                        screen.toggle_camera)
            if not narrow:
                self._arrow(tr("Which camera"), screen.choose_camera)
        if not narrow:                     # a phone's is in More (18.0)
            self.share = self._control("screen", tr("Share screen"),
                                       screen.toggle_screen)
        gap()
        self.hand = self._control("hand", tr("Raise hand"),
                                  screen.toggle_hand)
        if not narrow:
            self.react = self._control("smile", tr("React"),
                                       screen.choose_reaction)
        self.chat = self._control("chat", tr("In-call chat"),
                                  screen.toggle_chat)
        self.more = self._control("more", tr("More"), screen.more)
        self.badge: Optional[UnreadBadge] = None
        gap()
        self.leave = IconButton("phone_end", tint=T.on_alert, bg=T.alert,
                                label=tr("Leave call"),
                                size=(self.side + dp(8), self.side))
        self.leave.bind(on_release=lambda _w: screen.leave())
        self.add_widget(self.leave)
        if not narrow and screen.host_ends():
            self._arrow(tr("End call for everyone"), screen.end_choices)
        self.add_widget(Widget())
        self.refresh()

    def _control(self, icon, label, action) -> IconButton:
        button = IconButton(icon, label=label, size=(self.side, self.side))
        button.bind(on_release=lambda _w: action())
        self.add_widget(button)
        return button

    def _arrow(self, label: str, action: Callable) -> None:
        """A device's ▾, or Leave's: which one, or the host's choice (40
        dp wide: a whole target, beside the button it belongs to)."""
        arrow = IconButton("chevron_down", label=label, tint=T.text_3,
                           size=(dp(40), self.side))
        arrow.bind(on_release=lambda _w: action())
        self.add_widget(arrow)

    def refresh(self, unread: int = 0) -> None:
        me = self.screen.session.me
        # Off is the state to notice: red, as calls show it everywhere.
        self.mic.set_icon("mic" if me.mic else "mic_off",
                          T.text if me.mic else T.on_alert)
        self.mic._bg_hex = T.surface_hi if me.mic else T.alert
        if self.camera is not None:
            self.camera.set_icon("video" if me.camera else "video_off",
                                 T.text if me.camera else T.on_alert)
            self.camera._bg_hex = T.surface_hi if me.camera else T.alert
        for button, on in ((self.share, me.screen),
                           (self.hand, me.hand_at is not None),
                           (self.chat, self.screen.chat_open)):
            if button is not None:
                button.set_icon(button.icon, T.on_accent if on else T.text)
                button._bg_hex = T.accent if on else T.surface_hi
        for button in (self.mic, self.camera, self.share, self.hand,
                       self.chat):
            if button is not None:
                button._redraw()
        if self.badge is not None:
            self.chat.remove_widget(self.badge)
            self.badge = None
        if unread and not self.screen.chat_open:
            # On the chat button itself, in its top corner.
            self.badge = UnreadBadge(unread)
            self.badge.texture_update()
            self.badge.width = max(self.badge.height,
                                   self.badge.texture_size[0] + dp(10))
            self.chat.add_widget(self.badge)
            self.chat.bind(pos=self._place_badge, size=self._place_badge)
            self._place_badge()

    def _place_badge(self, *_a) -> None:
        if self.badge is not None:
            self.badge.pos = (self.chat.right - self.badge.width,
                              self.chat.top - self.badge.height)


class CallChatPanel(BoxLayout):
    """The in-call chat: only for the people in the call, and no
    notification; afterwards it stays with the call's card in the chat."""

    def __init__(self, screen: "ConferenceScreen", **kw) -> None:
        kw.setdefault("orientation", "vertical")
        kw.setdefault("spacing", dp(6))
        kw.setdefault("padding", [dp(14), dp(10), dp(14), dp(12)])
        super().__init__(**kw)
        self.screen = screen
        paint_round(self, T.surface, radius=dp(16))
        head = BoxLayout(size_hint_y=None, height=TOUCH)
        head.add_widget(single_line(tr("In-call chat"), fs(18), T.text,
                                    bold=True))
        close = IconButton("close", label=tr("Close"))
        close.bind(on_release=lambda _w: screen.toggle_chat())
        head.add_widget(close)
        self.add_widget(head)
        self.add_widget(InfoLabel(
            tr("Seen by the people in the call. It stays with the call's "
               "card in the chat."), color=T.text_3, font_size=fs(13)))
        self.scroll = ScrollView(do_scroll_x=False)
        self.list = BoxLayout(orientation="vertical", size_hint_y=None,
                              spacing=dp(10), padding=[0, dp(8)])
        self.list.bind(minimum_height=self.list.setter("height"))
        self.scroll.add_widget(self.list)
        self.add_widget(self.scroll)
        row = BoxLayout(size_hint_y=None, height=TOUCH, spacing=dp(6))
        self.field = TextInput(hint_text=tr("Message everyone in the call"),
                               multiline=False, font_size=fs(15),
                               background_color=C(T.surface_hi),
                               foreground_color=C(T.text),
                               hint_text_color=C(T.text_3),
                               cursor_color=C(T.accent),
                               padding=[dp(12), dp(12)])
        self.field.bind(on_text_validate=lambda _w: self._send())
        row.add_widget(self.field)
        send = IconButton("send", tint=T.on_accent, bg=T.accent,
                          label=tr("Send"))
        send.bind(on_release=lambda _w: self._send())
        row.add_widget(send)
        self.add_widget(row)
        for msg in screen.chat_messages:
            self.show(msg)

    def show(self, msg: dict) -> None:
        box = BoxLayout(orientation="vertical", size_hint_y=None,
                        spacing=dp(2))
        who = single_line(f"{msg['name']}  ·  {msg.get('time', '')}",
                          fs(12.5), T.text_3)
        body = InfoLabel(msg["text"], font_size=fs(15), color=T.text)
        box.add_widget(who)
        box.add_widget(body)
        body.bind(height=lambda _w, v: setattr(
            box, "height", v + who.height + dp(2)))
        box.height = body.height + who.height + dp(2)
        self.list.add_widget(box)

    def _send(self) -> None:
        text = self.field.text.strip()
        if text:
            self.field.text = ""
            self.screen.send_chat(text)


class ConferenceScreen(ModalView):
    """A call in progress, 1-to-1 or a group's: the pictures (gallery or
    focus), the controls, and the in-call chat beside them (over them on a
    phone)."""

    def __init__(self, app, session: "CallSession",
                 frames: Callable = _no_frames,
                 names: Optional[Callable] = None,
                 title: str = "", chat_messages: Optional[list] = None,
                 **kw) -> None:
        super().__init__(size_hint=(1, 1), auto_dismiss=False,
                         background_color=(0, 0, 0, 0),
                         overlay_color=(0, 0, 0, 0), **kw)
        self.app, self.session, self.frames = app, session, frames
        self.names = names or (lambda user: user[:8])
        self.title = title
        self.chat_messages = list(chat_messages or [])
        self.chat_open = False
        self.unread = 0
        # The call code's: this device's state to publish; an in-call
        # message to send; leave; the host's "End call for everyone".
        self.on_publish: Optional[Callable] = None
        self.on_chat: Optional[Callable] = None
        self.on_leave: Optional[Callable] = None
        self.on_end: Optional[Callable] = None
        # Where the sound can go now ([(key, label)]), and going there.
        self.on_routes: Optional[Callable] = None
        self.on_route: Optional[Callable] = None
        # Set aside (16.2): the call goes on under a bar at the top.
        self.on_aside: Optional[Callable] = None
        self.root = BoxLayout(orientation="vertical",
                              padding=[dp(12), dp(8), dp(12), 0])
        paint_round(self.root, T.bg, radius=0)
        sidebar = getattr(app, "call_chats_sidebar", None)
        if call_is_wide() and sidebar is not None:  # 17.2: chats beside
            beside = BoxLayout()
            beside.add_widget(sidebar())
            beside.add_widget(self.root)
            self.add_widget(beside)
        else:
            self.add_widget(self.root)
        session.follow_screens()          # 17.2: a screen shared already
        self.build()
        self._clock = Clock.schedule_interval(lambda _dt: self._tick(), 1)

    # -- layout ---------------------------------------------------------------------
    def build(self) -> None:
        self.root.clear_widgets()
        narrow = call_is_narrow()
        head = BoxLayout(size_hint_y=None, height=dp(56), spacing=dp(4))
        if self.session.group:
            back = IconButton("back", label=tr("Back"))
            back.bind(on_release=lambda _w: self.set_aside())
            head.add_widget(back)
        words = BoxLayout(orientation="vertical")
        words.add_widget(single_line(self.title or call_kind_label(
            self.session), fs(17), T.text, bold=True))
        self.clock_label = single_line("", fs(13.5), T.text_2)
        words.add_widget(self.clock_label)
        head.add_widget(words)
        self.meter = CallMeter(lambda: self.app.show_call_meter(),
                               pos_hint={"center_y": .5})      # 17.2, F16
        head.add_widget(self.meter)
        if call_recording_allowed() and not narrow:
            self.record_button = IconButton("record", label=tr("Record"))
            self.record_button.bind(
                on_release=lambda _w: self.app.toggle_recording())
            head.add_widget(self.record_button)
        if narrow:
            more = IconButton("more", label=tr("More"))
            more.bind(on_release=lambda _w: self.more())
            head.add_widget(more)
        else:
            for icon, view, label in (("grid", "grid", tr("Gallery")),
                                      ("stage", "focus", tr("Focus"))):
                b = IconButton(icon, label=label,
                               tint=T.accent if self.session.view == view
                               else T.text_3)
                b.bind(on_release=lambda _w, v=view: self.set_view(v))
                head.add_widget(b)
            if self.host_choices():
                more = IconButton("more", label=tr("More"))
                more.bind(on_release=lambda _w: MenuSheet(
                    self.host_choices()).open())
                head.add_widget(more)
        self.root.add_widget(head)
        body = FloatLayout() if narrow else BoxLayout(spacing=dp(12))
        self.stage = CallStageView(self.session, self.frames, self.names,
                                   on_view=getattr(self.app, "call_view",
                                                   None),
                                   pos_hint={"x": 0, "y": 0})
        body.add_widget(self.stage)
        self.chat_panel = None
        if self.chat_open:
            self.chat_panel = CallChatPanel(self)
            if narrow:
                self.chat_panel.size_hint = (1, .86)
                self.chat_panel.pos_hint = {"x": 0, "y": 0}
            else:
                self.chat_panel.size_hint_x = None
                self.chat_panel.width = dp(330)
            body.add_widget(self.chat_panel)
        self.root.add_widget(body)
        self.controls = CallControlBar(self)
        self.root.add_widget(self.controls)
        self.controls.refresh(self.unread)
        self._tick()

    def refresh(self) -> None:
        """Who is in the call changed, or what they send."""
        if self.session.follow_screens():
            self.build()                  # 17.2: the view a screen asks for
            return
        self.stage.rebuild()
        self.controls.refresh(self.unread)
        self._tick()

    def _tick(self) -> None:
        n = self.session.count()
        self.clock_label.text = ("● " + tr("Recording") + " · "
                                 if self.session.recording() else "") + \
            tr("{clock} · {n} in the call",
               clock=call_clock(self.session.duration()), n=n)
        for tile in self.stage._tiles:          # 17.2: a reaction fades
            if tile.reaction.text and not reaction_fresh(tile.member()):
                tile.refresh()
        meter = getattr(self.app, "call_meter", None)
        numbers = meter() if meter is not None else {}
        rtt = numbers.get("rtt")
        self.meter.set(meter_bars(numbers.get("way", ""), rtt),
                       tr("{ms} ms", ms=int(rtt)) if rtt is not None else "")

    def set_view(self, view: str) -> None:
        self.session.view, self.session.view_chosen = view, True
        if view == "grid":
            self.session.unpin()
        self.build()

    def more(self) -> None:
        """More (17.2, CALLUI): what is not in the bar, without leaving the
        call: the people in it, React (a phone's), the view, the call's
        way and time, recording, sound and devices, the host's asks, and
        Settings (the call goes on, aside)."""
        s = self.session
        items = [("group", tr("People ({n})", n=s.count()), self.people)]
        if call_is_narrow():
            items.append(("smile", tr("React"), self.choose_reaction))
            if not call_video_why_not("s"):      # 18.0: a phone's screen
                items.append(("screen", tr("Stop sharing your screen")
                              if s.me.screen else tr("Share your screen"),
                              self.toggle_screen))
        items += [("grid", tr("Gallery view"), lambda: self.set_view("grid")),
                  ("stage", tr("Focus view"), lambda: self.set_view("focus")),
                  ("clock", tr("The call's way and time"),
                   self.app.show_call_meter)]
        if call_recording_allowed():
            items.append(("record", tr("Stop recording") if s.me.recording
                          else tr("Record the call"),
                          self.app.toggle_recording))
        items.append(("speaker", tr("Sound and devices"), self.devices))
        copy_link = getattr(self.app, "copy_call_link", None)
        if s.group and s.room and copy_link is not None and \
                gid_of(s.chat):                               # CALLLINK
            items.append(("link", tr("Copy the call's link"),
                          lambda: copy_link(s)))
        if s.group and s.room and s.me.role == "host" and \
                hasattr(self.app, "join_link_for"):           # 18.0
            asks = len(self.app.store.join_asks("call", s.id))
            items.append(("person_add", tr("Invite with a link"),
                          lambda: JoinLinkSheet(self.app, "call",
                                                s.id).open()))
            if asks:
                items.append(("hand", tr("Asking to join ({n})", n=asks),
                              lambda: JoinAsksSheet.show(self.app, "call",
                                                         s.id)))
        items += self.host_choices()
        items.append(("sliders", tr("Settings"), self.settings))
        MenuSheet(items).open()

    def people(self) -> None:
        """Who is in the call: their microphone, camera and hand."""
        rows = []
        for member in [self.session.me] + list(self.session.members.values()):
            mine = member is self.session.me
            what = [tr("Host") if member.role == "host" else "",
                    tr("Microphone on") if member.mic else tr("Muted"),
                    tr("Camera on") if member.camera else "",
                    tr("Hand raised") if member.hand_at else ""]
            rows.append(("person", (tr("You") if mine else
                                    self.names(member.user)) + " · " +
                         ", ".join(w for w in what if w), lambda: None))
        MenuSheet(rows, title=tr("People ({n})", n=len(rows))).open()

    def choose_reaction(self) -> None:
        ReactionSheet(self.react).open()

    def react(self, emoji: str) -> None:
        """An emoji over your tile, for everyone, for a few seconds."""
        self._published(self.session.react(emoji))
        self.stage.rebuild()
        Clock.schedule_once(lambda _dt: self._published(
            self.session.clear_reaction()), CALL_REACTION_SECONDS)

    def choose_camera(self) -> None:
        """The camera's ▾: which camera (a camera on now changes at once)."""
        def chosen() -> None:
            if self.session.me.camera:            # off and on: the new one
                self.toggle_camera()
                self.toggle_camera()
        choose_camera(self.app, chosen)

    def host_ends(self) -> bool:
        s = self.session
        return s.group and s.me.role == "host" and self.on_end is not None

    def end_choices(self) -> None:
        """Leave's ▾, the host's: end it for everyone."""
        MenuSheet([("phone_end", tr("End call for everyone"), self.on_end),
                   ("back", tr("Leave the call"), self._leave)]).open()

    def settings(self) -> None:
        """Settings, the call aside (a group's) and going on."""
        self.set_aside()
        open_settings = getattr(self.app, "open_settings", None)
        if open_settings is not None:
            open_settings()

    def show_recording(self) -> None:
        """A red mark while anyone records the call (F13)."""
        on = self.session.recording()
        self.clock_label.color = C(T.alert if on else T.text_2)
        self._tick()
        button = getattr(self, "record_button", None)
        if button is not None:
            button.set_icon("record", T.alert if self.session.me.recording
                            else T.text)

    def host_choices(self) -> list:
        """The host's, in a group's call (16.2): everyone muted, every
        hand lowered — each can turn theirs back on."""
        s = self.session
        if not (s.group and s.joined and s.me.role == "host"):
            return []
        return [("mic_off", tr("Mute everyone"),
                 lambda: self.ask_everyone("mute")),
                ("hand", tr("Lower all hands"),
                 lambda: self.ask_everyone("hands"))]

    def ask_everyone(self, what: str) -> None:
        self._published(self.session.ask_everyone(what))
        self.app._set_status(tr("Everyone is asked to mute") if
                             what == "mute" else tr("Every hand is lowered"),
                             T.text_2)

    def set_aside(self) -> None:
        """Back to the chats; the call goes on (16.2), and no picture is
        passed while it is out of sight (17.0)."""
        if self.on_aside is not None:
            self.on_aside()
            if self.stage.on_view is not None:
                self.stage.on_view({})

    def devices(self) -> None:
        """Where the sound goes (a phone: earpiece, speaker, headset), or
        a computer's microphone and speaker for the next call."""
        routes = self.on_routes() if self.on_routes is not None else []
        if routes:
            MenuSheet([({"speaker": "speaker", "bluetooth": "bluetooth"}
                        .get(key, "phone"), label,
                        lambda k=key: self.on_route(k))
                       for key, label in routes], title=tr("Sound")).open()
        elif not IS_MOBILE:
            MenuSheet([(icon, tr(title), lambda k=kind: choose_sound_device(
                self.app, k, self._next_call))
                for kind, icon, title in (("input", "mic", N_("Microphone")),
                                          ("output", "speaker",
                                           N_("Speaker")))],
                title=tr("Sound and devices")).open()

    def _next_call(self) -> None:
        self.app._set_status(tr("Used from the next call on"), T.text_2)

    # -- this device's controls --------------------------------------------------------
    def _published(self, state: Optional[dict]) -> None:
        if state is not None and self.on_publish is not None:
            self.on_publish(state)
        self.controls.refresh(self.unread)
        self.stage.rebuild()

    def toggle_mic(self) -> None:
        self._published(self.session.set_mic(not self.session.me.mic))

    def toggle_camera(self) -> None:
        self._toggle_video("v")

    def toggle_screen(self) -> None:
        self._toggle_video("s")

    def _toggle_video(self, track: str) -> None:
        """This device's camera ('v') or screen ('s') on or off (17.0): on
        once it has opened, the others told then. A voice call has no
        camera (17.1)."""
        if track == "v" and not self.session.video:
            return
        me = self.session.me
        on = me.camera if track == "v" else me.screen
        switch = self.session.set_camera if track == "v" else \
            self.session.set_screen
        if on:
            self.app.stop_call_video(track)
            self._published(switch(False))
            return

        def started(why: str) -> None:
            if why:
                self.app._set_status(why, T.text_2)
            elif self.session.joined:
                self._published(switch(True))
        self.app.start_call_video(self.session, track, started)

    def video_stopped(self, track: str) -> None:
        """This device's camera or screen stopped by itself."""
        switch = self.session.set_camera if track == "v" else \
            self.session.set_screen
        self._published(switch(False))

    def toggle_hand(self) -> None:
        if self.session.me.hand_at is None:
            self._published(self.session.raise_hand())
        else:
            self._published(self.session.lower_hand())

    def toggle_chat(self) -> None:
        self.chat_open = not self.chat_open
        if self.chat_open:
            self.unread = 0
        self.build()

    def send_chat(self, text: str) -> None:
        if self.on_chat is not None:
            self.on_chat(text)      # its line comes back, numbered
            return
        msg = {"name": tr("You"), "text": text,
               "time": time.strftime("%H:%M")}
        self.receive_chat(msg, mine=True)

    def receive_chat(self, msg: dict, mine: bool = False) -> None:
        self.chat_messages.append(msg)
        if self.chat_panel is not None:
            self.chat_panel.show(msg)
        elif not mine:
            self.unread += 1
            self.controls.refresh(self.unread)

    def leave(self) -> None:
        """The red button. The host of a group's call that others are in
        is asked: leave it to them, or end it for everyone."""
        s = self.session
        if call_is_narrow() and self.host_ends() and s.members:
            self.end_choices()
            return
        self._leave()

    def _leave(self) -> None:
        if self.on_leave is not None:
            self.on_leave()
            return
        self.session.leave()
        self.close()

    def close(self) -> None:
        self._clock.cancel()
        self.stage.on_view = None         # no picture asked for once gone
        self.dismiss()

    def on_open(self) -> None:
        self.stage.report_view()          # back from aside: pictures again


class AboutButton(IconButton):
    """An ⓘ (17.2): what the thing beside it does, said in a toast on a
    tap, and on a computer as the pointer comes over it."""

    def __init__(self, about: str, **kw) -> None:
        kw.setdefault("tint", T.text_3)
        super().__init__("info", label=tr("What is this?"), **kw)
        self.about = about
        self._over = False
        self.bind(on_release=lambda _w: Toast.say(about))
        if not IS_MOBILE:
            Window.bind(mouse_pos=self._pointer)

    def _pointer(self, _window, pos) -> None:
        if self.get_root_window() is None:
            Window.unbind(mouse_pos=self._pointer)    # gone with its screen
            return
        over = self.collide_point(*self.to_widget(*pos))
        if over and not self._over:
            Toast.say(self.about)
        self._over = over


class CallLobby(ModalView):
    """Before joining (16.1, the spec's 2.2): what the others will see,
    the camera and the microphone (both off until turned on), the devices,
    then "Start call" or "Confirm & join". Nothing is sent from here."""

    def __init__(self, app, session: "CallSession",
                 frames: Callable = _no_frames, name: str = "",
                 title: str = "", on_join: Optional[Callable] = None,
                 devices: Optional[list] = None,
                 on_cancel: Optional[Callable] = None, **kw) -> None:
        super().__init__(size_hint=(1, 1), auto_dismiss=False,
                         background_color=(0, 0, 0, 0),
                         overlay_color=(0, 0, 0, 0), **kw)
        self.app, self.session, self.frames = app, session, frames
        self.on_join, self.on_cancel = on_join, on_cancel
        self.devices = devices if devices is not None else \
            call_device_rows(app, session.video)    # 17.1: voice: no camera
        session.preview()
        # A column a hand's span wide on a computer, the width of a phone.
        side = max(dp(20), (Window.width - dp(620)) / 2)
        root = BoxLayout(orientation="vertical", spacing=dp(10),
                         padding=[side, dp(12), side, dp(20)])
        paint_round(root, T.bg, radius=0)
        head = BoxLayout(size_hint_y=None, height=TOUCH)
        back = IconButton("close", label=tr("Cancel"))
        back.bind(on_release=lambda _w: self.cancel())
        head.add_widget(back)
        head.add_widget(single_line(title or call_kind_label(session),
                                    fs(18), T.text, bold=True))
        root.add_widget(head)
        root.add_widget(CapsLabel(tr("What others will see"), size=10.5,
                                  color=T.text_3, tracking=0.16,
                                  size_hint_y=None, height=dp(20)))
        frame = AnchorLayout()
        self.tile = CallTile(session, session.me.user, "v", frames,
                             name or tr("You"), disc=dp(104),
                             size_hint=(None, None))
        frame.bind(size=self._fit_tile)
        frame.add_widget(self.tile)
        self.frame = frame
        root.add_widget(frame)
        toggles = BoxLayout(size_hint_y=None, height=dp(86), spacing=dp(24))
        toggles.add_widget(Widget())
        self.camera_button = self.camera_caption = None
        if session.video:
            self.camera_button, self.camera_caption = self._toggle(
                toggles, "video_off", self.toggle_camera)
        self.mic_button, self.mic_caption = self._toggle(
            toggles, "mic_off", self.toggle_mic)
        toggles.add_widget(Widget())
        root.add_widget(toggles)
        for icon, what, chosen, action, *about in self.devices:
            root.add_widget(ListRow(icon, what, hint=chosen,
                                    chevron=action is not None,
                                    on_tap=action or (lambda: None),
                                    about=about[0] if about else ""))
        root.add_widget(InfoLabel(
            tr("Your camera and microphone stay off until you turn them "
               "on. Nothing is sent before you join.") if session.video else
            tr("Your microphone stays off until you turn it on. Nothing is "
               "sent before you join."),
            color=T.text_3, font_size=fs(13.5), halign="center"))
        start = session.me.role == "host" and session.stage == "lobby" \
            and not session.members
        self.join_button = Btn(tr("Start call") if start
                               else tr("Confirm & join"),
                               size_hint_y=None, height=dp(52))
        self.join_button.bind(on_release=lambda _w: self.join())
        root.add_widget(self.join_button)
        self.add_widget(root)
        self.refresh()
        # 17.0: a video call one starts opens with the camera on (VIDEO);
        # one joins with it off until turned on.
        if session.video and start and not session.me.camera:
            Clock.schedule_once(lambda _dt: self.toggle_camera(), 0)

    def _toggle(self, row, icon, action) -> tuple:
        box = BoxLayout(orientation="vertical", size_hint_x=None,
                        width=dp(112), spacing=dp(2))
        button = IconButton(icon, tint=T.on_alert, bg=T.alert,
                            size=(dp(60), dp(60)),
                            pos_hint={"center_x": .5})
        button.bind(on_release=lambda _w: action())
        caption = single_line("", fs(13), T.text_2, halign="center")
        box.add_widget(button)
        box.add_widget(caption)
        row.add_widget(box)
        return button, caption

    def _fit_tile(self, frame, size) -> None:
        w, h = size
        # 16:10 on a computer; a phone's portrait 3:4.
        ratio = 1.6 if not call_is_narrow() else 0.75
        tw = min(w, h * ratio)
        self.tile.size = (tw, tw / ratio)

    def refresh(self) -> None:
        me = self.session.me
        for button, caption, on, icon, words in (
                (self.camera_button, self.camera_caption, me.camera, "video",
                 (tr("Camera on"), tr("Camera off"))),
                (self.mic_button, self.mic_caption, me.mic, "mic",
                 (tr("Microphone on"), tr("Microphone off")))):
            if button is None:
                continue
            button.set_icon(icon if on else icon + "_off",
                            T.text if on else T.on_alert)
            button._bg_hex = T.surface_hi if on else T.alert
            button._redraw()
            caption.text = words[0] if on else words[1]
        self.tile.refresh()

    def toggle_camera(self) -> None:
        """The camera on (its picture here, 17.0) or off; a voice call has
        none (17.1)."""
        if self.camera_button is None:
            return
        me = self.session.me
        view = getattr(self.app, "call_view", None)
        if me.camera:
            self.app.stop_call_video("v")
            self.session.set_camera(False)
            self.refresh()
            return

        def started(why: str) -> None:
            if why:
                self.app._set_status(why, T.text_2)
                return
            self.session.set_camera(True)
            self.refresh()
            if view is not None:
                view({(me.user, "v"): self.tile})
        self.app.start_call_video(self.session, "v", started)

    def video_stopped(self, _track: str) -> None:
        self.session.set_camera(False)
        self.refresh()

    def toggle_mic(self) -> None:
        self.session.set_mic(not self.session.me.mic)
        self.refresh()

    def join(self) -> None:
        state = self.session.confirm_join()
        if state is None:
            return
        self.dismiss()
        if self.on_join is not None:
            self.on_join(self.session, state)

    def cancel(self) -> None:
        self.session.move("left" if self.session.group else "ended")
        self.dismiss()
        if self.on_cancel is not None:
            self.on_cancel(self.session)


def call_disc(video: bool, lit: bool) -> Widget:
    """A call's round mark on its card: voice or video, in the accent
    while it can be joined (a group's call, a planned call)."""
    disc = Widget(size_hint=(None, None), size=(dp(40), dp(40)))

    def paint(w, *_a):
        w.canvas.before.clear()
        with w.canvas.before:
            Color(*C(T.accent if lit else T.rule_strong))
            SmoothEllipse(pos=w.pos, size=w.size)
            draw_icon("video" if video else "phone", w.center_x, w.center_y,
                      dp(20), C(T.on_accent if lit else T.text_2))
    disc.bind(pos=paint, size=paint)
    return disc


class CallCard(BoxLayout):
    """A call's card in its chat (16.1, `invite_to_join`): while it lasts,
    the kind of call, its clock, who is in it and "Preview & join"; once
    over, "Call ended" with its length, and the in-call chat folded under
    it."""

    WIDTH = dp(330)

    def __init__(self, session: "CallSession", names: Callable,
                 on_join: Optional[Callable] = None,
                 chat_messages: Optional[list] = None,
                 on_fetch: Optional[Callable] = None,
                 on_call_back: Optional[Callable] = None,
                 on_note: Optional[Callable] = None, notes: int = 0,
                 **kw) -> None:
        kw.setdefault("orientation", "vertical")
        kw.setdefault("size_hint", (None, None))
        kw.setdefault("width", self.WIDTH)
        kw.setdefault("padding", [dp(16), dp(14)])
        kw.setdefault("spacing", dp(10))
        super().__init__(**kw)
        self.session, self.names, self.on_join = session, names, on_join
        self.on_fetch = on_fetch      # (session): the chat this device lacks
        self.on_call_back = on_call_back      # (session): 17.1, 1-to-1
        # 18.0: (session) a note on it; how many a group's call has
        self.on_note, self.notes = on_note, notes
        self.chat_messages = list(chat_messages or [])
        self.drawer_open = False
        paint_round(self, T.surface_hi, radius=dp(16))
        self.bind(minimum_height=self.setter("height"))
        self.build()

    def build(self) -> None:
        self.clear_widgets()
        s = self.session
        live = s.live
        missed = not s.group and s.outcome == "missed"
        top = BoxLayout(size_hint_y=None, height=dp(40), spacing=dp(12))
        if s.group:
            top.add_widget(call_disc(s.video, live))
            title = call_kind_label(s) if live else tr("Call ended")
        else:
            # 17.1: who called — their picture, or this device's own —
            # the kind of call on a badge at its corner.
            top.add_widget(caller_face(
                s.host, self.names(s.host), s.video,
                T.accent if live else T.alert if missed else T.rule_strong))
            title = direct_card_title(s, self.names(s.chat))
        words = BoxLayout(orientation="vertical")
        words.add_widget(single_line(title, fs(16),
                                     T.alert if missed else T.text,
                                     bold=True))
        self.clock_label = single_line("", fs(13.5), T.text_2)
        words.add_widget(self.clock_label)
        top.add_widget(words)
        self.add_widget(top)
        if live:
            people = BoxLayout(size_hint_y=None, height=dp(30),
                               spacing=-dp(8))
            # A group's: who is in it. A 1-to-1 call's: the other person,
            # ringing until this device is in it.
            shown = [m.user for m in s.everyone()[:4]] if s.group \
                else [s.chat]
            for user in shown:
                people.add_widget(Avatar(user, self.names(user),
                                         diameter=dp(30)))
            people.add_widget(Widget(size_hint_x=None, width=dp(24)))
            people.add_widget(single_line(
                tr("{n} in the call", n=s.count()) if s.group else
                tr("In the call") if s.answered else tr("Ringing…"),
                fs(13.5), T.text_2))
            self.add_widget(people)
            join = Btn(tr("Preview & join"), size_hint_y=None,
                       height=dp(46))
            if self.on_join is not None:
                join.bind(on_release=lambda _w: self.on_join(s))
            self.add_widget(join)
        rest = s.summary.split("\n", 1)[1:] if not live else []
        if rest:                 # how a 1-to-1 call went (its first line
            self.add_widget(InfoLabel(rest[0], font_size=fs(13.5),
                                      color=T.text_2))   # is the clock's)
        if not live and s.outcome not in CALL_HAD and \
                self.on_call_back is not None:
            again = Btn(tr("Call again") if s.me.role == "host" else
                        tr("Call back"), size_hint_y=None, height=dp(46))
            again.bind(on_release=lambda _w: self.on_call_back(s))
            self.add_widget(again)
        if not live and not s.group and self.on_note is not None and \
                s.outcome not in CALL_HAD:                 # 18.0: a note
            note = Btn(tr("Leave a note"), kind="quiet", size_hint_y=None,
                       height=dp(46))
            note.bind(on_release=lambda _w: self.on_note(s))
            self.add_widget(note)
        if not live and s.group and self.on_note is not None:
            self.add_widget(ListRow(
                "edit", tr("Notes"), trn("{n} note", "{n} notes",
                                         self.notes) if self.notes else
                tr("Leave the first"), chevron=True,
                on_tap=lambda: self.on_note(s),
                padding=[0, dp(4), 0, dp(4)]))
        if not live and (self.chat_messages or s.chat_count):
            fold = ListRow("chat", tr("View in-call chat ({n} messages)",
                                      n=max(s.chat_count,
                                            len(self.chat_messages))),
                           control=None, chevron=True,
                           on_tap=self.toggle_drawer,
                           padding=[0, dp(4), 0, dp(4)])
            self.add_widget(fold)
            if self.drawer_open:
                for msg in self.chat_messages:
                    line = InfoLabel(f"{msg['name']}: {msg['text']}",
                                     font_size=fs(14), color=T.text_2)
                    self.add_widget(line)
        self.refresh()

    def refresh(self, *_a) -> None:
        s = self.session
        if s.live:
            self.clock_label.text = call_clock(s.duration())
        elif s.outcome == "answered":                  # 17.1's cards
            self.clock_label.text = tr("Lasted {clock}",
                                       clock=call_clock(s.duration()))
        elif s.outcome == "missed":      # the title says it: when it was
            self.clock_label.text = pretty_time(datetime.fromtimestamp(
                s.started_at, timezone.utc).isoformat())
        elif s.summary:          # "No answer"; before 17.1 "Outgoing call
            self.clock_label.text = s.summary.split("\n", 1)[0]  # · 12:04"
        elif s.duration():
            self.clock_label.text = tr("Lasted {clock}",
                                       clock=call_clock(s.duration()))
        else:                      # how long it went on is not known
            self.clock_label.text = ""

    def toggle_drawer(self) -> None:
        self.drawer_open = not self.drawer_open
        if self.drawer_open and self.on_fetch is not None and \
                len(self.chat_messages) < self.session.chat_count:
            self.on_fetch(self.session)
        self.build()


def caller_face(user: str, name: str, video: bool, tone: str) -> Widget:
    """Who made a 1-to-1 call (17.1, its card): their picture in a disc,
    with a phone or a camera on a badge at its corner in `tone`."""
    box = Widget(size_hint=(None, None), size=(dp(40), dp(40)))
    face = Avatar(user, name, diameter=dp(40))
    box.add_widget(face)
    ink = T.text_2 if tone == T.rule_strong else T.on_accent

    def place(*_a):
        face.pos = box.pos
        box.canvas.after.clear()
        r = dp(9)
        cx, cy = box.right - r + dp(3), box.y + r - dp(3)
        with box.canvas.after:
            Color(*C(T.surface_hi))            # the card's own ground,
            SmoothEllipse(pos=(cx - r - dp(2), cy - r - dp(2)),  # a ring
                          size=(2 * r + dp(4), 2 * r + dp(4)))
            Color(*C(tone))
            SmoothEllipse(pos=(cx - r, cy - r), size=(2 * r, 2 * r))
            draw_icon("video" if video else "phone", cx, cy, dp(11), C(ink))
    box.bind(pos=place, size=place)
    place()
    return box


